                    CREATE FUNCTION [dbo].[ufnUtility_GetPreviousSundayDate]() 

                    RETURNS date AS

                    BEGIN

	                    RETURN DATEADD("day", -7, dbo.ufnUtility_GetSundayDate(getdate()))
                    END
