CREATE VIEW [dbo].[AnalyticsDimAttendanceLocation]
AS
SELECT l.Id [LocationId]
	,l.NAME
	,l.Street1 [Street1]
	,l.Street2 [Street2]
	,l.City [City]
	,l.County [County]
	,l.[State] [State]
	,l.Country [Country]
	,l.PostalCode [PostalCode]
	,l.GeoPoint [GeoPoint]
	,l.GeoFence [GeoFence]
	,l.GeoPoint.Lat [Latitude]
	,l.GeoPoint.Long [Longitude]
	,CONCAT (
		l.[Street1]
		,' '
		,+ l.[Street2]
		,' '
		,l.[City]
		,', '
		,l.[State]
		,' '
		,l.[PostalCode]
		) [FullAddress]
	,1 [Count]
FROM [Location] l
