/*
<doc>
	<summary>
 		This function returns the grade offset given a graduation date. The offset can then be used with defined value to find grade
	</summary>

	<returns>
		The grade offset based on graduation date
	</returns>
	<remarks>
		
	</remarks>
	<code>
		SELECT [dbo].[ufnCrm_GetGradeOffset]( 2018, null )
	</code>
</doc>
*/

CREATE FUNCTION [dbo].[ufnCrm_GetGradeOffset](@GraduationYear int, @TransitionDate datetime ) 

RETURNS INT WITH SCHEMABINDING AS

BEGIN

	DECLARE @Offset INT

	IF @GraduationYear IS NOT NULL
	BEGIN

		DECLARE @today DATETIME = DATEADD(day, DATEDIFF(day, 0, GETDATE()), 0)
		DECLARE @year INT = DATEPART(year, @today)

		IF @TransitionDate IS NULL
		BEGIN
			SET @TransitionDate = CAST(CAST(@year AS varchar) + '-06-01' AS DATETIME)
		END
		ELSE
		BEGIN
			SET @TransitionDate = CAST(CAST(@year AS varchar) + '-' + CAST(DATEPART(month,@TransitionDate) AS varchar) + '-' + CAST(DATEPART(day,@TransitionDate) AS varchar) AS DATETIME)
		END

		IF @today >= @TransitionDate
		BEGIN
			SET @year = @year + 1
		END

		SET @Offset = @GraduationYear - @year

	END
		
	RETURN @Offset

END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/*
<doc>
	<summary>

        *** THIS FUNCTION IS OBSOLETE.  PLEASE USE STRING_SPLIT(@YourString, ',') INSTEAD. ***

 		This function converts a comma-delimited string of values into a table of values
        The original version came from http://www.sqlservercentral.com/articles/Tally+Table/72993/
	</summary>
	<returns>
		* id
	</returns>
	<remarks>
        (Previously) Used by:
            * spFinance_ContributionStatementQuery
            * spFinance_GivingAnalyticsQuery_AccountTotals
            * spFinance_GivingAnalyticsQuery_PersonSummary
            * spFinance_GivingAnalyticsQuery_TransactionData
            * spCheckin_AttendanceAnalyticsQuery_AttendeeDates
            * spCheckin_AttendanceAnalyticsQuery_AttendeeFirstDates
            * spCheckin_AttendanceAnalyticsQuery_AttendeeLastAttendance
            * spCheckin_AttendanceAnalyticsQuery_Attendees
            * spCheckin_AttendanceAnalyticsQuery_NonAttendees
	</remarks>
	<code>
		SELECT * FROM [dbo].[ufnUtility_CsvToTable]('1,3,7,11,13') 
	</code>
</doc>
*/

/* #Obsolete# - Use STRING_SPLIT() instead */

CREATE FUNCTION [dbo].[ufnUtility_CsvToTable] 
(
 @pString VARCHAR(MAX)
)
RETURNS TABLE WITH SCHEMABINDING AS
RETURN
    SELECT Item = TRY_CONVERT(INT, LTRIM(RTRIM(value)))
    FROM STRING_SPLIT(@pString, ',');
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*
<doc>
	<summary>
 		This function returns the First and Last Sunday Date between the @StartDate and @EndDate.
        Note: If the @StartDate and @EndDate are within the same SundayWeek, there are no SundayDates between them, so this will return an [EndSundayDate] that is a week before the [StartSundayDate]
	</summary>
	<code>
		SELECT [dbo].[ufnUtility_GetSundayDateRange]('2019-09-17 00:00:00', '2019-10-09 00:00:00')
        -- should return '2019-09-22 00:00:00', '2019-10-06 00:00:00' (assuming FirstDayOfWeek is set to Monday)
	</code>
</doc>
*/
CREATE FUNCTION [dbo].[ufnUtility_GetSundayDateRange] (
	@StartDate DATETIME
	,@EndDate DATETIME
	)
RETURNS TABLE
AS
RETURN

SELECT isnull(x.[StartSundayDate], '1900-01-01') [StartSundayDate]
	,CASE 
		WHEN x.[EndSundayDate] IS NULL
			THEN '9999-12-31'
		WHEN x.[EndSundayDate] > @EndDate
			THEN DateAdd(day, - 7, x.[EndSundayDate])
		ELSE @EndDate
		END [EndSundayDate]
FROM (
	SELECT dbo.ufnUtility_GetSundayDate(@StartDate) [StartSundayDate]
		,dbo.ufnUtility_GetSundayDate(@EndDate) [EndSundayDate]
	) x
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*
<doc>
	<summary>
 		This function returns a list of Sundays between two dates
	</summary>

	<returns>
		* SundayDate - datetime
	</returns>
	<remarks>
		WARNING: Depending if you are asking for more than 100 weeks you'll need to add OPTION (MAXRECURSION 1000) to your call 
	</remarks>
	<code>
		SELECT * FROM [dbo].[ufnUtility_GetSundaysBetweenDates](DATEADD(week, -24, getdate()), getdate())
	</code>
</doc>
*/


CREATE FUNCTION [dbo].[ufnUtility_GetSundaysBetweenDates](@StartDate datetime, @EndDate datetime)
RETURNS TABLE AS

RETURN ( WITH
	
	cteAllDates AS
	(
		SELECT dbo.ufnUtility_GetSundayDate(@StartDate) AS DateOf
			UNION ALL
			SELECT DATEADD(day, 7, DateOf)
				FROM cteAllDates
				WHERE
				DATEADD(day, 7, DateOf) <= @EndDate
	)

	-- select out Sundays in a way that works across SQL Server setups
	SELECT DateOf AS [SundayDate]
		FROM cteAllDates  )
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
