SET QUOTED_IDENTIFIER ON
GO
-- truncate table [AnalyticsSourceFinancialTransaction]
-- EXECUTE [dbo].[spAnalytics_ETL_FinancialTransaction] 
CREATE PROCEDURE [dbo].[spAnalytics_ETL_FinancialTransaction]
AS
BEGIN
    DECLARE @MinDateTime DATETIME = DATEFROMPARTS(1900, 1, 1)
        ,@EtlDateTime DATETIME = SysDateTime();

    -- insert records into [AnalyticsSourceFinancialTransaction] from the source FinancialTransaction/FinancialTransactionDetail 
    -- tables that haven't been added yet
    INSERT INTO [dbo].[AnalyticsSourceFinancialTransaction] (
        [TransactionKey]
        ,[TransactionDateKey]
        ,[TransactionDateTime]
        ,[TransactionCode]
        ,[Summary]
        ,[TransactionTypeValueId]
        ,[SourceTypeValueId]
        ,[IsScheduled]
        ,[TransactionFrequency]
        ,[AuthorizedPersonAliasId]
        ,[ProcessedByPersonAliasId]
        ,[ProcessedDateTime]
        ,[GivingGroupId]
        ,[GivingId]
        ,[BatchId]
        ,[FinancialGatewayId]
        ,[EntityTypeId]
        ,[EntityId]
        ,[TransactionId]
        ,[TransactionDetailId]
        ,[AccountId]
        ,[CurrencyTypeValueId]
        ,[CreditCardTypeValueId]
        ,[DaysSinceLastTransactionOfType]
        ,[IsFirstTransactionOfType]
        ,[AuthorizedFamilyId]
        ,[Count]
        ,[Amount]
        ,[ModifiedDateTime]
        ,[Guid]
        )
    SELECT CONCAT (
            ft.Id
            ,'_'
            ,ftd.Id
            ) [TransactionKey]
        ,convert(INT, (convert(CHAR(8), ft.TransactionDateTime, 112))) [TransactionDateKey]
        ,ft.TransactionDateTime
        ,ft.TransactionCode [TransactionCode]
        ,ft.Summary [TransactionSummary]
        ,ft.TransactionTypeValueId [TransactionTypeValueId]
        ,ft.SourceTypeValueId [SourceTypeValueId]
        ,CASE 
            WHEN ft.ScheduledTransactionId IS NULL
                THEN 0
            ELSE 1
            END [IsScheduled]
        ,dvtf.Value [TransactionFrequency]
        ,ft.AuthorizedPersonAliasId
        ,ft.ProcessedByPersonAliasId
        ,ft.ProcessedDateTime
        ,p.GivingGroupId
        ,p.GivingId
        ,ft.BatchId
        ,ft.FinancialGatewayId
        ,ftd.EntityTypeId
        ,ftd.EntityId
        ,ft.Id [TransactionId]
        ,ftd.Id [TransactionDetailId]
        ,ftd.AccountId
        ,fpd.CurrencyTypeValueId
        ,fpd.CreditCardTypeValueId
        ,NULL [DaysSinceLastTransactionOfType] -- come back and fill this in later
        ,0 [IsFirstTransactionOfType] -- come back and fill this in later
        ,NULL [AuthorizedFamilyId] -- TODo: fill this in later
        ,1 [Count]
        ,ftd.Amount [Amount]
        ,@EtlDateTime [ModifiedDateTime]
        ,NEWID() [Guid]
    FROM FinancialTransaction ft
    JOIN FinancialTransactionDetail ftd ON ftd.TransactionId = ft.Id
    JOIN PersonAlias paAuthorizedPerson ON ft.AuthorizedPersonAliasId = paAuthorizedPerson.Id
    JOIN Person p ON p.Id = paAuthorizedPerson.PersonId
    LEFT JOIN EntityType et ON ftd.EntityTypeId = et.Id
    LEFT JOIN FinancialPaymentDetail fpd ON ft.FinancialPaymentDetailId = fpd.Id
    LEFT JOIN FinancialScheduledTransaction fst ON ft.ScheduledTransactionId = fst.Id
    LEFT JOIN DefinedValue dvtf ON fst.TransactionFrequencyValueId = dvtf.Id
    WHERE ft.TransactionDateTime > @MinDateTime
        AND ftd.Id NOT IN (
            SELECT TransactionDetailId
            FROM AnalyticsSourceFinancialTransaction
            )

    -- remove records from AnalyticsSourceFinancialTransaction that no longer exist in the source FinancialTransaction/FinancialTransactionDetail tables
    DELETE
    FROM AnalyticsSourceFinancialTransaction
    WHERE TransactionDetailId NOT IN (select Id from FinancialTransactionDetail)

    -- figure out IsFirstTransaction
    UPDATE AnalyticsSourceFinancialTransaction
    SET IsFirstTransactionOfType = 1
        ,DaysSinceLastTransactionOfType = NULL
    WHERE Id IN (
            SELECT asft.Id
            FROM (
                SELECT min(ft.TransactionDateTime) [DateTimeOfFirstTransactionOfType]
                    ,ft.TransactionTypeValueId
                    ,ft.GivingId
                FROM AnalyticsSourceFinancialTransaction ft
                GROUP BY ft.TransactionTypeValueId
                    ,GivingId
                ) firstTran
            CROSS APPLY (
                SELECT min(asft.Id) [Id]
                FROM AnalyticsSourceFinancialTransaction asft
                WHERE asft.GivingId = firstTran.GivingId
                    AND asft.TransactionTypeValueId = firstTran.TransactionTypeValueId
                    AND asft.TransactionDateTime = firstTran.DateTimeOfFirstTransactionOfType
                ) asft
            )
        AND IsFirstTransactionOfType != 1

    -- Update [DaysSinceLastTransactionOfType]
    -- get the number of days since the last transaction of this giving group of the same TransactionType
    -- but don't count it as a previous transaction if it was on the same date
    -- To optimize, add a WHERE DaysSinceLastTransactionOfType is NULL, but at the risk of the number being wrong due to a new transaction with an earlier date getting added 
    UPDATE asft
    SET DaysSinceLastTransactionOfType = x.[CalcDaysSinceLastTransactionOfType]
    FROM AnalyticsSourceFinancialTransaction asft
    CROSS APPLY (
        SELECT TOP 1 DATEDIFF(day, previousTran.TransactionDateTime, asft.TransactionDateTime) [CalcDaysSinceLastTransactionOfType]
        FROM AnalyticsSourceFinancialTransaction previousTran
        WHERE previousTran.GivingId = asft.GivingId
            AND previousTran.TransactionTypeValueId = asft.TransactionTypeValueId
            AND convert(DATE, previousTran.TransactionDateTime) < convert(DATE, asft.TransactionDateTime)
        ORDER BY previousTran.TransactionDateTime DESC
        ) x
    WHERE isnull(asft.DaysSinceLastTransactionOfType, 0) != x.CalcDaysSinceLastTransactionOfType

    -- update just in case any records where modified since originally inserted
    UPDATE asft
    SET asft.[TransactionKey] = x.[TransactionKey]
        ,asft.[TransactionDateKey] = x.[TransactionDateKey]
        ,asft.[TransactionDateTime] = x.[TransactionDateTime]
        ,asft.[TransactionCode] = x.[TransactionCode]
        ,asft.[Summary] = x.[Summary]
        ,asft.[TransactionTypeValueId] = x.[TransactionTypeValueId]
        ,asft.[SourceTypeValueId] = x.[SourceTypeValueId]
        ,asft.[IsScheduled] = x.[IsScheduled]
        ,asft.[TransactionFrequency] = x.[TransactionFrequency]
        ,asft.[AuthorizedPersonAliasId] = x.[AuthorizedPersonAliasId]
        ,asft.[ProcessedByPersonAliasId] = x.[ProcessedByPersonAliasId]
        ,asft.[ProcessedDateTime] = x.[ProcessedDateTime]
        ,asft.[GivingGroupId] = x.[GivingGroupId]
        ,asft.[GivingId] = x.[GivingId]
        ,asft.[BatchId] = x.[BatchId]
        ,asft.[FinancialGatewayId] = x.[FinancialGatewayId]
        ,asft.[EntityTypeId] = x.[EntityTypeId]
        ,asft.[EntityId] = x.[EntityId]
        ,asft.[AccountId] = x.[AccountId]
        ,asft.[CurrencyTypeValueId] = x.[CurrencyTypeValueId]
        ,asft.[CreditCardTypeValueId] = x.[CreditCardTypeValueId]
        ,asft.[AuthorizedFamilyId] = x.[AuthorizedFamilyId]
        ,asft.[Amount] = x.[Amount]
		,asft.ModifiedDateTime = @EtlDateTime
    FROM [AnalyticsSourceFinancialTransaction] asft
    JOIN (
        SELECT CONCAT (
                ft.Id
                ,'_'
                ,ftd.Id
                ) [TransactionKey]
            ,convert(INT, (convert(CHAR(8), ft.TransactionDateTime, 112))) [TransactionDateKey]
            ,ft.TransactionDateTime
            ,ft.TransactionCode [TransactionCode]
            ,ft.Summary [Summary]
            ,ft.TransactionTypeValueId [TransactionTypeValueId]
            ,ft.SourceTypeValueId [SourceTypeValueId]
            ,CASE 
                WHEN ft.ScheduledTransactionId IS NULL
                    THEN 0
                ELSE 1
                END [IsScheduled]
            ,dvtf.Value [TransactionFrequency]
            ,ft.AuthorizedPersonAliasId
            ,ft.ProcessedByPersonAliasId
            ,ft.ProcessedDateTime
            ,p.GivingGroupId
            ,p.GivingId
            ,ft.BatchId
            ,ft.FinancialGatewayId
            ,ftd.EntityTypeId
            ,ftd.EntityId
            ,ft.Id [TransactionId]
            ,ftd.Id [TransactionDetailId]
            ,ftd.AccountId
            ,fpd.CurrencyTypeValueId
            ,fpd.CreditCardTypeValueId
            ,NULL [DaysSinceLastTransactionOfType] -- come back and fill this in later
            ,0 [IsFirstTransactionOfType] -- come back and fill this in later
            ,NULL [AuthorizedFamilyId] -- TODo: fill this in later
            ,1 [Count]
            ,ftd.Amount [Amount]
            ,@EtlDateTime [ModifiedDateTime]
            ,NEWID() [Guid]
        FROM FinancialTransaction ft
        JOIN FinancialTransactionDetail ftd ON ftd.TransactionId = ft.Id
        JOIN PersonAlias paAuthorizedPerson ON ft.AuthorizedPersonAliasId = paAuthorizedPerson.Id
        JOIN Person p ON p.Id = paAuthorizedPerson.PersonId
        LEFT JOIN EntityType et ON ftd.EntityTypeId = et.Id
        LEFT JOIN FinancialPaymentDetail fpd ON ft.FinancialPaymentDetailId = fpd.Id
        LEFT JOIN FinancialScheduledTransaction fst ON ft.ScheduledTransactionId = fst.Id
        LEFT JOIN DefinedValue dvtf ON fst.TransactionFrequencyValueId = dvtf.Id
        WHERE ft.TransactionDateTime > @MinDateTime
        ) x ON x.[TransactionKey] = asft.[TransactionKey]
        AND (
            asft.[TransactionKey] != x.[TransactionKey]
            OR asft.[TransactionDateKey] != x.[TransactionDateKey]
            OR asft.[TransactionDateTime] != x.[TransactionDateTime]
            OR asft.[TransactionCode] != x.[TransactionCode]
            OR asft.[Summary] != x.[Summary]
            OR asft.[TransactionTypeValueId] != x.[TransactionTypeValueId]
            OR asft.[SourceTypeValueId] != x.[SourceTypeValueId]
            OR asft.[IsScheduled] != x.[IsScheduled]
            OR asft.[TransactionFrequency] != x.[TransactionFrequency]
            OR asft.[AuthorizedPersonAliasId] != x.[AuthorizedPersonAliasId]
            OR asft.[ProcessedByPersonAliasId] != x.[ProcessedByPersonAliasId]
            OR asft.[ProcessedDateTime] != x.[ProcessedDateTime]
            OR asft.[GivingGroupId] != x.[GivingGroupId]
            OR asft.[GivingId] != x.[GivingId]
            OR asft.[BatchId] != x.[BatchId]
            OR asft.[FinancialGatewayId] != x.[FinancialGatewayId]
            OR asft.[EntityTypeId] != x.[EntityTypeId]
            OR asft.[EntityId] != x.[EntityId]
            OR asft.[AccountId] != x.[AccountId]
            OR asft.[CurrencyTypeValueId] != x.[CurrencyTypeValueId]
            OR asft.[CreditCardTypeValueId] != x.[CreditCardTypeValueId]
            OR asft.[AuthorizedFamilyId] != x.[AuthorizedFamilyId]
            OR asft.[Amount] != x.[Amount]
            )

    /* Updating these PersonKeys depends on AnalyticsSourcePersonHistorical getting populated and updated. 
  -- It is probably best to schedule the ETL of AnalyticsSourcePersonHistorical to occur before spAnalytics_ETL_FinancialTransaction
  -- However, if not, it will catch up on the next run of spAnalytics_ETL_FinancialTransaction
  */
    -- Update PersonKeys for whatever PersonKey the person had at the time of the transaction
    UPDATE asft
    SET [AuthorizedPersonKey] = x.PersonKey
    FROM AnalyticsSourceFinancialTransaction asft
    CROSS APPLY (
        SELECT TOP 1 ph.Id [PersonKey]
        FROM AnalyticsSourcePersonHistorical ph
        JOIN PersonAlias pa ON asft.AuthorizedPersonAliasId = pa.Id
        WHERE ph.PersonId = pa.PersonId
            AND asft.[TransactionDateTime] < ph.[ExpireDate]
        ORDER BY ph.[ExpireDate] DESC
        ) x
    WHERE isnull(asft.AuthorizedPersonKey, 0) != x.PersonKey

    -- Update PersonKeys and AuthorizedFamilyId for whatever PersonKey/FamilyId is current right now
    UPDATE asft
    SET [AuthorizedCurrentPersonKey] = x.PersonKey
        ,[AuthorizedFamilyId] = x.PrimaryFamilyId
    FROM AnalyticsSourceFinancialTransaction asft
    CROSS APPLY (
        SELECT TOP 1 pc.Id [PersonKey]
            ,pc.PrimaryFamilyId
        FROM AnalyticsDimPersonCurrent pc
        JOIN PersonAlias pa ON asft.AuthorizedPersonAliasId = pa.Id
        WHERE pc.PersonId = pa.PersonId
        ) x
    WHERE isnull(asft.AuthorizedCurrentPersonKey, 0) != x.PersonKey
        OR (isnull(asft.AuthorizedFamilyId, 0) != x.PrimaryFamilyId)
END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/*
<doc>
	<summary>
 		This function returns attendee person ids and the dates they attended based on selected filter criteria
	</summary>

	<returns>
		* PersonId
		* SundayDate
		* MonthDate
		* Year Date
	</returns>
	<param name='GroupTypeId' datatype='int'>The Check-in Area Group Type Id (only attendance for this are will be included</param>
	<param name='StartDate' datatype='datetime'>Beginning date range filter</param>
	<param name='EndDate' datatype='datetime'>Ending date range filter</param>
	<param name='GroupIds' datatype='varchar(max)'>Optional list of group ids to limit attendance to</param>
	<param name='CampusIds' datatype='varchar(max)'>Optional list of campus ids to limit attendance to</param>
	<param name='IncludeNullCampusIds' datatype='bit'>Flag indicating if attendance not tied to campus should be included</param>
	<remarks>	
	</remarks>
	<code>
		EXEC [dbo].[spCheckin_AttendanceAnalyticsQuery_AttendeeDates] '24,25,26,27,28,29,30,31,32,56,57,58,59,111,112,113,114,115,116,117,118', '2019-09-17 00:00:00', '2019-10-12 00:00:00', null, 0, null
	</code>
</doc>
*/
CREATE PROCEDURE [dbo].[spCheckin_AttendanceAnalyticsQuery_AttendeeDates] @GroupIds VARCHAR(max)
	,@StartDate DATETIME = NULL
	,@EndDate DATETIME = NULL
	,@CampusIds VARCHAR(max) = NULL
	,@IncludeNullCampusIds BIT = 0
	,@ScheduleIds VARCHAR(max) = NULL
	WITH RECOMPILE
AS
BEGIN
	--  get the SundayDates within the StartDate and EndDate so we can query against AttendanceOccurrence.SundayDate
	DECLARE @startDateSundayDate DATE
	DECLARE @endDateSundayDate DATE

	SELECT @startDateSundayDate = x.StartSundayDate
		,@endDateSundayDate = x.EndSundayDate
	FROM dbo.ufnUtility_GetSundayDateRange(@StartDate, @EndDate) x

	DECLARE @CampusTbl TABLE ([Id] INT)

	INSERT INTO @CampusTbl
	SELECT value
	FROM STRING_SPLIT(@CampusIds, ',')

	DECLARE @ScheduleTbl TABLE ([Id] INT)

	INSERT INTO @ScheduleTbl
	SELECT value
	FROM STRING_SPLIT(@ScheduleIds, ',')

	DECLARE @GroupTbl TABLE ([Id] INT)

	INSERT INTO @GroupTbl
	SELECT value
	FROM STRING_SPLIT(@GroupIds, ',')

	-- Get all the attendance
	SELECT PA.[PersonId]
		,A.[SundayDate]
		,DATEADD(day, - (DATEPART(day, [SundayDate])) + 1, [SundayDate]) AS [MonthDate]
		,DATEADD(day, - (DATEPART(dayofyear, [SundayDate])) + 1, [SundayDate]) AS [YearDate]
	FROM (
		SELECT [PersonAliasId]
			,O.[GroupId]
			,[CampusId]
			,o.[SundayDate]
		FROM [Attendance] A
		INNER JOIN [AttendanceOccurrence] O ON O.[Id] = A.[OccurrenceId]
		INNER JOIN @GroupTbl [G] ON [G].[Id] = O.[GroupId]
		LEFT OUTER JOIN @CampusTbl [C] ON [C].[id] = [A].[CampusId]
		LEFT OUTER JOIN @ScheduleTbl [S] ON [S].[id] = [O].[ScheduleId]
		WHERE o.SundayDate BETWEEN @startDateSundayDate AND @endDateSundayDate AND A.[DidAttend] = 1 AND ((@CampusIds IS NULL OR [C].[Id] IS NOT NULL) OR (@IncludeNullCampusIds = 1 AND A.[CampusId] IS NULL)) AND (@ScheduleIds IS NULL OR [S].[Id] IS NOT NULL)
		) A
	INNER JOIN [PersonAlias] PA ON PA.[Id] = A.[PersonAliasId]
END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/*
<doc>
	<summary>
        This function return people who attended based on selected filter criteria and the first 5 dates they ever attended the selected group type
	</summary>

	<returns>
		* PersonId
		* TimeAttending
		* SundayDate
	</returns>
	<param name='GroupTypeIds' datatype='varchar(max)'>The Group Type Ids (only attendance for these group types will be included</param>
	<param name='StartDate' datatype='datetime'>Beginning date range filter</param>
	<param name='EndDate' datatype='datetime'>Ending date range filter</param>
	<param name='GroupIds' datatype='varchar(max)'>Optional list of group ids to limit attendance to</param>
	<param name='CampusIds' datatype='varchar(max)'>Optional list of campus ids to limit attendance to</param>
	<param name='IncludeNullCampusIds' datatype='bit'>Flag indicating if attendance not tied to campus should be included</param>
	<remarks>	
	</remarks>
	<code>
        EXEC [dbo].[spCheckin_AttendanceAnalyticsQuery_AttendeeFirstDates] '18,19,20,21,22,23,25', '24,25,26,27,28,29,30,31,32,56,57,58,59,111,112,113,114,115,116,117,118', '2019-09-17 00:00:00', '2019-10-23 00:00:00', null, 0, null
	</code>
</doc>
*/

CREATE PROCEDURE [dbo].[spCheckin_AttendanceAnalyticsQuery_AttendeeFirstDates]
	  @GroupTypeIds varchar(max)
	, @GroupIds varchar(max)
	, @StartDate datetime = NULL
	, @EndDate datetime = NULL
	, @CampusIds varchar(max) = NULL
	, @IncludeNullCampusIds bit = 0
	, @ScheduleIds varchar(max) = NULL
	WITH RECOMPILE

AS

BEGIN

    --  get the SundayDates within the StartDate and EndDate so we can query against AttendanceOccurrence.SundayDate
	DECLARE @startDateSundayDate DATE
	DECLARE @endDateSundayDate DATE

	SELECT @startDateSundayDate = x.StartSundayDate
		,@endDateSundayDate = x.EndSundayDate
	FROM dbo.ufnUtility_GetSundayDateRange(@StartDate, @EndDate) x

	DECLARE @CampusTbl TABLE ( [Id] int )
	INSERT INTO @CampusTbl SELECT value FROM STRING_SPLIT(@CampusIds,',')

	DECLARE @ScheduleTbl TABLE ( [Id] int )
	INSERT INTO @ScheduleTbl SELECT value FROM STRING_SPLIT(@ScheduleIds,',')

	DECLARE @GroupTbl TABLE ( [Id] int )
	INSERT INTO @GroupTbl SELECT value FROM STRING_SPLIT(@GroupIds,',')

	DECLARE @GroupTypeTbl TABLE ( [Id] int )
	INSERT INTO @GroupTypeTbl SELECT value FROM STRING_SPLIT(@GroupTypeIds,',')

	-- Get all the attendees
	DECLARE @PersonIdTbl TABLE ( [PersonId] INT NOT NULL )
	INSERT INTO @PersonIdTbl
	SELECT DISTINCT PA.[PersonId]
	FROM [Attendance] A
	INNER JOIN [AttendanceOccurrence] O ON O.[Id] = A.[OccurrenceId]
    INNER JOIN [PersonAlias] PA ON PA.[Id] = A.[PersonAliasId]
	INNER JOIN @GroupTbl [G] ON [G].[Id] = O.[GroupId]
	LEFT OUTER JOIN @CampusTbl [C] ON [C].[id] = [A].[CampusId]
	LEFT OUTER JOIN @ScheduleTbl [S] ON [S].[id] = [O].[ScheduleId]
    WHERE o.[SundayDate] BETWEEN @startDateSundayDate AND @endDateSundayDate
	AND [DidAttend] = 1
	AND ( 
		( @CampusIds IS NULL OR [C].[Id] IS NOT NULL ) OR  
		( @IncludeNullCampusIds = 1 AND A.[CampusId] IS NULL ) 
	)
	AND ( @ScheduleIds IS NULL OR [S].[Id] IS NOT NULL  )

	-- Get the first 5 occasions on which each person attended any of the selected group types regardless of group or campus.
	-- Multiple attendances on the same date are considered as a single occasion.
	SELECT DISTINCT
	    [PersonId]
	    , [TimeAttending]
	    , [StartDate]
	FROM (
	    SELECT 
	        [P].[Id] AS [PersonId]
	        , DENSE_RANK() OVER ( PARTITION BY [P].[Id] ORDER BY [AO].[OccurrenceDate] ) AS [TimeAttending]
	        , [AO].[OccurrenceDate] AS [StartDate]
	    FROM
	        [Attendance] [A]
	        INNER JOIN [AttendanceOccurrence] [AO] ON [AO].[Id] = [A].[OccurrenceId]
	        INNER JOIN [Group] [G] ON [G].[Id] = [AO].[GroupId]
	        INNER JOIN [PersonAlias] [PA] ON [PA].[Id] = [A].[PersonAliasId] 
	        INNER JOIN [Person] [P] ON [P].[Id] = [PA].[PersonId]
	        INNER JOIN @GroupTypeTbl [GT] ON [GT].[id] = [G].[GroupTypeId]
	    WHERE 
	        [P].[Id] IN ( SELECT [PersonId] FROM @PersonIdTbl )
	        AND [DidAttend] = 1
	) [X]
    WHERE [X].[TimeAttending] <= 5

END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/*
<doc>
	<summary>
        This function return people who attended based on selected filter criteria and the first 5 dates they ever attended the selected group type
	</summary>

	<returns>
		* PersonId
		* TimeAttending
		* SundayDate
	</returns>
	<param name='GroupTypeId' datatype='int'>The Check-in Area Group Type Id (only attendance for this are will be included</param>
	<param name='StartDate' datatype='datetime'>Beginning date range filter</param>
	<param name='EndDate' datatype='datetime'>Ending date range filter</param>
	<param name='GroupIds' datatype='varchar(max)'>Optional list of group ids to limit attendance to</param>
	<param name='CampusIds' datatype='varchar(max)'>Optional list of campus ids to limit attendance to</param>
	<param name='IncludeNullCampusIds' datatype='bit'>Flag indicating if attendance not tied to campus should be included</param>
	<remarks>	
	</remarks>
	<code>
		EXEC [dbo].[spCheckin_AttendanceAnalyticsQuery_AttendeeLastAttendance] '24,25,26,27,28,29,30,31,32,56,57,58,59,111,112,113,114,115,116,117,118', '2019-09-17 00:00:00', '2019-10-23 00:00:00', null, 0, null
                                                                               
	</code>
</doc>
*/

CREATE PROCEDURE [dbo].[spCheckin_AttendanceAnalyticsQuery_AttendeeLastAttendance]
	  @GroupIds varchar(max) 
	, @StartDate datetime = NULL
	, @EndDate datetime = NULL
	, @CampusIds varchar(max) = NULL
	, @IncludeNullCampusIds bit = 0
	, @ScheduleIds varchar(max) = NULL

AS

BEGIN

    --  get the SundayDates within the StartDate and EndDate so we can query against AttendanceOccurrence.SundayDate
	DECLARE @startDateSundayDate DATE
	DECLARE @endDateSundayDate DATE

	SELECT @startDateSundayDate = x.StartSundayDate
		,@endDateSundayDate = x.EndSundayDate
	FROM dbo.ufnUtility_GetSundayDateRange(@StartDate, @EndDate) x

	DECLARE @CampusTbl TABLE ( [Id] int )
	INSERT INTO @CampusTbl SELECT value FROM STRING_SPLIT(@CampusIds,',')

	DECLARE @ScheduleTbl TABLE ( [Id] int )
	INSERT INTO @ScheduleTbl SELECT value FROM STRING_SPLIT(@ScheduleIds,',')

	DECLARE @GroupTbl TABLE ( [Id] int )
	INSERT INTO @GroupTbl SELECT value FROM STRING_SPLIT(@GroupIds,',')

	SELECT B.[PersonId], B.[CampusId], B.[CampusName], B.[GroupId], B.[GroupName], B.[ScheduleId], B.[StartDateTime], B.[LocationId], B.[RoleName], B.[LocationName] 
	FROM
	(
		SELECT PA.[PersonId], ROW_NUMBER() OVER (PARTITION BY PA.[PersonId] ORDER BY A.[StartDateTime] DESC) AS PersonRowNumber,
			A.[CampusId], CA.[Name] AS [CampusName], O.[GroupId], G.[Name] AS [GroupName], O.[ScheduleId], A.[StartDateTime], O.[LocationId], R.[RoleName], L.[Name] AS [LocationName]
		FROM [Attendance] A
		INNER JOIN [AttendanceOccurrence] O ON O.[Id] = A.[OccurrenceId]
		INNER JOIN [PersonAlias] PA ON PA.[Id] = A.[PersonAliasId]
		INNER JOIN [Group] G ON G.[Id] = O.[GroupId]
		INNER JOIN @GroupTbl [G2] ON [G2].[Id] = G.[Id]
		OUTER APPLY (
			SELECT TOP 1 R.[Name] AS [RoleName]
			FROM [GroupMember] M 
			INNER JOIN [GroupTypeRole] R
				ON R.[Id] = M.[GroupRoleId]
			WHERE M.[GroupId] = G.[Id]
			AND M.[PersonId] = PA.[PersonId]
			AND M.[GroupMemberStatus] <> 0
			ORDER BY R.[Order]
		) R
		LEFT OUTER JOIN [Location] L
			ON L.[Id] = O.[LocationId]
		LEFT OUTER JOIN @CampusTbl [C] ON [C].[id] = [A].[CampusId]
		LEFT OUTER JOIN @ScheduleTbl [S] ON [S].[id] = [O].[ScheduleId]
		LEFT OUTER JOIN [Campus] [CA] ON [A].[CampusId] = [CA].[Id]
		WHERE o.[SundayDate] BETWEEN @startDateSundayDate AND @endDateSundayDate
		AND [DidAttend] = 1
		AND ( 
			( @CampusIds IS NULL OR [C].[Id] IS NOT NULL ) OR  
			( @IncludeNullCampusIds = 1 AND A.[CampusId] IS NULL ) 
		)
		AND ( @ScheduleIds IS NULL OR [S].[Id] IS NOT NULL  )
	) B
	WHERE B.PersonRowNumber = 1

END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/*
<doc>
	<summary>
 		This function returns the people that attended based on selected filter criteria
	</summary>

	<returns>
		* Id 
		* NickName
		* LastName
	</returns>
	<param name='GroupTypeId' datatype='int'>The Check-in Area Group Type Id (only attendance for this are will be included</param>
	<param name='StartDate' datatype='datetime'>Beginning date range filter</param>
	<param name='EndDate' datatype='datetime'>Ending date range filter</param>
	<param name='GroupIds' datatype='varchar(max)'>Optional list of group ids to limit attendance to</param>
	<param name='CampusIds' datatype='varchar(max)'>Optional list of campus ids to limit attendance to</param>
	<param name='IncludeNullCampusIds' datatype='bit'>Flag indicating if attendance not tied to campus should be included</param>
	<remarks>	
	</remarks>
	<code>
        EXEC [dbo].[spCheckin_AttendanceAnalyticsQuery_Attendees] '24,25,26,27,28,29,30,31,32,56,57,58,59,111,112,113,114,115,116,117,118', '2019-09-17 00:00:00', '2019-10-23 00:00:00', null, 0, 0, 0, null
	</code>
</doc>
*/

CREATE PROCEDURE [dbo].[spCheckin_AttendanceAnalyticsQuery_Attendees]
	  @GroupIds varchar(max)
	, @StartDate datetime = NULL
	, @EndDate datetime = NULL
	, @CampusIds varchar(max) = NULL
	, @IncludeNullCampusIds bit = 0
    , @IncludeParentsWithChild bit = 0
    , @IncludeChildrenWithParents bit = 0
	, @ScheduleIds varchar(max) = NULL
	WITH RECOMPILE

AS

BEGIN

    --  get the SundayDates within the StartDate and EndDate so we can query against AttendanceOccurrence.SundayDate
	DECLARE @startDateSundayDate DATE
	DECLARE @endDateSundayDate DATE

	SELECT @startDateSundayDate = x.StartSundayDate
		,@endDateSundayDate = x.EndSundayDate
	FROM dbo.ufnUtility_GetSundayDateRange(@StartDate, @EndDate) x

	DECLARE @CampusTbl TABLE ( [Id] int )
	INSERT INTO @CampusTbl SELECT value FROM STRING_SPLIT(@CampusIds,',')

	DECLARE @ScheduleTbl TABLE ( [Id] int )
	INSERT INTO @ScheduleTbl SELECT value FROM STRING_SPLIT(@ScheduleIds,',')

	DECLARE @GroupTbl TABLE ( [Id] int )
	INSERT INTO @GroupTbl SELECT value FROM STRING_SPLIT(@GroupIds,',')

	-- Get all the attendees
    IF @IncludeChildrenWithParents = 0 AND @IncludeParentsWithChild = 0
    BEGIN

        -- Just return the person who attended
	    SELECT	
		    P.[Id],
		    P.[NickName],
		    P.[LastName],
			P.[Gender],
		    P.[Email],
            P.[GivingId],
		    P.[BirthDate],
            P.[ConnectionStatusValueId],
			P.[GraduationYear],
			P.[DeceasedDate]
	    FROM (
		    SELECT DISTINCT PA.[PersonId]
			FROM (
				SELECT 
					A.[PersonAliasId],
					A.[CampusId],
					O.[ScheduleId]
 				FROM [Attendance] A
				INNER JOIN [AttendanceOccurrence] O ON O.[Id] = A.[OccurrenceId]
				INNER JOIN @GroupTbl G ON G.[Id] = O.[GroupId]
				WHERE o.[SundayDate] BETWEEN @startDateSundayDate AND @endDateSundayDate
				AND [DidAttend] = 1
			) A
            INNER JOIN [PersonAlias] PA ON PA.[Id] = A.[PersonAliasId]
			LEFT OUTER JOIN @CampusTbl [C] ON [C].[id] = [A].[CampusId]
			LEFT OUTER JOIN @ScheduleTbl [S] ON [S].[id] = [A].[ScheduleId]
		    WHERE ( 
			    ( @CampusIds IS NULL OR [C].[Id] IS NOT NULL ) OR  
			    ( @IncludeNullCampusIds = 1 AND A.[CampusId] IS NULL ) 
		    )
		    AND ( @ScheduleIds IS NULL OR [S].[Id] IS NOT NULL  )
	    ) [Attendee]
	    INNER JOIN [Person] P 
			ON P.[Id] = [Attendee].[PersonId]

    END
    ELSE
    BEGIN

        DECLARE @AdultRoleId INT = ( SELECT TOP 1 [Id] FROM [GroupTypeRole] WHERE [Guid] = '2639F9A5-2AAE-4E48-A8C3-4FFE86681E42' )
        DECLARE @ChildRoleId INT = ( SELECT TOP 1 [Id] FROM [GroupTypeRole] WHERE [Guid] = 'C8B1814F-6AA7-4055-B2D7-48FE20429CB9' )

        IF @IncludeParentsWithChild = 1 
   BEGIN

            -- Child attended, also include their parents
	        SELECT	
                C.[Id],
                C.[NickName],
                C.[LastName],
				C.[Gender],
                C.[Email],
                C.[GivingId],
                C.[BirthDate],
                C.[ConnectionStatusValueId],
				C.[GraduationYear],
				C.[DeceasedDate],
                A.[Id] AS [ParentId],
                A.[NickName] AS [ParentNickName],
                A.[LastName] AS [ParentLastName],
                A.[Email] AS [ParentEmail],
                A.[GivingId] as [ParentGivingId],
                A.[BirthDate] AS [ParentBirthDate],
				A.[Gender] AS [ParentGender],
				A.[DeceasedDate] AS [ParentDeceasedDate]
	        FROM (
				SELECT DISTINCT PA.[PersonId]
				FROM (
					SELECT 
						A.[PersonAliasId],
						A.[CampusId],
						O.[ScheduleId]
 					FROM [Attendance] A
					INNER JOIN [AttendanceOccurrence] O ON O.[Id] = A.[OccurrenceId]
					INNER JOIN @GroupTbl G ON G.[Id] = O.[GroupId]
					WHERE o.[SundayDate] BETWEEN @startDateSundayDate AND @endDateSundayDate
					AND [DidAttend] = 1
				) A
				INNER JOIN [PersonAlias] PA ON PA.[Id] = A.[PersonAliasId]
				LEFT OUTER JOIN @CampusTbl [C] ON [C].[id] = [A].[CampusId]
				LEFT OUTER JOIN @ScheduleTbl [S] ON [S].[id] = [A].[ScheduleId]
				WHERE ( 
					( @CampusIds IS NULL OR [C].[Id] IS NOT NULL ) OR  
					( @IncludeNullCampusIds = 1 AND A.[CampusId] IS NULL ) 
				)
				AND ( @ScheduleIds IS NULL OR [S].[Id] IS NOT NULL  )
	        ) [Attendee]
	        INNER JOIN [Person] C 
				ON C.[Id] = [Attendee].[PersonId]
            INNER JOIN [GroupMember] GMC
                ON GMC.[PersonId] = C.[Id]
	            AND GMC.[GroupRoleId] = @ChildRoleId
            INNER JOIN [GroupMember] GMA
	            ON GMA.[GroupId] = GMC.[GroupId]
	            AND GMA.[GroupRoleId] = @AdultRoleId
            INNER JOIN [Person] A 
				ON A.[Id] = GMA.[PersonId]

        END
        
        IF @IncludeChildrenWithParents = 1
        BEGIN

            -- Parents attended, include their children
	        SELECT	
                A.[Id],
                A.[NickName],
                A.[LastName],
				A.[Gender],
                A.[Email],
                A.[GivingId],
                A.[BirthDate],
                A.[ConnectionStatusValueId],
				A.[DeceasedDate],
                C.[Id] AS [ChildId],
                C.[NickName] AS [ChildNickName],
                C.[LastName] AS [ChildLastName],
                C.[Email] AS [ChildEmail],
                C.[GivingId] as [ChildGivingId],
                C.[BirthDate] AS [ChildBirthDate],
				C.[Gender] as [ChildGender],
				C.[GraduationYear] as [ChildGraduationYear],
				C.[DeceasedDate] AS [ChildDeceasedDate]
	        FROM (
				SELECT DISTINCT PA.[PersonId]
				FROM (
					SELECT 
						A.[PersonAliasId],
						A.[CampusId],
						O.[ScheduleId]
 					FROM [Attendance] A
					INNER JOIN [AttendanceOccurrence] O ON O.[Id] = A.[OccurrenceId]
					INNER JOIN @GroupTbl G ON G.[Id] = O.[GroupId]
					WHERE o.[SundayDate] BETWEEN @startDateSundayDate AND @endDateSundayDate
					AND [DidAttend] = 1
				) A
				INNER JOIN [PersonAlias] PA ON PA.[Id] = A.[PersonAliasId]
				LEFT OUTER JOIN @CampusTbl [C] ON [C].[id] = [A].[CampusId]
				LEFT OUTER JOIN @ScheduleTbl [S] ON [S].[id] = [A].[ScheduleId]
				WHERE ( 
					( @CampusIds IS NULL OR [C].[Id] IS NOT NULL ) OR  
					( @IncludeNullCampusIds = 1 AND A.[CampusId] IS NULL ) 
				)
				AND ( @ScheduleIds IS NULL OR [S].[Id] IS NOT NULL  )
	        ) [Attendee]
	        INNER JOIN [Person] A 
				ON A.[Id] = [Attendee].[PersonId]
            INNER JOIN [GroupMember] GMA
                ON GMA.[PersonId] = A.[Id]
	            AND GMA.[GroupRoleId] = @AdultRoleId
            INNER JOIN [GroupMember] GMC
	            ON GMC.[GroupId] = GMA.[GroupId]
	            AND GMC.[GroupRoleId] = @ChildRoleId
            INNER JOIN [Person] C 
				ON C.[Id] = GMC.[PersonId]

        END

    END

END
