/*
<doc>
    <summary>
         This function returns any person ids for people that have attended previously but who have not attended since the beginning date
    </summary>

    <returns>
        * PersonId 
        * SundayDate - Last time attended
    </returns>
    <param name='GroupTypeIds' datatype='varchar(max)'>The Group Type Ids (only attendance for these group types will be included</param>
    <param name='StartDateTime' datatype='datetime'>Beginning date range filter</param>
    <param name='GroupIds' datatype='varchar(max)'>Optional list of group ids to limit attendance to</param>
    <param name='CampusIds' datatype='varchar(max)'>Optional list of campus ids to limit attendance to</param>
    <param name='IncludeNullCampusIds' datatype='bit'>Flag indicating if attendance not tied to campus should be included</param>
    <remarks>    
    </remarks>
    <code>
        EXEC [dbo].[spCheckin_AttendanceAnalyticsQuery_NonAttendees] '18,19,20,21,22,23,25', '24,25,26,27,28,29,30,31,32,56,57,58,59,111,112,113,114,115,116,117,118', '2019-09-17 00:00:00', '2019-10-23 00:00:00', null, 0, null, 0, 0
    </code>
</doc>
*/

CREATE PROCEDURE [dbo].[spCheckin_AttendanceAnalyticsQuery_NonAttendees]
      @GroupTypeIds varchar(max)
    , @GroupIds varchar(max)
    , @StartDate datetime = NULL
    , @EndDate datetime = NULL
    , @CampusIds varchar(max) = NULL
    , @IncludeNullCampusIds bit = 0
    , @ScheduleIds varchar(max) = NULL
    , @IncludeParentsWithChild bit = 0
    , @IncludeChildrenWithParents bit = 0
    WITH RECOMPILE

AS

BEGIN

   	--  get the SundayDates within the StartDate and EndDate so we can query against AttendanceOccurrence.SundayDate
	DECLARE @startDateSundayDate DATE
	DECLARE @endDateSundayDate DATE

	SELECT @startDateSundayDate = x.StartSundayDate
		,@endDateSundayDate = x.EndSundayDate
	FROM dbo.ufnUtility_GetSundayDateRange(@StartDate, @EndDate) x

    DECLARE @PersonIdTbl TABLE ( [Id] INT NOT NULL )

    DECLARE @CampusTbl TABLE ( [Id] int )
    INSERT INTO @CampusTbl SELECT value FROM STRING_SPLIT(@CampusIds,',')

    DECLARE @ScheduleTbl TABLE ( [Id] int )
    INSERT INTO @ScheduleTbl SELECT value FROM STRING_SPLIT(@ScheduleIds,',')

    DECLARE @GroupTbl TABLE ( [Id] int )
    INSERT INTO @GroupTbl SELECT value FROM STRING_SPLIT(@GroupIds,',')

    DECLARE @GroupTypeTbl TABLE ( [Id] int )
    INSERT INTO @GroupTypeTbl SELECT value FROM STRING_SPLIT(@GroupTypeIds,',')

    -- Find all the person ids for people who belong to any of the selected groups and have not attended any group/campus of selected group type
    INSERT INTO @PersonIdTbl
    SELECT DISTINCT M.[PersonId]
    FROM @GroupTbl G
    INNER JOIN [GroupMember] M
        ON M.[GroupId] = G.[Id]
        AND M.[GroupMemberStatus] = 1
    WHERE M.[PersonId] NOT IN (
        SELECT DISTINCT PA.[PersonId]
        FROM (
            SELECT 
                A.[PersonAliasId],
                A.[CampusId],
                O.[ScheduleId]
             FROM [Attendance] A
            INNER JOIN [AttendanceOccurrence] O ON O.[Id] = A.[OccurrenceId]
            INNER JOIN @GroupTbl G ON G.[Id] = O.[GroupId]
            WHERE o.[SundayDate] BETWEEN @startDateSundayDate AND @endDateSundayDate
            AND [DidAttend] = 1
        ) A
        INNER JOIN [PersonAlias] PA ON PA.[Id] = A.[PersonAliasId]
        LEFT OUTER JOIN @CampusTbl [C] ON [C].[id] = [A].[CampusId]
        LEFT OUTER JOIN @ScheduleTbl [S] ON [S].[id] = [A].[ScheduleId]
        WHERE ( 
            ( @CampusIds IS NULL OR [C].[Id] IS NOT NULL ) OR  
            ( @IncludeNullCampusIds = 1 AND A.[CampusId] IS NULL ) 
        )
        AND ( @ScheduleIds IS NULL OR [S].[Id] IS NOT NULL  )
    )

    IF @IncludeChildrenWithParents = 0 AND @IncludeParentsWithChild = 0
    BEGIN

        -- Just return the person 
 SELECT    
            P.[Id],
            P.[NickName],
            P.[LastName],
            P.[Gender],
            P.[Email],
            P.[GivingId],
            P.[BirthDate],
            P.[ConnectionStatusValueId],
			P.[DeceasedDate],
			P.[GraduationYear]
        FROM @PersonIdTbl M
        INNER JOIN [Person] P ON P.[Id] = M.[Id]

    END
    ELSE
    BEGIN

        DECLARE @AdultRoleId INT = ( SELECT TOP 1 [Id] FROM [GroupTypeRole] WHERE [Guid] = '2639F9A5-2AAE-4E48-A8C3-4FFE86681E42' )
        DECLARE @ChildRoleId INT = ( SELECT TOP 1 [Id] FROM [GroupTypeRole] WHERE [Guid] = 'C8B1814F-6AA7-4055-B2D7-48FE20429CB9' )

        IF @IncludeParentsWithChild = 1 
        BEGIN

            -- Child attended, also include their parents
            SELECT    
                C.[Id],
                C.[NickName],
                C.[LastName],
                C.[Gender],
                C.[Email],
                C.[GivingId],
                C.[BirthDate],
                C.[ConnectionStatusValueId],
				C.[DeceasedDate],
				C.[GraduationYear],
                A.[Id] AS [ParentId],
                A.[NickName] AS [ParentNickName],
                A.[LastName] AS [ParentLastName],
                A.[Email] AS [ParentEmail],
                A.[GivingId] as [ParentGivingId],
                A.[BirthDate] AS [ParentBirthDate],
				A.[DeceasedDate] AS [ParentDeceasedDate],
				A.[Gender] AS [ParentGender]
            FROM @PersonIdTbl M
            INNER JOIN [Person] C 
                ON C.[Id] = M.[Id]
            INNER JOIN [GroupMember] GMC
                ON GMC.[PersonId] = C.[Id]
                AND GMC.[GroupRoleId] = @ChildRoleId
            INNER JOIN [GroupMember] GMA
                ON GMA.[GroupId] = GMC.[GroupId]
                AND GMA.[GroupRoleId] = @AdultRoleId
            INNER JOIN [Person] A 
                ON A.[Id] = GMA.[PersonId]

        END
        
        IF @IncludeChildrenWithParents = 1
        BEGIN

            -- Parents attended, include their children
            SELECT    
                A.[Id],
                A.[NickName],
                A.[LastName],
                A.[Gender],
                A.[Email],
                A.[GivingId] as [GivingId],
                A.[BirthDate],
                A.[ConnectionStatusValueId],
				A.[DeceasedDate],
                C.[Id] AS [ChildId],
                C.[NickName] AS [ChildNickName],
                C.[LastName] AS [ChildLastName],
                C.[Email] AS [ChildEmail],
                C.[GivingId] as [ChildGivingId],
                C.[BirthDate] AS [ChildBirthDate],
				C.[Gender] as [ChildGender],
				C.[GraduationYear] as [ChildGraduationYear],
				C.[DeceasedDate] AS [ChildDeceasedDate]
            FROM @PersonIdTbl M
            INNER JOIN [Person] A 
                ON A.[Id] = M.[Id]
            INNER JOIN [GroupMember] GMA
                ON GMA.[PersonId] = A.[Id]
                AND GMA.[GroupRoleId] = @AdultRoleId
            INNER JOIN [GroupMember] GMC
                ON GMC.[GroupId] = GMA.[GroupId]
                AND GMC.[GroupRoleId] = @ChildRoleId
            INNER JOIN [Person] C 
                ON C.[Id] = GMC.[PersonId]

        END

    END

    -- Get the first 5 times they attended this group type (any group or campus)
    SELECT 
        P.[Id] AS [PersonId],
        D.[TimeAttending],
        D.[StartDate]
    FROM @PersonIdTbl P
    CROSS APPLY ( 
        SELECT TOP 5 
            ROW_NUMBER() OVER (ORDER BY [StartDate]) AS [TimeAttending],
            [StartDate]
        FROM (
            SELECT DISTINCT [StartDate]
            FROM [vCheckin_GroupTypeAttendance] A
            INNER JOIN @GroupTypeTbl [G] ON [G].[id] = [A].[GroupTypeId]
            AND A.[PersonId] = P.[Id]
        ) S
    ) D

    -- Get the last time they attended
    SELECT 
        PD.[PersonId],
        PD.[CampusId],
		CA.[Name] AS [CampusName],
        PD.[GroupId],
        PD.[GroupName],
        PD.[ScheduleId],
        PD.[StartDateTime],
        PD.[LocationId],
   R.[Name] AS [RoleName],
        L.[Name] AS [LocationName]
    FROM (
        SELECT 
            P.[Id] AS [PersonId],
            A.[CampusId],
            A.[GroupId],
  A.[GroupName],
            A.[ScheduleId],
            A.[StartDateTime],
            A.[LocationId]
        FROM @PersonIdTbl P
        CROSS APPLY (
            SELECT TOP 1 
                A.[CampusId],
                A.[GroupId],
                G.[Name] AS [GroupName],
                A.[ScheduleId],
                A.[LocationId],
                A.[StartDateTime]
            FROM (
                SELECT 
                    A.[PersonAliasId],
                    A.[CampusId],
                    O.[GroupId],
                    O.[ScheduleId],
                    O.[LocationId],
                    A.[StartDateTime]
                 FROM [Attendance] A
                INNER JOIN [AttendanceOccurrence] O ON O.[Id] = A.[OccurrenceId]
                INNER JOIN @GroupTbl G ON G.[Id] = O.[GroupId]
                WHERE o.[SundayDate] < @startDateSundayDate
                AND [DidAttend] = 1
            ) A
            INNER JOIN [PersonAlias] PA ON PA.[Id] = A.[PersonAliasId] 
            INNER JOIN [Group] G ON G.[Id] = A.[GroupId]
            LEFT OUTER JOIN @CampusTbl [C] ON [C].[id] = [A].[CampusId]
            LEFT OUTER JOIN @ScheduleTbl [S] ON [S].[id] = [A].[ScheduleId]
            WHERE PA.[PersonId] = P.[Id]
            AND ( 
                ( @CampusIds IS NULL OR [C].[Id] IS NOT NULL ) OR  
                ( @IncludeNullCampusIds = 1 AND A.[CampusId] IS NULL ) 
            )
            AND ( @ScheduleIds IS NULL OR [S].[Id] IS NOT NULL  )
            ORDER BY A.[StartDateTime] DESC
        ) A
    ) PD
    OUTER APPLY (
        SELECT TOP 1 R.[Name]
        FROM [GroupMember] M 
        INNER JOIN [GroupTypeRole] R
            ON R.[Id] = M.[GroupRoleId]
        WHERE M.[GroupId] = PD.[GroupId]
        AND M.[PersonId] = PD.[PersonId]
        AND M.[GroupMemberStatus] <> 0
        ORDER BY R.[Order]
    ) R
    LEFT OUTER JOIN [Location] L
        ON L.[Id] = PD.[LocationId]
	LEFT OUTER JOIN [Campus] CA ON PD.[CampusId] = CA.[Id]
END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE[dbo].[spCheckin_BadgeAttendance]
                  @PersonId int
                  , @RoleGuid uniqueidentifier = null
                  , @ReferenceDate datetime = null
                  , @MonthCount int = 24
				  , @ShowAsIndividual bit = 0
              AS
              BEGIN
                  DECLARE @cROLE_ADULT uniqueidentifier = '2639F9A5-2AAE-4E48-A8C3-4FFE86681E42'
              
                  DECLARE @cROLE_CHILD uniqueidentifier = 'C8B1814F-6AA7-4055-B2D7-48FE20429CB9'
              
                  DECLARE @cGROUP_TYPE_FAMILY uniqueidentifier = '790E3215-3B10-442B-AF69-616C0DCB998E'
              
                  DECLARE @StartDay datetime
              
                  DECLARE @LastDay datetime

                  -- if role( adult / child ) is unknown determine it

    IF( @RoleGuid IS NULL )

    BEGIN
        SELECT TOP 1 @RoleGuid = gtr.[Guid]

            FROM[GroupTypeRole] gtr
               INNER JOIN[GroupMember] gm ON gm.[GroupRoleId] = gtr.[Id]

                INNER JOIN[Group] g ON g.[Id] = gm.[GroupId]

            WHERE gm.[PersonId] = @PersonId
AND g.[GroupTypeId] = (SELECT[ID] FROM [GroupType] WHERE[Guid] = @cGROUP_TYPE_FAMILY)

    END

	-- if start date null get today's date

    IF( @ReferenceDate IS NULL)

        SET @ReferenceDate = getdate()

    -- set data boundaries
    SET @LastDay = [dbo].[ufnUtility_GetLastDayOfMonth] (@ReferenceDate) -- last day is most recent day
SET @StartDay = DATEADD( M, DATEDIFF(M, 0, DATEADD(month, ((@MonthCount -1) * -1), @LastDay)), 0) -- start day is the 1st of the first full month of the oldest day

	-- make sure last day is not in future( in case there are errant checkin data)

    IF( @LastDay > getdate())

        SET @LastDay = getdate()

    --PRINT 'Last Day: ' + CONVERT( VARCHAR, @LastDay, 101)
	--PRINT 'Start Day: ' + CONVERT( VARCHAR, @StartDay, 101)

    DECLARE @familyMemberPersonIds table( [PersonId] int);

		IF( @RoleGuid = @cROLE_CHILD OR @ShowAsIndividual = 1 )
	        INSERT INTO @familyMemberPersonIds SELECT @PersonId
        ELSE IF( @RoleGuid = @cROLE_ADULT )
			INSERT INTO @familyMemberPersonIds SELECT[Id] FROM[dbo].[ufnCrm_FamilyMembersOfPersonId]
        (@PersonId) 

	-- query for attendance data

    SELECT
        COUNT( b.[Attended]) AS[AttendanceCount]
		, (SELECT[dbo].[ufnUtility_GetNumberOfSundaysInMonth] (DATEPART(year, b.[SundayDate]), DATEPART( month, b.[SundayDate]), 'True' )) AS[SundaysInMonth]
		, DATEPART( month, b.[SundayDate]) AS[Month]
		, DATEPART( year, b.[SundayDate]) AS[Year]
     FROM(
         SELECT
             s.[SundayDate], NULL AS [Attended]
        FROM
             dbo.ufnUtility_GetSundaysBetweenDates(@StartDay, @LastDay) s
 
         UNION ALL
 
             SELECT
                 DISTINCT ao.[SundayDate], 1 AS[Attended]
             FROM
 
                 [AttendanceOccurrence] ao
                 INNER JOIN[dbo].[ufnCheckin_WeeklyServiceGroups]() wg ON ao.[GroupId] = wg.[Id]
 
                 INNER JOIN [Attendance] a ON ao.[Id] = a.[OccurrenceId] AND a.[DidAttend] = 1
 
                 INNER JOIN [PersonAlias] pa ON a.[PersonAliasId] = pa.[Id] AND pa.[PersonId] IN (SELECT[PersonId] FROM @familyMemberPersonIds )

            WHERE
                ao.[OccurrenceDate] BETWEEN @StartDay AND @LastDay
    ) b
    GROUP BY DATEPART( month, b.[SundayDate]), DATEPART( year, b.[SundayDate])

    OPTION( MAXRECURSION 1000)
END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*
<doc>
	<summary>
 		This function returns the number of weekends a member of a family has attended a weekend service
		in the last X weeks.
	</summary>

	<returns>
		* Number of weeks
	</returns>
	<param name=""PersonId"" datatype=""int"">The person id to use</param>
	<param name=""WeekDuration"" datatype=""int"">The number of weeks to use as the duration (default 16)</param>
	<remarks>	
	</remarks>
	<code>
		EXEC [dbo].[spCheckin_WeeksAttendedInDuration] 2 -- Ted Decker
	</code>
</doc>
*/

CREATE PROCEDURE [dbo].[spCheckin_WeeksAttendedInDuration]
	@PersonId int
	,@WeekDuration int = 16
AS
BEGIN
	
    DECLARE @startSunday datetime 
    DECLARE @lastSunday datetime 

    SET @lastSunday = [dbo].[ufnUtility_GetPreviousSundayDate]()
    SET @startSunday = DATEADD(WEEK, ((@WeekDuration -1) * -1), @lastSunday)

    SELECT 
	    COUNT(DISTINCT O.SundayDate )
    FROM
	    [Attendance] a
		INNER JOIN [AttendanceOccurrence] O ON O.[Id] = A.[OccurrenceId]
	    INNER JOIN [PersonAlias] pa ON pa.[Id] = a.[PersonAliasId]
    WHERE 
	    O.[GroupId] IN (SELECT [Id] FROM [dbo].[ufnCheckin_WeeklyServiceGroups]())
	    AND O.[SundayDate] BETWEEN @startSunday AND @lastSunday
	    AND pa.[PersonId] IN (SELECT [Id] FROM [dbo].[ufnCrm_FamilyMembersOfPersonId](@PersonId))
		AND a.[DidAttend] = 1

END
