/*
<doc>
	<summary>
        This procedure takes a communication list (group) or communication and returns all of the
		recipients along with the data needed to determine if the individual can recieve an email,
		sms or push notification.
	</summary>

	<returns>
		All of the fields needed to drive the communication wizard.
	</returns>
	<param name='ListId' datatype='int'>The group id of the communication list or the communication id.</param>
	<param name='ListType' datatype='int'>1 = Communication List Id, 2 = Communication Id</param>
	<param name='MatchType' datatype='int'>1 = OR compare or 2 = AND compare</param>
	<param name='PersonalizationSegmentList' datatype='varchar(max)'>A comma separated string of personalization segment ids.</param>
	<remarks>	
	</remarks>
	<code>
        EXEC [dbo].[spCommunicationRecipientDetails] 1097001, 1, 1, '11,12'

		Sample Segments 3 = clients, 5= females, 2 = staff
	</code>
</doc>
*/
CREATE PROCEDURE [dbo].[spCommunicationRecipientDetails]
	@ListId int			-- this can be either a communication list or communication
	, @ListType int		-- 1 = Communication List, 2 = Communication
	, @MatchType int	-- 1 = OR, 2 = AND
	, @PersonalizationSegmentList nvarchar(max)   
	WITH RECOMPILE

AS

BEGIN
	DECLARE @StartTime DATETIME2, @RecipientLoadTime DATETIME2, @RecipientFilterTime DATETIME2, @ReturnResultsTime DATETIME2;
	
	SET @StartTime = SYSDATETIME();

	/* Get defined value ids for filtering */
    DECLARE @MobilePersonDeviceTypeValueId int = (SELECT TOP 1 [Id] FROM [DefinedValue] WHERE [Guid] = '5A8F264F-3BE6-4F15-912A-3CE93A98E8F6')
	DECLARE @MobilePhoneTypeValueId int = (SELECT TOP 1 [Id] FROM [DefinedValue] WHERE [Guid] = '407E7E45-7B2E-4FCD-9605-ECB1339F2453')


	/* Define temp tables for filtering */
	CREATE TABLE #RecipientList (
		[PersonId] INT PRIMARY KEY,
		[GroupCommunicationPreference] INT NULL
	);

	CREATE TABLE #PersonSegmentList (
		[PersonId] INT,
		[PersonalizationSegmentId] INT,
		PRIMARY KEY ([PersonId], [PersonalizationSegmentId])
	);

	/* Load the recipient list and filter by segment if needed */
	IF @ListType = 1 
		BEGIN
			/* Communication List Logic - This uses segments for filtering */
            ;WITH DistinctRecipients AS (
	            SELECT gm.[PersonId], gm.[CommunicationPreference], ROW_NUMBER() OVER (PARTITION BY gm.[PersonId] ORDER BY gm.[Id]) AS rn FROM [GroupMember] gm
	                INNER JOIN [Person] p ON p.[Id] = gm.[PersonId]
	            WHERE gm.[GroupId] = @ListId
		            AND p.[IsDeceased] = 0
		            AND gm.[GroupMemberStatus] = 1
                    AND gm.[IsArchived] = 0
            )
            INSERT INTO #RecipientList ([PersonId], [GroupCommunicationPreference])
            SELECT [PersonId], [CommunicationPreference] FROM DistinctRecipients
                WHERE rn = 1;

			SET @RecipientLoadTime = SYSDATETIME();

			;WITH [PersonalizationSegments] AS (
				SELECT value AS [PersonalizationSegmentId] FROM STRING_SPLIT(@PersonalizationSegmentList, ',')  -- Convert to table
			)

			/* Load the person segment table */
			INSERT INTO #PersonSegmentList
			SELECT DISTINCT p.[Id], pap.[PersonalizationEntityId] FROM [Person] p
				INNER JOIN [PersonAlias] pa ON pa.[PersonId] = p.[Id]
					INNER JOIN [PersonAliasPersonalization] pap ON pap.[PersonAliasId] = pa.[Id] 
						AND pap.[PersonalizationType] = 0
					INNER JOIN [PersonalizationSegments] ps ON ps.[PersonalizationSegmentId] = pap.[PersonalizationEntityId]
					WHERE
						p.[Id] IN (SELECT [PersonId] FROM #RecipientList)

			/* Get Count of Provided Segments */
			DECLARE @SegmentCount int = (SELECT COUNT(*) FROM STRING_SPLIT(@PersonalizationSegmentList, ',') Split WHERE Split.[value] IS NOT NULL AND Split.[value] <> '')

            IF @SegmentCount > 0
                BEGIN
			        /* Filter out based on segments using AND/OR logic */
			        IF @MatchType = 1
				        BEGIN
					        DELETE FROM #RecipientList
					        WHERE [PersonId] NOT IN (SELECT [PersonId] FROM #PersonSegmentList)
				        END
			        ELSE 
				        BEGIN
					        DELETE FROM #RecipientList
					        WHERE [PersonId] NOT IN (SELECT [PersonId] FROM #PersonSegmentList GROUP BY [PersonId] HAVING COUNT(DISTINCT [PersonalizationSegmentId]) = @SegmentCount)
				        END
                END

			SET @RecipientFilterTime = SYSDATETIME();
		END
	ELSE
		BEGIN
            ;WITH DistinctRecipients AS (
	            SELECT pa.[PersonId], ROW_NUMBER() OVER (PARTITION BY pa.[PersonId] ORDER BY cr.[Id]) AS rn FROM [CommunicationRecipient] cr 
	                INNER JOIN [PersonAlias] pa ON pa.[Id] = cr.[PersonAliasId]
	                INNER JOIN [Person] p ON p.[Id] = pa.[PersonId]
	            WHERE cr.[CommunicationId] = @ListId
		            AND p.[IsDeceased] = 0
            )
            INSERT INTO #RecipientList ([PersonId], [GroupCommunicationPreference])
                SELECT [PersonId], NULL FROM DistinctRecipients
                WHERE rn = 1;

			SET @RecipientLoadTime = SYSDATETIME();
			SET @RecipientFilterTime = SYSDATETIME();
		END

	/* Return the final result set with required data */
	SELECT 
		p.[Id]
		, CASE WHEN p.[NickName] IS NOT NULL THEN p.[NickName] ELSE p.[FirstName] END AS [NickName]
		, [LastName]
		, p.[PhotoId]
		, CAST(CASE WHEN (p.[Email] IS NULL OR p.[Email] = '' OR p.[IsEmailActive] = 0 OR p.[EmailPreference] = 2) THEN 0 ELSE 1 END AS BIT) AS [IsEmailEnabled]
		, p.[Email]
		, p.[IsEmailActive]
		, p.[EmailNote] -- possibly not needed
		, p.[ConnectionStatusValueId]
		, p.[CommunicationPreference]
		, rl.[GroupCommunicationPreference]
		, CAST(CASE WHEN (pn.[NumberFormatted] IS NULL OR pn.[IsMessagingEnabled] = 0 OR pn.[IsMessagingOptedOut] = 1) THEN 0 ELSE 1 END AS BIT) AS [IsSmsEnabled]
		, pn.[NumberFormatted] AS [MobilePhoneNumber]
		, CAST(CASE WHEN pn.[IsMessagingEnabled] IS NULL THEN 0 ELSE pn.[IsMessagingEnabled] END AS BIT) AS [IsMessagingEnabled]
		, CAST(CASE WHEN pn.[IsMessagingOptedOut] IS NULL THEN 0 ELSE pn.[IsMessagingOptedOut] END AS BIT) AS [IsMessagingOptedOut]
		, CAST(CASE WHEN (pd.[DeviceRegistrationId] IS NULL OR pd.[NotificationsEnabled] = 0) THEN 0 ELSE 1 END AS BIT) AS [IsPushEnabled]
		, pd.[DeviceRegistrationId]
		, CAST(CASE WHEN pd.[NotificationsEnabled] IS NULL THEN 0 ELSE pd.[NotificationsEnabled] END AS BIT) AS [NotificationsEnabled]
		, CAST(CASE WHEN (p.[Email] IS NULL OR p.[Email] = '' OR p.[IsEmailActive] = 0 OR p.[EmailPreference] = 2 OR p.[EmailPreference] = 1) THEN 0 ELSE 1 END AS BIT) AS [IsBulkEmailEnabled]
        , p.[EmailPreference] -- needed for disabled messaging
        , p.[RecordTypeValueId] -- needed for nameless check and full name
        , p.[SuffixValueId] -- needed for full name
        , p.[PrimaryAliasGuid]
        , p.[PrimaryAliasId]
        , p.[AgeClassification] -- needed for photo
        , p.[Age] -- needed for photo
        , p.[Gender] -- needed for photo
        
	FROM [Person] p
		INNER JOIN #RecipientList rl ON rl.[PersonId] = p.[Id]
		OUTER APPLY ( -- outer apply to ensure we only get one
			SELECT TOP 1 pn.[NumberFormatted], pn.[IsMessagingEnabled], pn.[IsMessagingOptedOut] 
			FROM [PhoneNumber] pn 
			WHERE pn.[PersonId] = p.[Id] AND pn.[NumberTypeValueId] = @MobilePhoneTypeValueId
			ORDER BY pn.[IsMessagingEnabled], pn.[IsMessagingOptedOut]
		) pn
		OUTER APPLY ( -- outer apply to ensure we only get one
			SELECT TOP 1 pd.[DeviceRegistrationId], pd.[NotificationsEnabled]
			FROM [PersonalDevice] pd 
			WHERE pd.[PersonAliasId] IN (SELECT [Id] FROM [PersonAlias] pa WHERE pa.[PersonId] = p.[Id])
			AND pd.[IsActive] = 1 AND pd.[PersonalDeviceTypeValueId] = @MobilePersonDeviceTypeValueId 
			ORDER BY [NotificationsEnabled]
		) pd
	
	WHERE p.[PrimaryAliasGuid] IS NOT NULL AND p.[PrimaryAliasId] IS NOT NULL

	SET @ReturnResultsTime = SYSDATETIME();

	PRINT 'Recipient Load: ' + CONVERT(NVARCHAR, DATEDIFF(MILLISECOND, @StartTime, @RecipientLoadTime));
	PRINT 'Recipient Filter: ' + CONVERT(NVARCHAR, DATEDIFF(MILLISECOND, @RecipientLoadTime, @RecipientFilterTime));
	PRINT 'Recipient List: ' + CONVERT(NVARCHAR, DATEDIFF(MILLISECOND, @RecipientFilterTime, @ReturnResultsTime));
END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*
<doc>
<summary>
This stored procedure returns the data for the communication saturation report.
</summary>
<param name='StartDate' datatype='date'>The starting date.</param>
<param name='EndDate' datatype='date'>The ending date.</param>
<param name='BucketSize' datatype='int'>The number of messages in the buckets.</param>
<param name='CommunicationType' datatype='int'>The type of communications to filter on (1 = Email, 2 = SMS, 3 = Push).</param>
<param name='@IncludeNonBulk' datatype='bool'>Determines if only bulk emails should be considered.</param>
<param name='DataViewId' datatype='int'>The data view to filter people on.</param>
<param name='ConnectionStatusValueId' datatype='int'>The connection type to filter on.</param>
<remarks>

</remarks>
<code>
EXEC [dbo].[spCommunication_SaturationReport] '1/1/2025', '2/1/2025'
EXEC [dbo].[spCommunication_SaturationReport] '1/1/2025', '2/1/2025', 5, 1, 1
</code>
</doc>
*/
CREATE PROCEDURE [dbo].[spCommunication_SaturationReport]
  @StartDate DATE
, @EndDate DATE
, @BucketSize int = 3 -- null means don't filter by start date
, @CommunicationType varchar(10) = '1' -- default to email, 2 is sms, 3 is push, formatted as comma-delimited list for multi-select
, @IncludeNonBulk bit = 0 -- Default to only consider bulk email
, @DataViewId int = null -- null means don't filter by a data view
, @ConnectionStatusValueId int = null -- null means all connection statuses
AS
BEGIN

/*
Create a temp table to hold our buckets. This will ensure that we return all buckets.
It's possible that if there are no individuals with the count in the buckets that the
bucket would not show otherwise. This will also help us to order the buckets and return
information about the bucket ranges.
*/
CREATE TABLE #ReportBuckets (
[Id] INT,
[LowerRange] INT,
[UpperRange] INT,
[Name] NVARCHAR(25),
[Order] INT
);

-- Get the active record status
DECLARE @ActiveRecordStatusValueId INT = (SELECT TOP 1 [Id] FROM [DefinedValue] WHERE [Guid] = '618F906C-C33D-4FA3-8AEF-E58CB7B63F1E')

-- Add bucket ranges
INSERT INTO #ReportBuckets ([Id], [LowerRange], [UpperRange], [Name], [Order])
VALUES (1, 0, 0, '0', 1)

--1
INSERT INTO #ReportBuckets ([Id], [LowerRange], [UpperRange], [Name], [Order])
VALUES (2, 1, @BucketSize,'1-' + CAST(@BucketSize AS nvarchar(5)) , 2)

--2
INSERT INTO #ReportBuckets ([Id], [LowerRange], [UpperRange], [Name], [Order])
VALUES (3, (@BucketSize + 1),(@BucketSize * 2), CAST((@BucketSize + 1) AS nvarchar(5)) + '-' + CAST((@BucketSize * 2) AS nvarchar(5)), 3)

--3
INSERT INTO #ReportBuckets ([Id], [LowerRange], [UpperRange], [Name], [Order])
VALUES (4, ((@BucketSize * 2) + 1), (@BucketSize * 3),CAST(((@BucketSize * 2) + 1) AS nvarchar(5)) + '-' + CAST((@BucketSize * 3) AS nvarchar(5)), 4)

--4
INSERT INTO #ReportBuckets ([Id], [LowerRange], [UpperRange], [Name], [Order])
VALUES (5, ((@BucketSize * 3) + 1), (@BucketSize * 4),CAST(((@BucketSize * 3) + 1) AS nvarchar(5)) + '-' + CAST((@BucketSize * 4) AS nvarchar(5)), 5)

--5
INSERT INTO #ReportBuckets ([Id], [LowerRange], [UpperRange], [Name], [Order])
VALUES (6, ((@BucketSize * 4) + 1), (@BucketSize * 5),CAST(((@BucketSize * 4) + 1) AS nvarchar(5)) + '-' + CAST((@BucketSize * 5) AS nvarchar(5)), 6)

--6
INSERT INTO #ReportBuckets ([Id], [LowerRange], [UpperRange], [Name], [Order])
VALUES (7, ((@BucketSize * 5) + 1),(@BucketSize * 6), CAST(((@BucketSize * 5) + 1) AS nvarchar(5)) + '-' + CAST((@BucketSize * 6) AS nvarchar(5)), 7)

--7
INSERT INTO #ReportBuckets ([Id], [LowerRange], [UpperRange], [Name], [Order])
VALUES (8, ((@BucketSize * 6) + 1),999999999, CAST(((@BucketSize * 6) + 1) AS nvarchar(5)) + '+', 8)

-- Query the data
SELECT
    [Name]
    , ISNULL([NumberOfRecipients], 0) AS [NumberOfRecipients] -- Ensure NULL values are replaced with 0
FROM (
    SELECT
        [MessageBucketId]
        , COUNT(*) AS [NumberOfRecipients]
    FROM (
        SELECT
            rb.[Id] AS [MessageBucketId]
        FROM (
            SELECT
                pa.[PersonId]
                , COUNT( c.[Id] ) AS [MessageCount]
            FROM [Person] p
            INNER JOIN [PersonAlias] pa ON pa.[PersonId] = p.[Id]
            LEFT OUTER JOIN [CommunicationRecipient] cr ON pa.[Id] = cr.[PersonAliasId]
            LEFT OUTER JOIN [Communication] c ON c.[Id] = cr.[CommunicationId]
                AND (c.[IsBulkCommunication] = 1 OR @IncludeNonBulk = 1)
                AND c.[SendDateTime] >= @StartDate
                AND c.[SendDateTime] < @EndDate
                AND c.[CommunicationType] IN (SELECT value FROM STRING_SPLIT(@CommunicationType, ','))
            WHERE
                p.[RecordStatusValueId] = @ActiveRecordStatusValueId
                AND p.[AgeClassification] = 1
                AND p.[RecordTypeValueId] = 1
                AND NOT (p.[FirstName] = 'Anonymous' AND p.[LastName] = 'Visitor')
                AND NOT (p.[FirstName] = 'Giver' AND p.[LastName] = 'Anonymous')
                AND (p.[ConnectionStatusValueId] = @ConnectionStatusValueId OR @ConnectionStatusValueId IS NULL)
                AND (@DataViewId IS NULL OR p.[Id] IN (SELECT [EntityId] FROM [DataViewPersistedValue] dvp WHERE dvp.[DataViewId] = @DataViewId))
            GROUP BY pa.[PersonId]
        ) AS [RecipientMessageCounts]
        INNER JOIN #ReportBuckets rb ON rb.[LowerRange] <= [RecipientMessageCounts].[MessageCount] AND rb.UpperRange >= [RecipientMessageCounts].[MessageCount]
    ) AS [Buckets]
    GROUP BY [MessageBucketId]
) AS [BucketCounts]
RIGHT OUTER JOIN #ReportBuckets rb ON rb.[Id] = [BucketCounts].MessageBucketId
ORDER BY rb.[Order]
END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*
<doc>
    <summary>
        Synchronizes the pending recipients of a communication with the current, active members of its list group,
        respecting scheduled send cutoffs, recipient/person communication preferences, and optional personalization
        segment filters.
    </summary>
    <params>
        <param name="@CommunicationId" type="INT" required="true">
            The Id of the [Communication] to synchronize.
        </param>
    </params>
    <examples>
        <code>
            -- Synchronize recipients for communication Id 123
            EXEC [dbo].[spCommunication_SynchronizeListRecipients] 123;
        </code>
    </examples>
</doc>
*/

CREATE PROCEDURE [dbo].[spCommunication_SynchronizeListRecipients]
    @CommunicationId INT
AS
BEGIN

    -- If any runtime error occurs inside this transaction, automatically abort the transaction.
    SET XACT_ABORT ON;

    -- Get data from the specified communication record needed to operate below.
    DECLARE @SendDateTime DATETIME
        , @FutureSendDateTime DATETIME
        , @ListGroupId INT
        , @HasLegacySegments BIT
        , @PersonalizationSegmentString NVARCHAR(MAX)
        , @SegmentCriteria INT
        , @CommunicationType INT;

    SELECT @SendDateTime = [SendDateTime]
        , @FutureSendDateTime = [FutureSendDateTime]
        , @ListGroupId = [ListGroupId]
        , @HasLegacySegments = CASE
            WHEN LEN([Segments]) > 0 THEN 1
            ELSE 0
          END
        , @PersonalizationSegmentString = [PersonalizationSegments]
        , @SegmentCriteria = [SegmentCriteria]
        , @CommunicationType = [CommunicationType]
    FROM [Communication]
    WHERE [Id] = @CommunicationId;

    -- If the specified communication:
    --  1) has already been sent;
    --  2) is NOT tied to a list group;
    --  3) has any legacy segments.
    -- Then there's nothing to do. Exit early.
    IF @SendDateTime IS NOT NULL OR @ListGroupId IS NULL OR @HasLegacySegments = 1
        RETURN;

    -- Ensure only a single process can synchronize a given communication's recipients at once.
    DECLARE @LockResult INT
        , @LockResource NVARCHAR(100) = CONCAT('spCommunication_SynchronizeListRecipients_', @CommunicationId);

    BEGIN TRY
        BEGIN TRAN;

        EXEC @LockResult = sp_getapplock
            @Resource = @LockResource
            , @LockMode = 'Exclusive'
            , @LockOwner = 'Transaction'
            , @LockTimeout = 90000;

        IF @LockResult < 0
            RAISERROR('Unable to acquire application lock for communication with ID %d.', 16, 1, @CommunicationId);

        -- Declare constants (Enum values, Etc.).
        DECLARE @PersonalizationTypeSegment INT = 0
            , @SegmentCriteriaAll INT = 0
            , @SegmentCriteriaAny INT = 1

            , @GroupMemberStatusActive INT = 1

            , @RecipientStatusPending INT = 0

            , @CommunicationTypeRecipientPreference INT = 0
            , @CommunicationTypeEmail INT = 1
            , @CommunicationTypeSms INT = 2
            , @CommunicationTypePush INT = 3

            , @NoCommunicationPreference INT = 0

            , @EmailMediumEntityTypeId INT = (SELECT TOP 1 [Id] FROM [EntityType] WHERE [Guid] = '5A653EBE-6803-44B4-85D2-FB7B8146D55D')
            , @SmsMediumEntityTypeId INT = (SELECT TOP 1 [Id] FROM [EntityType] WHERE [Guid] = '4BC02764-512A-4A10-ACDE-586F71D8A8BD')
            , @PushMediumEntityTypeId INT = (SELECT TOP 1 [Id] FROM [EntityType] WHERE [Guid] = '3638C6DF-4FF3-4A52-B4B8-AFB754991597');

        DECLARE @MediumEntityTypeByCommunicationTypes TABLE
        (
            [CommunicationType] INT NOT NULL
            , [MediumEntityTypeId]INT NULL
        );

        INSERT INTO @MediumEntityTypeByCommunicationTypes VALUES
            (@CommunicationTypeRecipientPreference, NULL)
            , (@CommunicationTypeEmail, @EmailMediumEntityTypeId)
            , (@CommunicationTypeSms, @SmsMediumEntityTypeId)
            , (@CommunicationTypePush, @PushMediumEntityTypeId);

        DECLARE @CommunicationMediumEntityTypeId INT = (
            SELECT TOP 1 [MediumEntityTypeId]
            FROM @MediumEntityTypeByCommunicationTypes
            WHERE [CommunicationType] = @CommunicationType
        );

        IF @CommunicationMediumEntityTypeId IS NULL
        BEGIN
            -- Default to email in case a recipient doesn't have a preference.
            SET @CommunicationMediumEntityTypeId = @EmailMediumEntityTypeId;
        END

        -- Split the communication's personalization segment IDs into a table variable for easy reference.
        DECLARE @PersonalizationSegments TABLE
        (
            [PersonalizationSegmentId] INT NOT NULL
        );

        INSERT INTO @PersonalizationSegments
        SELECT TRY_CONVERT(int, value)
        FROM STRING_SPLIT(@PersonalizationSegmentString, ',')
        WHERE TRY_CONVERT(int, value) IS NOT NULL;

        DECLARE @PersonalizationSegmentCount INT = (
            SELECT COUNT(*)
            FROM @PersonalizationSegments
            WHERE [PersonalizationSegmentId] > 0
        );

        -- Create a map from person IDs to personalization segments for this communication.
        IF OBJECT_ID('tempdb..#PersonSegmentList') IS NOT NULL
        BEGIN
            DROP TABLE #PersonSegmentList;
        END

        SELECT psl.[PersonId]
            , psl.[PersonalizationEntityId]
        INTO #PersonSegmentList
        FROM (
            SELECT DISTINCT pa.[PersonId]
                , pap.[PersonalizationEntityId]
            FROM [PersonAliasPersonalization] pap
            INNER JOIN [PersonAlias] pa
                ON pa.[Id] = pap.[PersonAliasId]
            WHERE pap.[PersonalizationType] = @PersonalizationTypeSegment
                AND pap.[PersonalizationEntityId] IN (
                    SELECT [PersonalizationSegmentId]
                    FROM @PersonalizationSegments
                )
        ) psl;

        CREATE CLUSTERED INDEX CX_PersonSegmentList
            ON #PersonSegmentList([PersonId]);

        -- Select person + primary alias ID along with communication preference for current, active list group members.
        IF OBJECT_ID('tempdb..#ListMembers') IS NOT NULL
        BEGIN
            DROP TABLE #ListMembers;
        END

        SELECT lm.[PersonId]
            , lm.[PrimaryAliasId]
            , lm.[MediumEntityTypeId]
        INTO #ListMembers
        FROM (
            SELECT p.[Id] AS [PersonId]
                , p.[PrimaryAliasId]
                , met.[MediumEntityTypeId]
                -- A person might be in the group more than once; select the earliest group member per person.
                , rn = ROW_NUMBER() OVER (PARTITION BY p.[Id] ORDER BY gm.[Id])
            FROM [GroupMember] gm
            INNER JOIN [Person] p
                ON p.[Id] = gm.[PersonId]
            LEFT OUTER JOIN @MediumEntityTypeByCommunicationTypes met
                ON met.[CommunicationType] =
                    CASE
                        WHEN gm.[CommunicationPreference] = @NoCommunicationPreference THEN p.[CommunicationPreference]
                        ELSE gm.[CommunicationPreference]
                    END
            WHERE gm.[GroupId] = @ListGroupId
                AND gm.[IsArchived] = 0
                AND gm.[GroupMemberStatus] = @GroupMemberStatusActive
                AND (
                    @FutureSendDateTime IS NULL
                    -- If this is a scheduled communication, don't include Members
                    -- that were added after the scheduled FutureSendDateTime.
                    OR COALESCE(gm.[DateTimeAdded], gm.[CreatedDateTime]) < @FutureSendDateTime
                    OR (
                        gm.[DateTimeAdded] IS NULL
                        AND gm.[CreatedDateTime] IS NULL
                    )
                )
                AND p.[IsDeceased] = 0
                AND p.[PrimaryAliasId] IS NOT NULL
                AND (
                    -- Either the communication isn't tied to any personalization segments.
                    @PersonalizationSegmentCount = 0
                    -- OR.. filter down to only those list members who are in the specified
                    -- personalization segments.
                    OR (
                        -- They must belong to at least one of the specified segments.
                        @SegmentCriteria = @SegmentCriteriaAny
                        AND EXISTS (
                            SELECT 1
                            FROM #PersonSegmentList
                            WHERE [PersonId] = gm.[PersonId]
                        )
                    )
                    OR (
                        -- They must belong to ALL of the specified segments.
                        @SegmentCriteria = @SegmentCriteriaAll
                        AND (
                            SELECT COUNT(*)
                            FROM #PersonSegmentList
                            WHERE [PersonId] = gm.[PersonId]
                        ) = @PersonalizationSegmentCount
                    )
                )
        ) lm
        WHERE lm.[rn] = 1;

        CREATE CLUSTERED INDEX CX_ListMembers
            ON #ListMembers([PersonId]);

        CREATE NONCLUSTERED INDEX IX_ListMembers_PrimaryAliasId
            ON #ListMembers([PrimaryAliasId])
            INCLUDE ([MediumEntityTypeId]);

        -- Create a map from person IDs to person alias IDs to minimize the risk of excessive table locking during the upsert.
        IF OBJECT_ID('tempdb..#PersonIdMappings') IS NOT NULL
        BEGIN
            DROP TABLE #PersonIdMappings;
        END

        SELECT pa.[PersonId]
            , pa.[Id] AS [PersonAliasId]
        INTO #PersonIdMappings
        FROM [PersonAlias] pa
        INNER JOIN #ListMembers lm
            ON lm.[PersonId] = pa.[PersonId];

        CREATE CLUSTERED INDEX CX_PersonIdMappings
            ON #PersonIdMappings([PersonId]);

        CREATE NONCLUSTERED INDEX IX_PersonIdMappings_PersonAliasId
            ON #PersonIdMappings([PersonAliasId]);

        -- Upsert current, active list members to [CommunicationRecipient] records.
        MERGE [CommunicationRecipient] AS t
        USING #ListMembers AS s
            ON t.[CommunicationId] = @CommunicationId
                AND EXISTS (
                    SELECT 1
                    FROM #PersonIdMappings pm
                    WHERE pm.[PersonId] = s.[PersonId]
                        AND pm.[PersonAliasId] = t.[PersonAliasId]
                )
        WHEN MATCHED AND t.[Status] = @RecipientStatusPending THEN
            -- Update each pending recipient to reflect their current list member or person communication
            -- preference IF the commmunication type is recipient preference; otherwise, ensure the selected
            -- medium type matches that of the communication.
            UPDATE SET t.[MediumEntityTypeId] = CASE
                    WHEN @CommunicationType = @CommunicationTypeRecipientPreference
                        AND s.[MediumEntityTypeId] IS NOT NULL
                        THEN s.[MediumEntityTypeId]
                    ELSE @CommunicationMediumEntityTypeId
                    END
                , [ModifiedDateTime] = GETDATE()
        WHEN NOT MATCHED BY TARGET THEN
            -- Add new [CommunicationRecipient] records for list members not yet reflected in this table.
            INSERT
            (
                [CommunicationId]
                , [Status]
                , [Guid]
                , [CreatedDateTime]
                , [ModifiedDateTime]
                , [PersonAliasId]
                , [MediumEntityTypeId]
            )
            VALUES
            (
                @CommunicationId
                , @RecipientStatusPending
                , NEWID()
                , GETDATE()
                , GETDATE()
                , s.[PrimaryAliasId]
                , CASE
                    WHEN @CommunicationType = @CommunicationTypeRecipientPreference
                        AND s.[MediumEntityTypeId] IS NOT NULL
                        THEN s.[MediumEntityTypeId]
                    ELSE @CommunicationMediumEntityTypeId
                    END
            )
        OPTION (RECOMPILE);

        -- Batch delete pending [CommunicationRecipient] records that do not have a corresponding list member record.
        WHILE 1 = 1
        BEGIN
            WITH [DeleteRecipients] AS (
                SELECT TOP 1500 cr.[Id]
                FROM [CommunicationRecipient] cr WITH (READPAST)
                WHERE cr.[CommunicationId] = @CommunicationId
                    AND cr.[Status] = @RecipientStatusPending
                    AND NOT EXISTS (
                        SELECT 1
                        FROM #ListMembers lm
                        WHERE lm.[PrimaryAliasId] = cr.[PersonAliasId]
                    )
                ORDER BY cr.[Id]
            )
            DELETE cr
            FROM [CommunicationRecipient] cr WITH (ROWLOCK, READPAST)
            INNER JOIN [DeleteRecipients] dr
                ON dr.[Id] = cr.[Id];

            IF @@ROWCOUNT > 0 CONTINUE;

            -- Break only if there are truly no more recipients to delete.
            IF NOT EXISTS (
                SELECT 1
                FROM [CommunicationRecipient] cr
                WHERE cr.[CommunicationId] = @CommunicationId
                    AND cr.[Status] = @RecipientStatusPending
                    AND NOT EXISTS (
                        SELECT 1
                        FROM #ListMembers lm
                        WHERE lm.[PrimaryAliasId] = cr.[PersonAliasId]
                    )
            ) BREAK;

            WAITFOR DELAY '00:00:00.100';
        END

        COMMIT TRAN;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRAN;

        THROW;
    END CATCH

END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

                -- create stored proc that retrieves a binaryfile record
                /*
                <doc>
	                <summary>
 		                This function returns the BinaryFile for a given Id or Guid, depending on which is specified
	                </summary>

	                <returns>
		                * BinaryFile record
	                </returns>
	                <param name='Id' datatype='int'>The binary id to use</param>
	                <param name='Guid' datatype='uniqueidentifier'>The binaryfile guid to use</param>
	                <remarks>	
	                </remarks>
	                <code>
		                EXEC [dbo].[spCore_BinaryFileGet] 14, null -- car-promo.jpg
	                </code>
                </doc>
                */
                CREATE PROCEDURE [dbo].[spCore_BinaryFileGet]
                    @Id int
                    , @Guid uniqueidentifier
                AS
                BEGIN
                    SET NOCOUNT ON;

                    /* NOTE!: Column Order cannot be changed without changing BinaryFileService.partial.cs due to CommandBehavior.SequentialAccess */
                    SELECT 
                        bf.[Id]
                        , bf.[IsTemporary] 
                        , bf.[IsSystem]
                        , bf.[BinaryFileTypeId]
		                , bft.[RequiresViewSecurity]
                        , bf.[FileName] 
                        , bf.[MimeType]
                        , bf.[ModifiedDateTime]
                        , bf.[Description]
                        , bf.[StorageEntityTypeId]
                        , bf.[Guid]
		                , bf.[StorageEntitySettings]
		                , bf.[Path]
		                , bf.[FileSize]
		                , bf.[ParentEntityTypeId]
		                , bf.[ParentEntityId]
                        /* if the BinaryFile as StorageEntityTypeId set, use that. Otherwise use the default StorageEntityTypeId from BinaryFileType  */
                        , COALESCE (bfse.[Name],bftse.[Name] ) as [StorageEntityTypeName]
                        , bfd.[Content]
                    FROM [BinaryFile] bf 
                    LEFT JOIN [BinaryFileData] bfd ON bf.[Id] = bfd.[Id]
                    LEFT JOIN [EntityType] bfse ON bf.[StorageEntityTypeId] = bfse.[Id]
                    LEFT JOIN [BinaryFileType] bft ON bf.[BinaryFileTypeId] = bft.[Id]
                    LEFT JOIN [EntityType] bftse ON bft.[StorageEntityTypeId] = bftse.[Id]
                    WHERE (@Id > 0 AND bf.[Id] = @Id)
                        OR (bf.[Guid] = @Guid)
                END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*
<doc>
	<summary>
		This procedure AttributeMatrix records that are no longer associated with an attribute value.
	</summary>

	<returns>
	</returns>
	<code>
	</code>
</doc>
*/
	
CREATE PROCEDURE [dbo].[spCore_DeleteOrphanedAttributeMatrices]
AS
BEGIN
	DECLARE @MatrixItemEntityTypeId INT = (SELECT Id FROM [EntityType] WHERE [Guid]='3C9D5021-0484-4846-AEF6-B6216D26C3C8')
	DECLARE @MatrixFieldTypeId INT = (SELECT Id FROM [FieldType] WHERE [Guid]='f16fc460-dc1e-4821-9012-5f21f974c677')
	DECLARE @MatrixEntityTypeId INT = (SELECT Id FROM [EntityType] WHERE [Guid]='028228F0-B1D9-4DE5-9E6A-F898C34DDAB8')
	IF @MatrixItemEntityTypeId IS NOT NULL AND @MatrixFieldTypeId IS NOT NULL AND @MatrixEntityTypeId IS NOT NULL
	BEGIN
    -- Get all the attribute matrix identifiers into temp table that has no active reference found in attribute value
		SELECT
			am.[Id], am.[Guid]
		INTO #temp
		FROM
			[AttributeMatrix] am 
			LEFT OUTER JOIN [AttributeValue] av ON av.[Value] = CONVERT(nvarchar(36), am.[Guid] ) AND av.[AttributeId] IN (
				SELECT a.[Id] FROM [Attribute] a WHERE a.[FieldTypeId] = @MatrixFieldTypeId )
		WHERE av.[Value] IS NULL

         -- Exclude attribute matrix identifiers from the temp table that has any reference foundn in AssignedGroupMemberAttributeValues of connection request
		DELETE FROM #temp 
		WHERE [Guid] IN (SELECT 
				am.[Guid] 
			FROM 
				#temp AS am
				LEFT JOIN [dbo].[ConnectionRequest] AS cr ON cr.AssignedGroupMemberAttributeValues LIKE ('%' + CONVERT(nvarchar(36), am.[Guid]) + '%')
			WHERE
				[AssignedGroupMemberAttributeValues] LIKE ('%' + CONVERT(nvarchar(36), am.[Guid]) + '%'))

         -- Delete all the attribute value related to attribute matrices found in temp table
		DELETE FROM av
		FROM 
			#temp as am 
			INNER JOIN [AttributeMatrixItem] ai ON am.Id = ai.AttributeMatrixId 
			INNER JOIN [AttributeValue] as av ON av.[EntityId] = ai.[Id]
			INNER JOIN [Attribute] as a ON a.EntityTypeId = @MatrixItemEntityTypeId AND a.Id = av.AttributeId
		WHERE a.EntityTypeId = @MatrixItemEntityTypeId

        -- Delete all the attribute matrix items related to attribute matrices found in temp table
		DELETE FROM ai
		FROM 
			#temp as am 
			INNER JOIN [AttributeMatrixItem] ai ON am.Id = ai.AttributeMatrixId 

        -- Delete all the attribute matrix items related to attribute matrices found in temp table
		DELETE FROM [AttributeMatrix] WHERE [Id] IN (SELECT Id FROM #temp)
	END
END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[spCrm_FamilyAnalyticsAttendance]

AS
BEGIN
	
	-- configuration of the duration in weeks
	DECLARE @EntryAttendanceDurationWeeks int = 16
		
	DECLARE @cACTIVE_RECORD_STATUS_VALUE_GUID uniqueidentifier = '618F906C-C33D-4FA3-8AEF-E58CB7B63F1E'
	DECLARE @cPERSON_RECORD_TYPE_VALUE_GUID uniqueidentifier = '36CF10D6-C695-413D-8E7C-4546EFEF385E'
	DECLARE @cATTRIBUTE_IS_ERA_GUID uniqueidentifier = 'CE5739C5-2156-E2AB-48E5-1337C38B935E'
	DECLARE @cFAMILY_GROUPTYPE_GUID uniqueidentifier = '790E3215-3B10-442B-AF69-616C0DCB998E'
	DECLARE @cADULT_ROLE_GUID uniqueidentifier = '2639F9A5-2AAE-4E48-A8C3-4FFE86681E42'
	DECLARE @cCHILD_ROLE_GUID uniqueidentifier = 'C8B1814F-6AA7-4055-B2D7-48FE20429CB9'

	DECLARE @cATTRIBUTE_FIRST_ATTENDED uniqueidentifier  = 'AB12B3B0-55B8-D6A5-4C1F-DB9CCB2C4342'
	DECLARE @cATTRIBUTE_LAST_ATTENDED uniqueidentifier  = '5F4C6462-018E-D19C-4AB0-9843CB21C57E'
	DECLARE @cATTRIBUTE_TIMES_ATTENDED_IN_DURATION uniqueidentifier  = '45A1E978-DC5B-CFA1-4AF4-EA098A24C914'
	DECLARE @Now DATETIME = dbo.RockGetDate()

	-- --------- END CONFIGURATION --------------

	DECLARE @ActiveRecordStatusValueId int = (SELECT TOP 1 [Id] FROM [DefinedValue] WHERE [Guid] = @cACTIVE_RECORD_STATUS_VALUE_GUID)
	DECLARE @PersonRecordTypeValueId int = (SELECT TOP 1 [Id] FROM [DefinedValue] WHERE [Guid] = @cPERSON_RECORD_TYPE_VALUE_GUID)
	DECLARE @IsEraAttributeId int = (SELECT TOP 1 [Id] FROM [Attribute] WHERE [Guid] = @cATTRIBUTE_IS_ERA_GUID)
	DECLARE @FamilyGroupTypeId int = (SELECT TOP 1 [Id] FROM [GroupType] WHERE [Guid] = @cFAMILY_GROUPTYPE_GUID)
	DECLARE @AdultRoleId int = (SELECT TOP 1 [Id] FROM [GroupTypeRole] WHERE [Guid] = @cADULT_ROLE_GUID)
	DECLARE @ChildRoleId int = (SELECT TOP 1 [Id] FROM [GroupTypeRole] WHERE [Guid] = @cCHILD_ROLE_GUID)

	-- calculate dates for query
	DECLARE @SundayDateStart datetime = [dbo].[ufnUtility_GetPreviousSundayDate]()
	DECLARE @SundayEntryAttendanceDuration datetime = DATEADD(DAY,  (7 * @EntryAttendanceDurationWeeks * -1), @SundayDateStart)
	

	-- first checkin
	DECLARE @FirstAttendedAttributeId int = (SELECT TOP 1 [Id] FROM dbo.[Attribute] WHERE [Guid] = @cATTRIBUTE_FIRST_ATTENDED);

	WITH
	  cteIndividual ([PersonId], [GivingGroupId], [FamilyRole])
	  AS
	  (
		SELECT p.[Id] AS [PersonId], p.[GivingGroupId], CASE WHEN fr.[FamilyRole] = @AdultRoleId THEN 'Adult' ELSE 'Child' END
		FROM [Person] p
		CROSS APPLY
			(
			SELECT TOP 1 gm.[GroupRoleId] AS [FamilyRole]
			FROM    
				[GroupMember] gm 
				INNER JOIN [Group] g ON g.[Id] = gm.[GroupId] AND g.[GroupTypeId] = @FamilyGroupTypeId
				INNER JOIN [GroupTypeRole] gtr ON gtr.[Id] = gm.[GroupRoleId]
			WHERE 
				gm.[PersonId] = p.[Id] 
			) fr
		WHERE
			[RecordStatusValueId] = @ActiveRecordStatusValueId -- record is active
			AND [RecordTypeValueId] = @PersonRecordTypeValueId  -- person record type (not business)
	  )
	SELECT [PersonId], [FirstAttendedDate], av.[Id] AttributeValueId, av.[ValueAsDateTime] ExistingValue
	INTO #firstAttended
	FROM 
		(SELECT 
			i.[PersonId]
			, CASE WHEN [FamilyRole] = 'Adult' THEN 
					(SELECT 
						MIN(A.[StartDateTime] )
					FROM
						[Attendance] a
						INNER JOIN [AttendanceOccurrence] O ON O.[Id] = A.[OccurrenceId]
						INNER JOIN [PersonAlias] pa ON pa.[Id] = a.[PersonAliasId]
					WHERE 
						O.[GroupId] IN (SELECT [Id] FROM [dbo].[ufnCheckin_WeeklyServiceGroups]())
                        AND a.[DidAttend] = 1
						AND pa.[PersonId] IN (SELECT [Id] FROM [dbo].[ufnCrm_FamilyMembersOfPersonId](i.[PersonId])))
				ELSE
					(SELECT 
						MIN(a.[StartDateTime] )
					FROM
						[Attendance] a
						INNER JOIN [AttendanceOccurrence] O ON O.[Id] = A.[OccurrenceId]
						INNER JOIN [PersonAlias] pa ON pa.[Id] = a.[PersonAliasId]
					WHERE 
						O.[GroupId] IN (SELECT [Id] FROM [dbo].[ufnCheckin_WeeklyServiceGroups]())
                        AND a.[DidAttend] = 1
						AND pa.[PersonId] = i.[PersonId])
			  END AS [FirstAttendedDate]
		FROM cteIndividual i ) AS a
	LEFT JOIN [AttributeValue] av ON av.[EntityId] = a.[PersonId]
	AND av.[AttributeId] = @FirstAttendedAttributeId
	WHERE a.[FirstAttendedDate] IS NOT NULL

	-- Update Existing values before inserting to reduce number of logical reads.
	UPDATE av SET
		av.[Value] = f.[FirstAttendedDate],
		av.[ValueAsDateTime] = f.[FirstAttendedDate],
		av.[IsPersistedValueDirty] = 1
	FROM dbo.[AttributeValue] av
	JOIN #firstAttended f on f.[AttributeValueId] = av.[Id]
	WHERE f.[ExistingValue] IS NULL
	OR f.[ExistingValue] <> f.[FirstAttendedDate]

	-- Added new values.
	INSERT dbo.[AttributeValue] ([EntityId]
        , [AttributeId]
        , [Value]
        , [IsSystem]
        , [Guid]
        , [CreatedDateTime]
        , [ValueAsDateTime]
        , [IsPersistedValueDirty])
	SELECT f.[PersonId]
		, @FirstAttendedAttributeId
		, f.[FirstAttendedDate]
		, 0
		, newid()
		, @Now
		, f.[FirstAttendedDate]
		, 1
	FROM #firstAttended f
	WHERE f.[AttributeValueId] IS NULL

	-- Remove the temp table.
	DROP TABLE #firstAttended

	-- last checkin
	DECLARE @LastAttendedAttributeId int = (SELECT TOP 1 [Id] FROM [Attribute] WHERE [Guid] = @cATTRIBUTE_LAST_ATTENDED);

	WITH
	  cteIndividual ([PersonId], [GivingGroupId], [FamilyRole])
	  AS
	  (
		SELECT p.[Id] AS [PersonId], p.[GivingGroupId], CASE WHEN fr.[FamilyRole] = @AdultRoleId THEN 'Adult' ELSE 'Child' END
		FROM [Person] p
		CROSS APPLY
			(
			SELECT TOP 1 gm.[GroupRoleId] AS [FamilyRole]
			FROM    
				[GroupMember] gm 
				INNER JOIN [Group] g ON g.[Id] = gm.[GroupId] AND g.[GroupTypeId] = @FamilyGroupTypeId
				INNER JOIN [GroupTypeRole] gtr ON gtr.[Id] = gm.[GroupRoleId]
			WHERE 
				gm.[PersonId] = p.[Id] 
			) fr
		WHERE
			[RecordStatusValueId] = @ActiveRecordStatusValueId -- record is active
			AND [RecordTypeValueId] = @PersonRecordTypeValueId  -- person record type (not business)
	  )
	SELECT [PersonId], [LastAttendedDate], av.[Id] AttributeValueId, av.[ValueAsDateTime] ExistingValue
	INTO #lastAttended
	FROM 
		(SELECT 
			i.[PersonId]
			, CASE WHEN [FamilyRole] = 'Adult' THEN 
					(SELECT 
						MAX(a.StartDateTime )
					FROM
						[Attendance] a
						INNER JOIN [AttendanceOccurrence] O ON O.[Id] = A.[OccurrenceId]
						INNER JOIN [PersonAlias] pa ON pa.[Id] = a.[PersonAliasId]
					WHERE 
						O.[GroupId] IN (SELECT [Id] FROM [dbo].[ufnCheckin_WeeklyServiceGroups]())
                        AND a.[DidAttend] = 1
						AND pa.[PersonId] IN (SELECT [Id] FROM [dbo].[ufnCrm_FamilyMembersOfPersonId](i.[PersonId])))
				ELSE
					(SELECT 
						MAX(a.StartDateTime )
					FROM
						[Attendance] a
						INNER JOIN [AttendanceOccurrence] O ON O.[Id] = A.[OccurrenceId]
						INNER JOIN [PersonAlias] pa ON pa.[Id] = a.[PersonAliasId]
					WHERE 
						O.[GroupId] IN (SELECT [Id] FROM [dbo].[ufnCheckin_WeeklyServiceGroups]())
                        AND a.[DidAttend] = 1
						AND pa.[PersonId] = i.[PersonId])
			  END AS [LastAttendedDate]
		FROM cteIndividual i ) AS a
	LEFT JOIN dbo.[AttributeValue] av ON av.[EntityId] = a.[PersonId] 
	AND av.[AttributeId] = @LastAttendedAttributeId
	WHERE a.[LastAttendedDate] IS NOT NULL

	-- Update Existing values before inserting to reduce number of logical reads.
	UPDATE av SET
		av.[Value] = f.[LastAttendedDate],
		av.[ValueAsDateTime] = f.[LastAttendedDate],
		av.[IsPersistedValueDirty] = 1
	FROM dbo.[AttributeValue] av
	JOIN #lastAttended f on f.[AttributeValueId] = av.[Id]
	WHERE f.[ExistingValue] IS NULL
	OR f.[ExistingValue] <> f.[LastAttendedDate]

	-- Added new values.
	INSERT dbo.[AttributeValue] ([EntityId]
        , [AttributeId]
        , [Value]
        , [IsSystem]
        , [Guid]
        , [CreatedDateTime]
        , [ValueAsDateTime]
        , [IsPersistedValueDirty])
	SELECT f.PersonId
		, @LastAttendedAttributeId
		, f.[LastAttendedDate]
		, 0
		, newid()
		, @Now
		, f.[LastAttendedDate]
		, 1
	FROM #lastAttended f
	WHERE f.[AttributeValueId] IS NULL

	-- Remove the temp table.
	DROP TABLE #lastAttended

	-- times checkedin
	DECLARE @TimesAttendedAttributeId int = (SELECT TOP 1 [Id] FROM [Attribute] WHERE [Guid] = @cATTRIBUTE_TIMES_ATTENDED_IN_DURATION);

	WITH
	  cteIndividual ([PersonId], [GivingGroupId], [FamilyRole])
	  AS
	  (
		SELECT p.[Id] AS [PersonId], p.[GivingGroupId], CASE WHEN fr.[FamilyRole] = @AdultRoleId THEN 'Adult' ELSE 'Child' END
		FROM [Person] p
		CROSS APPLY
			(
			SELECT TOP 1 gm.[GroupRoleId] AS [FamilyRole]
			FROM    
				[GroupMember] gm 
				INNER JOIN [Group] g ON g.[Id] = gm.[GroupId] AND g.[GroupTypeId] = @FamilyGroupTypeId
				INNER JOIN [GroupTypeRole] gtr ON gtr.[Id] = gm.[GroupRoleId]
			WHERE 
				gm.[PersonId] = p.[Id] 
			) fr
		WHERE
			[RecordStatusValueId] = @ActiveRecordStatusValueId -- record is active
			AND [RecordTypeValueId] = @PersonRecordTypeValueId  -- person record type (not business)
	  )
	SELECT [PersonId], [CheckinCount], av.[Id] AttributeValueId, av.[ValueAsDateTime] ExistingValue
	INTO #checkInCount
	FROM 
		(SELECT 
			i.[PersonId]
			, CASE WHEN [FamilyRole] = 'Adult' THEN 
					(SELECT 
						COUNT(*)
					FROM
						[Attendance] a
						INNER JOIN [AttendanceOccurrence] O ON O.[Id] = A.[OccurrenceId]
						INNER JOIN [PersonAlias] pa ON pa.[Id] = a.[PersonAliasId]
					WHERE 
						O.[GroupId] IN (SELECT [Id] FROM [dbo].[ufnCheckin_WeeklyServiceGroups]())
						AND CAST( a.[StartDateTime] AS DATE ) <= @SundayDateStart AND a.[StartDateTime] >= @SundayEntryAttendanceDuration
                        AND a.[DidAttend] = 1
						AND pa.[PersonId] IN (SELECT [Id] FROM [dbo].[ufnCrm_FamilyMembersOfPersonId](i.[PersonId])))
				ELSE
					(SELECT 
						COUNT(*)
					FROM
						[Attendance] a
						INNER JOIN [AttendanceOccurrence] O ON O.[Id] = A.[OccurrenceId]
						INNER JOIN [PersonAlias] pa ON pa.[Id] = a.[PersonAliasId]
					WHERE 
						O.[GroupId] IN (SELECT [Id] FROM [dbo].[ufnCheckin_WeeklyServiceGroups]())
						AND CAST( a.[StartDateTime] AS DATE ) <= @SundayDateStart AND a.[StartDateTime] >= @SundayEntryAttendanceDuration
                        AND a.[DidAttend] = 1
						AND pa.[PersonId] = i.[PersonId])
			  END AS [CheckinCount]
		FROM cteIndividual i ) AS a
	LEFT JOIN dbo.[AttributeValue] av ON av.[EntityId] = a.[PersonId]
	AND av.[AttributeId] = @TimesAttendedAttributeId
	WHERE a.[CheckinCount] IS NOT NULL

	-- Update Existing values before inserting to reduce number of logical reads.
	UPDATE av SET
		av.[Value] = f.[CheckinCount],
		av.[ValueAsNumeric] = f.[CheckinCount],
		av.[IsPersistedValueDirty] = 1
	FROM dbo.[AttributeValue] av
	JOIN #checkInCount f on f.[AttributeValueId] = av.[Id]
	WHERE f.[ExistingValue] IS NULL
	OR f.[ExistingValue] <> f.[CheckinCount]

	-- Added new values.
	INSERT dbo.[AttributeValue] ([EntityId]
        , [AttributeId]
        , [Value]
        , [IsSystem]
        , [Guid]
        , [CreatedDateTime]
        , [ValueAsNumeric]
        , [IsPersistedValueDirty])
	SELECT f.[PersonId]
		, @TimesAttendedAttributeId
		, f.[CheckinCount]
		, 0
		, newid()
		, @Now
		, f.[CheckinCount]
		, 1
	FROM #checkInCount f
	WHERE f.[AttributeValueId] IS NULL

	-- Remove the temp table.
	DROP TABLE #checkInCount
	
END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/*
<doc>
	<summary>
 		This stored procedure returns a data set used by the Rock eRA job to add/remove
		people from being an eRA. It should not be modified as it will be updated in the
		future to meet additional requirements.
		The goal of the query is to return both those that meet the eRA requirements as well
		as those that are marked as already being an eRA and the criteria to ensure that
		they still should be an era.
	</summary>
	
	<remarks>
		For eRA we only consider adults for the criteria.
	</remarks>
	<code>
		EXEC [dbo].[spCrm_FamilyAnalyticsEraDataset] 
	</code>
</doc>
*/
CREATE PROCEDURE [dbo].[spCrm_FamilyAnalyticsEraDataset]
AS
BEGIN
    -- configuration of the duration in weeks
    DECLARE @EntryGivingDurationLongWeeks INT = 52
    DECLARE @EntryGivingDurationShortWeeks INT = 6
    DECLARE @EntryAttendanceDurationWeeks INT = 16
    DECLARE @ExitGivingDurationWeeks INT = 8
    DECLARE @ExitAttendanceDurationShortWeeks INT = 4
    DECLARE @ExitAttendanceDurationLongWeeks INT = 16
    -- configuration of the item counts in the durations
    DECLARE @EntryGiftCountDurationLong INT = 4
    DECLARE @EntryGiftCountDurationShort INT = 1
    DECLARE @EntryAttendanceCountDuration INT = 8
    DECLARE @cACTIVE_RECORD_STATUS_VALUE_GUID UNIQUEIDENTIFIER = '618F906C-C33D-4FA3-8AEF-E58CB7B63F1E'
    DECLARE @cPERSON_RECORD_TYPE_VALUE_GUID UNIQUEIDENTIFIER = '36CF10D6-C695-413D-8E7C-4546EFEF385E'
    DECLARE @cATTRIBUTE_IS_ERA_GUID UNIQUEIDENTIFIER = 'CE5739C5-2156-E2AB-48E5-1337C38B935E'
    DECLARE @cFAMILY_GROUPTYPE_GUID UNIQUEIDENTIFIER = '790E3215-3B10-442B-AF69-616C0DCB998E'
    DECLARE @cADULT_ROLE_GUID UNIQUEIDENTIFIER = '2639F9A5-2AAE-4E48-A8C3-4FFE86681E42'
    DECLARE @cTRANSACTION_TYPE_CONTRIBUTION UNIQUEIDENTIFIER = '2D607262-52D6-4724-910D-5C6E8FB89ACC';
	DECLARE @cATTRIBUTE_ERA_START_DATE_GUID UNIQUEIDENTIFIER = 'A106610C-A7A1-469E-4097-9DE6400FDFC2';
    -- --------- END CONFIGURATION --------------
    DECLARE @PersonRecordTypeValueId INT = (
            SELECT TOP 1 [Id]
            FROM [DefinedValue]
            WHERE [Guid] = @cPERSON_RECORD_TYPE_VALUE_GUID
            )
    DECLARE @IsEraAttributeId INT = (
            SELECT TOP 1 [Id]
            FROM [Attribute]
            WHERE [Guid] = @cATTRIBUTE_IS_ERA_GUID
            )
	DECLARE @EraStartDateAttributeId INT = (
            SELECT TOP 1 [Id]
            FROM [Attribute]
            WHERE [Guid] = @cATTRIBUTE_ERA_START_DATE_GUID
            )
    DECLARE @FamilyGroupTypeId INT = (
            SELECT TOP 1 [Id]
            FROM [GroupType]
            WHERE [Guid] = @cFAMILY_GROUPTYPE_GUID
            )
    DECLARE @AdultRoleId INT = (
            SELECT TOP 1 [Id]
            FROM [GroupTypeRole]
            WHERE [Guid] = @cADULT_ROLE_GUID
            )
    DECLARE @ContributionType INT = (
            SELECT TOP 1 [Id]
            FROM [DefinedValue]
            WHERE [Guid] = @cTRANSACTION_TYPE_CONTRIBUTION
            )
    -- calculate dates for query
    DECLARE @SundayDateStart DATETIME = [dbo].[ufnUtility_GetPreviousSundayDate]()
    DECLARE @SundayEntryGivingDurationLong DATETIME = DATEADD(DAY, (7 * @EntryGivingDurationLongWeeks * - 1), @SundayDateStart)
    DECLARE @SundayEntryGivingDurationShort DATETIME = DATEADD(DAY, (7 * @EntryGivingDurationShortWeeks * - 1), @SundayDateStart)
    DECLARE @SundayEntryAttendanceDuration DATETIME = DATEADD(DAY, (7 * @EntryAttendanceDurationWeeks * - 1), @SundayDateStart)
    DECLARE @SundayExitGivingDuration DATETIME = DATEADD(DAY, (7 * @ExitGivingDurationWeeks * - 1), @SundayDateStart)
    DECLARE @SundayExitAttendanceDurationShort DATETIME = DATEADD(DAY, (7 * @ExitAttendanceDurationShortWeeks * - 1), @SundayDateStart)
    DECLARE @SundayExitAttendanceDurationLong DATETIME = DATEADD(DAY, (7 * @ExitAttendanceDurationLongWeeks * - 1), @SundayDateStart)
    DECLARE @TempFinancialTransactionByDateAndGivingId TABLE (
    DistinctCount INT
        ,GivingId NVARCHAR(50)
        ,TransactionDateTime DATETIME
        ,SundayDate Date
        )
    INSERT INTO @TempFinancialTransactionByDateAndGivingId
    SELECT COUNT(DISTINCT (ft.[Id])) [DistinctCount]
        ,g1.GivingId
        ,ft.TransactionDateTime [TransactionDateTime]
        ,SundayDate Date
    FROM [FinancialTransaction] ft
    INNER JOIN [PersonAlias] pa ON pa.[Id] = ft.[AuthorizedPersonAliasId]
    INNER JOIN [Person] g1 ON g1.[Id] = pa.[PersonId]
    INNER JOIN [FinancialTransactionDetail] ftd ON ftd.[TransactionId] = ft.[Id]
    INNER JOIN [FinancialAccount] fa ON fa.[Id] = ftd.AccountId
    WHERE ft.TransactionTypeValueId = @ContributionType
        AND fa.[IsTaxDeductible] = 1
        AND ft.TransactionDateTime >= @SundayEntryGivingDurationLong
    GROUP BY g1.GivingId
        ,ft.TransactionDateTime
        ,SundayDate
    DECLARE @TempAttendanceBySundayDateAndFamily TABLE (
        SundayDate DATE
        ,StartDateTime DATETIME
        ,FamilyId INT
        )
    INSERT INTO @TempAttendanceBySundayDateAndFamily
    SELECT O.SundayDate
        ,a.StartDateTime
        ,fg.Id [FamilyId]
    FROM [Attendance] a
    INNER JOIN [AttendanceOccurrence] O ON O.[Id] = A.[OccurrenceId]
    INNER JOIN [Group] ag ON ag.[Id] = O.[GroupId]
    INNER JOIN [GroupType] agt ON agt.[Id] = ag.[GroupTypeId]
        AND agt.[AttendanceCountsAsWeekendService] = 1
    INNER JOIN [PersonAlias] pa ON pa.[Id] = a.[PersonAliasId]
    INNER JOIN [GroupMember] fgm ON fgm.[PersonId] = pa.[PersonId]
    INNER JOIN [Group] fg ON fg.[Id] = fgm.[GroupId]
        AND fg.[GroupTypeId] = @FamilyGroupTypeId
    WHERE a.[DidAttend] = 1
        AND a.StartDateTime >= @SundayExitAttendanceDurationLong
        AND fgm.IsArchived = 0
        AND fg.IsArchived = 0
    GROUP BY O.SundayDate
        ,StartDateTime
        ,fg.Id
	DECLARE @TempEntryGiftCountDurationShort TABLE (
			GivingId NVARCHAR(50) INDEX IX1 CLUSTERED
			, DistinctCount INT
		    )
	INSERT INTO @TempEntryGiftCountDurationShort
	SELECT GivingId, SUM(ft.DistinctCount)
	FROM @TempFinancialTransactionByDateAndGivingId ft
	WHERE ft.TransactionDateTime >= @SundayEntryGivingDurationShort
		AND ft.SundayDate <= @SundayDateStart
	GROUP BY GivingId
	DECLARE @TempExitGiftCountDuration TABLE (
			GivingId NVARCHAR(50) INDEX IX2 CLUSTERED
			, DistinctCount INT
		    )
	INSERT INTO @TempExitGiftCountDuration
	SELECT GivingId, ISNULL(SUM(ft.DistinctCount), 0)
	FROM @TempFinancialTransactionByDateAndGivingId ft
	WHERE ft.TransactionDateTime >= @SundayExitGivingDuration
		AND ft.SundayDate <= @SundayDateStart
	GROUP BY GivingId
	DECLARE @TempEntryGiftCountDurationLong TABLE (
			GivingId NVARCHAR(50) INDEX IX3 CLUSTERED
			, DistinctCount INT
		    )
	INSERT INTO @TempEntryGiftCountDurationLong
	SELECT GivingId, ISNULL(SUM(ft.DistinctCount), 0) AS [EntryGiftCountDurationLong]
					FROM @TempFinancialTransactionByDateAndGivingId ft
					WHERE ft.TransactionDateTime >= @SundayEntryGivingDurationLong
						AND ft.SundayDate <= @SundayDateStart
	GROUP BY GivingId
	DECLARE @TempExitAttendanceCountDurationShort TABLE (
			FamilyId INT INDEX IX4 CLUSTERED
			, DistinctCount INT
		    )
	INSERT INTO @TempExitAttendanceCountDurationShort
	SELECT FamilyId, COUNT(DISTINCT a.SundayDate) AS [ExitAttendanceCountDurationShort]
					FROM @TempAttendanceBySundayDateAndFamily a
					WHERE a.StartDateTime <= @SundayDateStart
						AND a.StartDateTime >= @SundayExitAttendanceDurationShort
	GROUP BY FamilyId
	DECLARE @TempEntryAttendanceCountDuration TABLE (
			FamilyId INT INDEX IX5 CLUSTERED
			, DistinctCount INT
		    )
	INSERT INTO @TempEntryAttendanceCountDuration
	SELECT FamilyId, COUNT(DISTINCT a.SundayDate) AS [EntryAttendanceCountDuration]
					FROM @TempAttendanceBySundayDateAndFamily a
					WHERE a.StartDateTime <= @SundayDateStart
						AND a.StartDateTime >= @SundayEntryAttendanceDuration
	GROUP BY FamilyId
	DECLARE @TempExitAttendanceCountDurationLong TABLE (
			FamilyId INT INDEX IX6 CLUSTERED
			, DistinctCount INT
		    )
	INSERT INTO @TempExitAttendanceCountDurationLong
	SELECT FamilyId, COUNT(DISTINCT a.SundayDate) AS [ExitAttendanceCountDurationLong]
					FROM @TempAttendanceBySundayDateAndFamily a
					WHERE a.StartDateTime <= @SundayDateStart
						AND a.StartDateTime >= @SundayExitAttendanceDurationLong
	GROUP BY FamilyId
	DECLARE @TempPersonFamilyGroupIds TABLE (
			Id INT,
			GivingId NVARCHAR(50),
			[IsEra] INT,
			FamilyId INT,
			INDEX IXR NONCLUSTERED(GivingId,[IsEra],FamilyId)
		    )
	INSERT INTO @TempPersonFamilyGroupIds
	SELECT p.[Id]
		, p.[GivingId]
		,CASE 
			WHEN (era.[Value] = 'true')
				THEN 1
			ELSE 0
			END AS [IsEra]
		,g.[Id] AS [FamilyId]
	FROM [Person] p
	INNER JOIN [GroupMember] gm ON gm.[PersonId] = p.[Id]
		AND gm.[GroupRoleId] = @AdultRoleId
	INNER JOIN [Group] g ON g.[Id] = gm.[GroupId]
		AND g.[GroupTypeId] = @FamilyGroupTypeId
	LEFT OUTER JOIN [AttributeValue] era ON era.[EntityId] = p.[Id]
		AND era.[AttributeId] = @IsEraAttributeId
	WHERE [RecordTypeValueId] = @PersonRecordTypeValueId -- person record type (not business)
    AND gm.IsArchived = 0
    AND g.IsArchived = 0
	DECLARE @TempIsEraFamilyMembers TABLE (
		PersonId INT,
		[IsEra] INT,
		FamilyId INT,
		INDEX IXR NONCLUSTERED([IsEra],FamilyId)
	    )
	DECLARE @CreatedDateTime DATETIME = GETDATE()
	DECLARE @StartDateValue NVARCHAR(MAX) = CONVERT(nvarchar(MAX), GETDATE(), 127)
	INSERT INTO @TempIsEraFamilyMembers
	SELECT p.Id,
		Min(tgpgids.IsEra),
		Min(p.PrimaryFamilyId)
		FROM [Person] p
		LEFT JOIN @TempPersonFamilyGroupIds tgpgids ON p.PrimaryFamilyId = tgpgids.FamilyId
		WHERE tgpgids.IsEra = 1
		GROUP BY  p.Id
    
    -- Insert missing IsEra Attribute --
	MERGE [AttributeValue] AS TARGET
	USING @TempIsEraFamilyMembers AS SOURCE
	ON (TARGET.EntityId = SOURCE.PersonId AND TARGET.AttributeId = @IsEraAttributeId)
	WHEN NOT MATCHED BY TARGET
	THEN INSERT (EntityId, AttributeId, Value, IsSystem, Guid, CreatedDateTime, ValueAsBoolean, IsPersistedValueDirty) VALUES (SOURCE.PersonId, @IsEraAttributeId, 'True', 0, NEWID(), @CreatedDateTime, 1, 1)
	WHEN MATCHED AND [Value] != 'True' THEN UPDATE SET Value = 'True', ValueAsBoolean = 1, IsPersistedValueDirty = 1;
    -- Insert missing EraStartDate --
	MERGE [AttributeValue] AS TARGET
	USING @TempIsEraFamilyMembers AS SOURCE
	ON (TARGET.EntityId = SOURCE.PersonId AND TARGET.AttributeId = @EraStartDateAttributeId)
	WHEN NOT MATCHED BY TARGET
	THEN INSERT (EntityId, AttributeId, Value, IsSystem, Guid, CreatedDateTime, ValueAsDateTime, IsPersistedValueDirty) VALUES (SOURCE.PersonId, @EraStartDateAttributeId, @StartDateValue, 0, NEWID(), @CreatedDateTime, @CreatedDateTime, 1)
    WHEN MATCHED AND ([Value] is null or [Value] = '') THEN UPDATE SET Value = @StartDateValue, ValueAsDateTime = @CreatedDateTime, IsPersistedValueDirty = 1;
	SELECT [FamilyId]
        ,MAX([EntryGiftCountDurationShort]) AS [EntryGiftCountDurationShort]
        ,MAX([EntryGiftCountDurationLong]) AS [EntryGiftCountDurationLong]
        ,MAX([ExitGiftCountDuration]) AS [ExitGiftCountDuration]
        ,MAX([EntryAttendanceCountDuration]) AS [EntryAttendanceCountDuration]
        ,MAX([ExitAttendanceCountDurationShort]) AS [ExitAttendanceCountDurationShort]
        ,MAX([ExitAttendanceCountDurationLong]) AS [ExitAttendanceCountDurationLong]
        ,CAST(MAX([IsEra]) AS BIT) AS [IsEra]
    FROM (
        SELECT [Id]
            ,[IsEra]
            ,tpfgids.[FamilyId]
            ,ISNULL(egcds.DistinctCount, 0) AS [EntryGiftCountDurationShort]
            ,ISNULL(egcd.DistinctCount, 0) AS [ExitGiftCountDuration]
            ,ISNULL(egcdl.DistinctCount, 0) AS [EntryGiftCountDurationLong]
            ,ISNULL(eacds.DistinctCount, 0) AS [ExitAttendanceCountDurationShort]
            ,ISNULL(eacd.DistinctCount, 0) AS [EntryAttendanceCountDuration]
            ,ISNULL(eacdl.DistinctCount, 0) AS [ExitAttendanceCountDurationLong]
        FROM @TempPersonFamilyGroupIds tpfgids
		LEFT JOIN @TempEntryGiftCountDurationShort egcds ON egcds.GivingId = tpfgids.GivingId
		LEFT JOIN @TempExitGiftCountDuration egcd ON egcd.GivingId = tpfgids.GivingId
		LEFT JOIN @TempEntryGiftCountDurationLong egcdl ON egcdl.GivingId = tpfgids.GivingId
		LEFT JOIN @TempExitAttendanceCountDurationShort eacds ON eacds.FamilyId = tpfgids.FamilyId
		LEFT JOIN @TempEntryAttendanceCountDuration eacd ON eacd.FamilyId = tpfgids.FamilyId
		LEFT JOIN @TempExitAttendanceCountDurationLong eacdl ON eacdl.FamilyId = tpfgids.FamilyId
        ) AS t
    WHERE (
            ([IsEra] = 1)
            OR (
                (
                    [EntryGiftCountDurationLong] >= @EntryGiftCountDurationLong
                    AND [EntryGiftCountDurationShort] >= @EntryGiftCountDurationShort
                    )
                OR ([EntryAttendanceCountDuration] >= @EntryAttendanceCountDuration)
                )
            )
    GROUP BY [FamilyId]
END
