CREATE PROCEDURE [dbo].[spCrm_FamilyAnalyticsGiving]
	
AS
BEGIN
	
	-- configuration of the duration in weeks
	DECLARE @GivingDurationLongWeeks int = 52
	DECLARE @GivingDurationShortWeeks int = 6
	
	DECLARE @cACTIVE_RECORD_STATUS_VALUE_GUID uniqueidentifier = '618F906C-C33D-4FA3-8AEF-E58CB7B63F1E'
	DECLARE @cPERSON_RECORD_TYPE_VALUE_GUID uniqueidentifier = '36CF10D6-C695-413D-8E7C-4546EFEF385E'
	DECLARE @cFAMILY_GROUPTYPE_GUID uniqueidentifier = '790E3215-3B10-442B-AF69-616C0DCB998E'
	DECLARE @cADULT_ROLE_GUID uniqueidentifier = '2639F9A5-2AAE-4E48-A8C3-4FFE86681E42'	
	DECLARE @cCONTRIBUTION_TYPE_VALUE_GUID uniqueidentifier = '2D607262-52D6-4724-910D-5C6E8FB89ACC'
	DECLARE @cATTRIBUTE_FIRST_GAVE uniqueidentifier  = 'EE5EC76A-D4B9-56B5-4B48-29627D945F10'
	DECLARE @cATTRIBUTE_LAST_GAVE uniqueidentifier  = '02F64263-E290-399E-4487-FC236F4DE81F'
	DECLARE @cATTRIBUTE_GIFT_COUNT_SHORT uniqueidentifier  = 'AC11EF53-AE55-79A0-4CAD-43721750E988'
	DECLARE @cATTRIBUTE_GIFT_COUNT_LONG uniqueidentifier  = '57700E8F-ED11-D787-415A-04DDF411BB10'
	-- --------- END CONFIGURATION --------------
	DECLARE @ActiveRecordStatusValueId int = (SELECT TOP 1 [Id] FROM [DefinedValue] WHERE [Guid] = @cACTIVE_RECORD_STATUS_VALUE_GUID)
	DECLARE @PersonRecordTypeValueId int = (SELECT TOP 1 [Id] FROM [DefinedValue] WHERE [Guid] = @cPERSON_RECORD_TYPE_VALUE_GUID)
	DECLARE @FamilyGroupTypeId int = (SELECT TOP 1 [Id] FROM [GroupType] WHERE [Guid] = @cFAMILY_GROUPTYPE_GUID)
	DECLARE @AdultRoleId int = (SELECT TOP 1 [Id] FROM [GroupTypeRole] WHERE [Guid] = @cADULT_ROLE_GUID)
	DECLARE @ContributionTypeId int = (SELECT TOP 1 [Id] FROM [DefinedValue] WHERE [Guid] = @cCONTRIBUTION_TYPE_VALUE_GUID)
	
	-- calculate dates for queries
	DECLARE @SundayDateStart datetime = [dbo].[ufnUtility_GetPreviousSundayDate]()
	DECLARE @SundayGivingDurationLong datetime = DATEADD(DAY,  (7 * @GivingDurationLongWeeks * -1), @SundayDateStart)
	DECLARE @SundayGivingDurationShort datetime = DATEADD(DAY,  (7 * @GivingDurationShortWeeks * -1), @SundayDateStart);
	DECLARE @Now DATETIME = dbo.RockGetDate()

	-- first gift (people w/Giving Group)
	DECLARE @FirstGaveAttributeId int = (SELECT TOP 1 [Id] FROM [Attribute] WHERE [Guid] = @cATTRIBUTE_FIRST_GAVE);
	WITH
	    cteIndividual ([PersonId], [GivingGroupId], [FamilyRole])
	    AS
	    (
		SELECT p.[Id] AS [PersonId], p.[GivingGroupId], CASE WHEN fr.[FamilyRole] = @AdultRoleId THEN 'Adult' ELSE 'Child' END
		FROM [Person] p
		CROSS APPLY
			(
			SELECT TOP 1 gm.[GroupRoleId] AS [FamilyRole]
			FROM    
				[GroupMember] gm 
				INNER JOIN [Group] g ON g.[Id] = gm.[GroupId] AND g.[GroupTypeId] = @FamilyGroupTypeId
				INNER JOIN [GroupTypeRole] gtr ON gtr.[Id] = gm.[GroupRoleId]
			WHERE 
				gm.[PersonId] = p.[Id] 
				AND p.[GivingGroupId] IS NOT NULL
				AND gm.IsArchived = 0
                AND g.IsArchived = 0
			) fr
		WHERE
			[RecordTypeValueId] = @PersonRecordTypeValueId  -- person record type (not business)
	    )
		SELECT [PersonId], [FirstContributionDate], av.[Id] AttributeValueId, av.[ValueAsDateTime] ExistingValue
		INTO #firstGiftWithGroup
		FROM 
			(SELECT 
	    		[PersonId]
	    		, (SELECT MIN(ft.TransactionDateTime)
	    					FROM [FinancialTransaction] ft
	    						INNER JOIN [PersonAlias] pa ON pa.[Id] = ft.[AuthorizedPersonAliasId]
	    						INNER JOIN [Person] gp ON gp.[Id] = pa.[PersonId]
	    						INNER JOIN [FinancialTransactionDetail] ftd ON ftd.[TransactionId] = ft.[Id]
	    						INNER JOIN [FinancialAccount] fa ON fa.[Id] = ftd.AccountId
	    					WHERE 
	    						gp.[GivingGroupId] = i.[GivingGroupId]
	    						AND ft.TransactionTypeValueId = @ContributionTypeId) AS [FirstContributionDate]
	    	FROM cteIndividual i
	    	WHERE [FamilyRole] = 'Adult') AS g
		LEFT JOIN [AttributeValue] av ON av.[EntityId] = g.[PersonId]
		AND av.[AttributeId] = @FirstGaveAttributeId
	    WHERE g.[FirstContributionDate] IS NOT NULL

	-- Update Existing values before inserting to reduce number of logical reads.
	UPDATE av SET
		av.[Value] = f.[FirstContributionDate],
		av.[ValueAsDateTime] = f.[FirstContributionDate],
		av.[IsPersistedValueDirty] = 1
	FROM dbo.[AttributeValue] av
	JOIN #firstGiftWithGroup f on f.[AttributeValueId] = av.[Id]
	WHERE f.[ExistingValue] IS NULL
	OR f.[ExistingValue] <> f.[FirstContributionDate]

	-- Added new values.
	INSERT dbo.[AttributeValue] ([EntityId]
        , [AttributeId]
        , [Value]
        , [IsSystem]
        , [Guid]
        , [CreatedDateTime]
        , [ValueAsDateTime]
        , [IsPersistedValueDirty])
	SELECT f.[PersonId]
		, @FirstGaveAttributeId
		, f.[FirstContributionDate]
		, 0
		, newid()
		, @Now
		, f.[FirstContributionDate]
		, 1
	FROM #firstGiftWithGroup f
	WHERE f.[AttributeValueId] IS NULL

	-- Remove the temp table.
	DROP TABLE #firstGiftWithGroup

	-- first gift (people WITHOUT Giving Group)
	;WITH
	    cteIndividual ([PersonId], [GivingGroupId], [FamilyRole])
	    AS
	    (
		SELECT p.[Id] AS [PersonId], p.[GivingGroupId], CASE WHEN fr.[FamilyRole] = @AdultRoleId THEN 'Adult' ELSE 'Child' END
		FROM [Person] p
		CROSS APPLY
			(
			SELECT TOP 1 gm.[GroupRoleId] AS [FamilyRole]
			FROM    
				[GroupMember] gm 
				INNER JOIN [Group] g ON g.[Id] = gm.[GroupId] AND g.[GroupTypeId] = @FamilyGroupTypeId
				INNER JOIN [GroupTypeRole] gtr ON gtr.[Id] = gm.[GroupRoleId]
			WHERE 
				gm.[PersonId] = p.[Id] 
				AND p.[GivingGroupId] IS NULL
				AND gm.IsArchived = 0
                AND g.IsArchived = 0
			) fr
		WHERE
			[RecordTypeValueId] = @PersonRecordTypeValueId  -- person record type (not business)
	    )

		SELECT [PersonId], [FirstContributionDate], av.[Id] AttributeValueId, av.[ValueAsDateTime] ExistingValue
		INTO #firstGiftWithoutGroup
		FROM 
	    	(SELECT 
	    		[PersonId]
	    		, (SELECT MIN(ft.TransactionDateTime)
						FROM [FinancialTransaction] ft
							INNER JOIN [PersonAlias] pa ON pa.[Id] = ft.[AuthorizedPersonAliasId]
							INNER JOIN [Person] gp ON gp.[Id] = pa.[PersonId]
							INNER JOIN [FinancialTransactionDetail] ftd ON ftd.[TransactionId] = ft.[Id]
							INNER JOIN [FinancialAccount] fa ON fa.[Id] = ftd.AccountId
						WHERE 
							gp.[Id] = i.[PersonId] -- match by person id
							AND ft.TransactionTypeValueId = @ContributionTypeId) AS [FirstContributionDate]
	    	FROM cteIndividual i
	    	WHERE [FamilyRole] = 'Adult') AS g
		LEFT JOIN [AttributeValue] av ON av.[EntityId] = g.[PersonId]
		AND av.[AttributeId] = @FirstGaveAttributeId
	    WHERE g.[FirstContributionDate] IS NOT NULL

	-- Update Existing values before inserting to reduce number of logical reads.
	UPDATE av SET
		av.[Value] = f.[FirstContributionDate],
		av.[ValueAsDateTime] = f.[FirstContributionDate],
		av.[IsPersistedValueDirty] = 1
	FROM dbo.[AttributeValue] av
	JOIN #firstGiftWithoutGroup f on f.[AttributeValueId] = av.[Id]
	WHERE f.[ExistingValue] IS NULL
	OR f.[ExistingValue] <> f.[FirstContributionDate]

	-- Added new values.
	INSERT dbo.[AttributeValue] ([EntityId]
        , [AttributeId]
        , [Value]
        , [IsSystem]
        , [Guid]
        , [CreatedDateTime]
        , [ValueAsDateTime]
        , [IsPersistedValueDirty])
	SELECT f.[PersonId]
		, @FirstGaveAttributeId
		, f.[FirstContributionDate]
		, 0
		, newid()
		, @Now
		, f.[FirstContributionDate]
		, 1
	FROM #firstGiftWithoutGroup f
	WHERE f.[AttributeValueId] IS NULL

	-- Remove the temp table.
	DROP TABLE #firstGiftWithoutGroup
	
	-- last gift (people w/Giving Group)
	DECLARE @LastGaveAttributeId int = (SELECT TOP 1 [Id] FROM [Attribute] WHERE [Guid] = @cATTRIBUTE_LAST_GAVE);
	WITH
	    cteIndividual ([PersonId], [GivingGroupId], [FamilyRole])
	    AS
	    (
		SELECT p.[Id] AS [PersonId], p.[GivingGroupId], CASE WHEN fr.[FamilyRole] = @AdultRoleId THEN 'Adult' ELSE 'Child' END
		FROM [Person] p
		CROSS APPLY
			(
			SELECT TOP 1 gm.[GroupRoleId] AS [FamilyRole]
			FROM    
				[GroupMember] gm 
				INNER JOIN [Group] g ON g.[Id] = gm.[GroupId] AND g.[GroupTypeId] = @FamilyGroupTypeId
				INNER JOIN [GroupTypeRole] gtr ON gtr.[Id] = gm.[GroupRoleId]
			WHERE 
				gm.[PersonId] = p.[Id] 
				AND p.[GivingGroupId] IS NOT NULL
				AND gm.IsArchived = 0
                AND g.IsArchived = 0
			) fr
		WHERE
			[RecordTypeValueId] = @PersonRecordTypeValueId  -- person record type (not business)
	    )

		SELECT [PersonId], [LastContributionDate], av.[Id] AttributeValueId, av.[ValueAsDateTime] ExistingValue
		INTO #lastGiftWithGroup
		FROM 
	    	(SELECT 
	    		[PersonId]
	    		, (SELECT MAX(ft.TransactionDateTime)
						FROM [FinancialTransaction] ft
							INNER JOIN [PersonAlias] pa ON pa.[Id] = ft.[AuthorizedPersonAliasId]
							INNER JOIN [Person] gp ON gp.[Id] = pa.[PersonId]
							INNER JOIN [FinancialTransactionDetail] ftd ON ftd.[TransactionId] = ft.[Id]
							INNER JOIN [FinancialAccount] fa ON fa.[Id] = ftd.AccountId
						WHERE 
							gp.[GivingGroupId] = i.[GivingGroupId]
							AND ft.TransactionTypeValueId = @ContributionTypeId) AS [LastContributionDate]
	    	FROM cteIndividual i
	    	WHERE [FamilyRole] = 'Adult') AS g
		LEFT JOIN [AttributeValue] av ON av.[EntityId] = g.[PersonId]
		AND av.[AttributeId] = @LastGaveAttributeId
	    WHERE g.[LastContributionDate] IS NOT NULL

	-- Update Existing values before inserting to reduce number of logical reads.
	UPDATE av SET
		av.[Value] = f.[LastContributionDate],
		av.[ValueAsDateTime] = f.[LastContributionDate],
		av.[IsPersistedValueDirty] = 1
	FROM dbo.[AttributeValue] av
	JOIN #lastGiftWithGroup f on f.[AttributeValueId] = av.[Id]
	WHERE f.[ExistingValue] IS NULL
	OR f.[ExistingValue] <> f.[LastContributionDate]

	-- Added new values.
	INSERT dbo.[AttributeValue] ([EntityId]
        , [AttributeId]
        , [Value]
        , [IsSystem]
        , [Guid]
        , [CreatedDateTime]
        , [ValueAsDateTime]
        , [IsPersistedValueDirty])
	SELECT f.[PersonId]
		, @LastGaveAttributeId
		, f.[LastContributionDate]
		, 0
		, newid()
		, @Now
		, f.[LastContributionDate]
		, 1
	FROM #lastGiftWithGroup f
	WHERE f.[AttributeValueId] IS NULL

	-- Remove the temp table.
	DROP TABLE #lastGiftWithGroup

	-- last gift (people WITHOUT Giving Group)
	;WITH
	    cteIndividual ([PersonId], [GivingGroupId], [FamilyRole])
	    AS
	    (
		SELECT p.[Id] AS [PersonId], p.[GivingGroupId], CASE WHEN fr.[FamilyRole] = @AdultRoleId THEN 'Adult' ELSE 'Child' END
		FROM [Person] p
		CROSS APPLY
			(
			SELECT TOP 1 gm.[GroupRoleId] AS [FamilyRole]
			FROM    
				[GroupMember] gm 
				INNER JOIN [Group] g ON g.[Id] = gm.[GroupId] AND g.[GroupTypeId] = @FamilyGroupTypeId
				INNER JOIN [GroupTypeRole] gtr ON gtr.[Id] = gm.[GroupRoleId]
			WHERE 
				gm.[PersonId] = p.[Id] -- match by person id
				AND p.[GivingGroupId] IS NULL
				AND gm.IsArchived = 0
                AND g.IsArchived = 0
			) fr
		WHERE
			[RecordTypeValueId] = @PersonRecordTypeValueId  -- person record type (not business)
	    )

		SELECT [PersonId], [LastContributionDate], av.[Id] AttributeValueId, av.[ValueAsDateTime] ExistingValue
		INTO #lastGiftWithoutGroup
		FROM 
	    	(SELECT 
	    		[PersonId]
	    		, (SELECT MAX(ft.TransactionDateTime)
						FROM [FinancialTransaction] ft
							INNER JOIN [PersonAlias] pa ON pa.[Id] = ft.[AuthorizedPersonAliasId]
							INNER JOIN [Person] gp ON gp.[Id] = pa.[PersonId]
							INNER JOIN [FinancialTransactionDetail] ftd ON ftd.[TransactionId] = ft.[Id]
							INNER JOIN [FinancialAccount] fa ON fa.[Id] = ftd.AccountId
						WHERE 
							gp.[Id] = i.[PersonId]
							AND ft.TransactionTypeValueId = @ContributionTypeId) AS [LastContributionDate]
	    	FROM cteIndividual i
	    	WHERE [FamilyRole] = 'Adult') AS g
		LEFT JOIN [AttributeValue] av ON av.[EntityId] = g.[PersonId]
		AND av.[AttributeId] = @LastGaveAttributeId
	    WHERE g.[LastContributionDate] IS NOT NULL

	-- Update Existing values before inserting to reduce number of logical reads.
	UPDATE av SET
		av.[Value] = f.[LastContributionDate],
		av.[ValueAsDateTime] = f.[LastContributionDate],
		av.[IsPersistedValueDirty] = 1
	FROM dbo.[AttributeValue] av
	JOIN #lastGiftWithoutGroup f on f.[AttributeValueId] = av.[Id]
	WHERE f.[ExistingValue] IS NULL
	OR f.[ExistingValue] <> f.[LastContributionDate]

	-- Added new values.
	INSERT dbo.[AttributeValue] ([EntityId]
        , [AttributeId]
        , [Value]
        , [IsSystem]
        , [Guid]
        , [CreatedDateTime]
        , [ValueAsDateTime]
        , [IsPersistedValueDirty])
	SELECT f.[PersonId]
		, @LastGaveAttributeId
		, f.[LastContributionDate]
		, 0
		, newid()
		, @Now
		, f.[LastContributionDate]
		, 1
	FROM #lastGiftWithoutGroup f
	WHERE f.[AttributeValueId] IS NULL

	-- Remove the temp table.
	DROP TABLE #lastGiftWithoutGroup

	-- number of gifts short duration (people w/Giving Group)
	DECLARE @GiftCountShortAttributeId int = (SELECT TOP 1 [Id] FROM [Attribute] WHERE [Guid] = @cATTRIBUTE_GIFT_COUNT_SHORT);
	WITH
	    cteIndividual ([PersonId], [GivingGroupId], [FamilyRole])
	    AS
	    (
		SELECT p.[Id] AS [PersonId], p.[GivingGroupId], CASE WHEN fr.[FamilyRole] = @AdultRoleId THEN 'Adult' ELSE 'Child' END
		FROM [Person] p
		CROSS APPLY
			(
			SELECT TOP 1 gm.[GroupRoleId] AS [FamilyRole]
			FROM    
				[GroupMember] gm 
				INNER JOIN [Group] g ON g.[Id] = gm.[GroupId] AND g.[GroupTypeId] = @FamilyGroupTypeId
				INNER JOIN [GroupTypeRole] gtr ON gtr.[Id] = gm.[GroupRoleId]
			WHERE 
				gm.[PersonId] = p.[Id] 
				AND p.[GivingGroupId] IS NOT NULL
				AND gm.IsArchived = 0
                AND g.IsArchived = 0
			) fr
		WHERE
			[RecordStatusValueId] = @ActiveRecordStatusValueId -- record is active
			AND [RecordTypeValueId] = @PersonRecordTypeValueId  -- person record type (not business)
	    )

		SELECT [PersonId], [GiftCountDurationShort], av.[Id] AttributeValueId, av.[ValueAsDateTime] ExistingValue
		INTO #giftCountShortWithGroup
		FROM 
	    	(SELECT 
	    		[PersonId]
	    		, (SELECT COUNT(DISTINCT(ft.[Id])) 
						FROM [FinancialTransaction] ft
							INNER JOIN [PersonAlias] pa ON pa.[Id] = ft.[AuthorizedPersonAliasId]
							INNER JOIN [Person] gp ON gp.[Id] = pa.[PersonId]
							INNER JOIN [FinancialTransactionDetail] ftd ON ftd.[TransactionId] = ft.[Id]
							INNER JOIN [FinancialAccount] fa ON fa.[Id] = ftd.AccountId
						WHERE 
							gp.[GivingGroupId] = i.[GivingGroupId]
							AND ft.TransactionTypeValueId = @ContributionTypeId
							AND ft.TransactionDateTime >= @SundayGivingDurationShort
							AND ft.SundayDate <= @SundayDateStart) AS [GiftCountDurationShort]
	    	FROM cteIndividual i
	    	WHERE [FamilyRole] = 'Adult') AS g
		LEFT JOIN [AttributeValue] av ON av.[EntityId] = g.[PersonId]
		AND av.[AttributeId] = @GiftCountShortAttributeId
	    WHERE g.[GiftCountDurationShort] IS NOT NULL

	-- Update Existing values before inserting to reduce number of logical reads.
	UPDATE av SET
		av.[Value] = f.[GiftCountDurationShort],
		av.[ValueAsNumeric] = f.[GiftCountDurationShort],
		av.[IsPersistedValueDirty] = 1
	FROM dbo.[AttributeValue] av
	JOIN #giftCountShortWithGroup f on f.[AttributeValueId] = av.[Id]
	WHERE f.[ExistingValue] IS NULL
	OR f.[ExistingValue] <> f.[GiftCountDurationShort]

	-- Added new values.
	INSERT dbo.[AttributeValue] ([EntityId]
        , [AttributeId]
        , [Value]
        , [IsSystem]
        , [Guid]
        , [CreatedDateTime]
        , [ValueAsNumeric]
        , [IsPersistedValueDirty])
	SELECT f.[PersonId]
		, @GiftCountShortAttributeId
		, f.[GiftCountDurationShort]
		, 0
		, newid()
		, @Now
		, f.[GiftCountDurationShort]
		, 1
	FROM #giftCountShortWithGroup f
	WHERE f.[AttributeValueId] IS NULL

    -- Remove the temp table.
	DROP TABLE #giftCountShortWithGroup

	-- number of gifts short duration (people WITHOUT Giving Group)
	;WITH
	    cteIndividual ([PersonId], [GivingGroupId], [FamilyRole])
	    AS
	    (
		SELECT p.[Id] AS [PersonId], p.[GivingGroupId], CASE WHEN fr.[FamilyRole] = @AdultRoleId THEN 'Adult' ELSE 'Child' END
		FROM [Person] p
		CROSS APPLY
			(
			SELECT TOP 1 gm.[GroupRoleId] AS [FamilyRole]
			FROM    
				[GroupMember] gm 
				INNER JOIN [Group] g ON g.[Id] = gm.[GroupId] AND g.[GroupTypeId] = @FamilyGroupTypeId
				INNER JOIN [GroupTypeRole] gtr ON gtr.[Id] = gm.[GroupRoleId]
			WHERE 
				gm.[PersonId] = p.[Id] 
				AND p.[GivingGroupId] IS NULL
				AND gm.IsArchived = 0
                AND g.IsArchived = 0
			) fr
		WHERE
			[RecordStatusValueId] = @ActiveRecordStatusValueId -- record is active
			AND [RecordTypeValueId] = @PersonRecordTypeValueId  -- person record type (not business)
	    )

		SELECT [PersonId], [GiftCountDurationShort], av.[Id] AttributeValueId, av.[ValueAsDateTime] ExistingValue
		INTO #giftCountShortWithoutGroup
		FROM 
	    	(SELECT 
	    		[PersonId]
	    		, (SELECT COUNT(DISTINCT(ft.[Id])) 
						FROM [FinancialTransaction] ft
							INNER JOIN [PersonAlias] pa ON pa.[Id] = ft.[AuthorizedPersonAliasId]
							INNER JOIN [Person] gp ON gp.[Id] = pa.[PersonId]
							INNER JOIN [FinancialTransactionDetail] ftd ON ftd.[TransactionId] = ft.[Id]
							INNER JOIN [FinancialAccount] fa ON fa.[Id] = ftd.AccountId
						WHERE 
							gp.[Id] = i.[PersonId] -- match by person id
							AND ft.TransactionTypeValueId = @ContributionTypeId
							AND ft.TransactionDateTime >= @SundayGivingDurationShort
							AND ft.SundayDate <= @SundayDateStart) AS [GiftCountDurationShort]
	    	FROM cteIndividual i
	    	WHERE [FamilyRole] = 'Adult') AS g
		LEFT JOIN [AttributeValue] av ON av.[EntityId] = g.[PersonId]
		AND av.[AttributeId] = @GiftCountShortAttributeId
	    WHERE g.[GiftCountDurationShort] IS NOT NULL

	-- Update Existing values before inserting to reduce number of logical reads.
	UPDATE av SET
		av.[Value] = f.[GiftCountDurationShort],
		av.[ValueAsNumeric] = f.[GiftCountDurationShort],
		av.[IsPersistedValueDirty] = 1
	FROM dbo.[AttributeValue] av
	JOIN #giftCountShortWithoutGroup f on f.[AttributeValueId] = av.[Id]
	WHERE f.[ExistingValue] IS NULL
	OR f.[ExistingValue] <> f.[GiftCountDurationShort]

	-- Added new values.
	INSERT dbo.[AttributeValue] ([EntityId]
        , [AttributeId]
        , [Value]
        , [IsSystem]
        , [Guid]
        , [CreatedDateTime]
        , [ValueAsNumeric]
        , [IsPersistedValueDirty])
	SELECT f.[PersonId]
		, @GiftCountShortAttributeId
		, f.[GiftCountDurationShort]
		, 0
		, newid()
		, @Now
		, f.[GiftCountDurationShort]
		, 1
	FROM #giftCountShortWithoutGroup f
	WHERE f.[AttributeValueId] IS NULL

    -- Remove the temp table.
	DROP TABLE #giftCountShortWithoutGroup

	-- number of gifts long duration (people w/Giving Group)
	DECLARE @GiftCountLongAttributeId int = (SELECT TOP 1 [Id] FROM [Attribute] WHERE [Guid] = @cATTRIBUTE_GIFT_COUNT_LONG);
	WITH
	    cteIndividual ([PersonId], [GivingGroupId], [FamilyRole])
	    AS
	    (
		SELECT p.[Id] AS [PersonId], p.[GivingGroupId], CASE WHEN fr.[FamilyRole] = @AdultRoleId THEN 'Adult' ELSE 'Child' END
		FROM [Person] p
		CROSS APPLY
			(
			SELECT TOP 1 gm.[GroupRoleId] AS [FamilyRole]
			FROM    
				[GroupMember] gm 
				INNER JOIN [Group] g ON g.[Id] = gm.[GroupId] AND g.[GroupTypeId] = @FamilyGroupTypeId
				INNER JOIN [GroupTypeRole] gtr ON gtr.[Id] = gm.[GroupRoleId]
			WHERE 
				gm.[PersonId] = p.[Id] 
				AND p.[GivingGroupId] IS NOT NULL
				AND gm.IsArchived = 0
                AND g.IsArchived = 0
			) fr
		WHERE
			[RecordStatusValueId] = @ActiveRecordStatusValueId -- record is active
			AND [RecordTypeValueId] = @PersonRecordTypeValueId  -- person record type (not business)
	  )

		SELECT [PersonId], [GiftCountDurationLong], av.[Id] AttributeValueId, av.[ValueAsDateTime] ExistingValue
		INTO #giftCountLongWithGroup
		FROM 
	    	(SELECT 
	    		[PersonId]
	    		, (SELECT COUNT(DISTINCT(ft.[Id])) 
						FROM [FinancialTransaction] ft
							INNER JOIN [PersonAlias] pa ON pa.[Id] = ft.[AuthorizedPersonAliasId]
							INNER JOIN [Person] gp ON gp.[Id] = pa.[PersonId]
							INNER JOIN [FinancialTransactionDetail] ftd ON ftd.[TransactionId] = ft.[Id]
							INNER JOIN [FinancialAccount] fa ON fa.[Id] = ftd.AccountId
						WHERE 
							gp.[GivingGroupId] = i.[GivingGroupId]
							AND ft.TransactionTypeValueId = @ContributionTypeId
							AND ft.TransactionDateTime >= @SundayGivingDurationLong
							AND ft.SundayDate <= @SundayDateStart) AS [GiftCountDurationLong]
	    	FROM cteIndividual i
	    	WHERE [FamilyRole] = 'Adult') AS g
		LEFT JOIN [AttributeValue] av ON av.[EntityId] = g.[PersonId]
		AND av.[AttributeId] = @GiftCountLongAttributeId
	    WHERE g.[GiftCountDurationLong] IS NOT NULL

	-- Update Existing values before inserting to reduce number of logical reads.
	UPDATE av SET
		av.[Value] = f.[GiftCountDurationLong],
		av.[ValueAsNumeric] = f.[GiftCountDurationLong],
		av.[IsPersistedValueDirty] = 1
	FROM dbo.[AttributeValue] av
	JOIN #giftCountLongWithGroup f on f.[AttributeValueId] = av.[Id]
	WHERE f.[ExistingValue] IS NULL
	OR f.[ExistingValue] <> f.[GiftCountDurationLong]

	-- Added new values.
	INSERT dbo.[AttributeValue] ([EntityId]
        , [AttributeId]
        , [Value]
        , [IsSystem]
        , [Guid]
        , [CreatedDateTime]
        , [ValueAsNumeric]
        , [IsPersistedValueDirty])
	SELECT f.[PersonId]
		, @GiftCountLongAttributeId
		, f.[GiftCountDurationLong]
		, 0
		, newid()
		, @Now
		, f.[GiftCountDurationLong]
		, 1
	FROM #giftCountLongWithGroup f
	WHERE f.[AttributeValueId] IS NULL

    -- Remove the temp table.
	DROP TABLE #giftCountLongWithGroup
	
	-- number of gifts long duration (people WITHOUT Giving Group)
	;WITH
	    cteIndividual ([PersonId], [GivingGroupId], [FamilyRole])
	    AS
	    (
		SELECT p.[Id] AS [PersonId], p.[GivingGroupId], CASE WHEN fr.[FamilyRole] = @AdultRoleId THEN 'Adult' ELSE 'Child' END
		FROM [Person] p
		CROSS APPLY
			(
			SELECT TOP 1 gm.[GroupRoleId] AS [FamilyRole]
			FROM    
				[GroupMember] gm 
				INNER JOIN [Group] g ON g.[Id] = gm.[GroupId] AND g.[GroupTypeId] = @FamilyGroupTypeId
				INNER JOIN [GroupTypeRole] gtr ON gtr.[Id] = gm.[GroupRoleId]
			WHERE 
				gm.[PersonId] = p.[Id] 
				AND p.[GivingGroupId] IS NULL
				AND gm.IsArchived = 0
                AND g.IsArchived = 0
			) fr
		WHERE
			[RecordStatusValueId] = @ActiveRecordStatusValueId -- record is active
			AND [RecordTypeValueId] = @PersonRecordTypeValueId  -- person record type (not business)
	    )

		SELECT [PersonId], [GiftCountDurationLong], av.[Id] AttributeValueId, av.[ValueAsDateTime] ExistingValue
		INTO #giftCountLongWithoutGroup
		FROM 
	    	(SELECT 
	    		[PersonId]
	    		, (SELECT COUNT(DISTINCT(ft.[Id])) 
						FROM [FinancialTransaction] ft
							INNER JOIN [PersonAlias] pa ON pa.[Id] = ft.[AuthorizedPersonAliasId]
							INNER JOIN [Person] gp ON gp.[Id] = pa.[PersonId]
							INNER JOIN [FinancialTransactionDetail] ftd ON ftd.[TransactionId] = ft.[Id]
							INNER JOIN [FinancialAccount] fa ON fa.[Id] = ftd.AccountId
						WHERE 
							gp.[Id] = i.[PersonId] -- match by person id
							AND ft.TransactionTypeValueId = @ContributionTypeId
							AND ft.TransactionDateTime >= @SundayGivingDurationLong
							AND ft.SundayDate <= @SundayDateStart) AS [GiftCountDurationLong]
	    		, 0 AS [IsSystem]
	    		, newid() AS [Guid]
	    	FROM cteIndividual i
	    	WHERE [FamilyRole] = 'Adult') AS g
		LEFT JOIN [AttributeValue] av ON av.[EntityId] = g.[PersonId]
		AND av.[AttributeId] = @GiftCountLongAttributeId
	    WHERE g.[GiftCountDurationLong] IS NOT NULL

	-- Update Existing values before inserting to reduce number of logical reads.
	UPDATE av SET
		av.[Value] = f.[GiftCountDurationLong],
		av.[ValueAsNumeric] = f.[GiftCountDurationLong],
		av.[IsPersistedValueDirty] = 1
	FROM dbo.[AttributeValue] av
	JOIN #giftCountLongWithoutGroup f on f.[AttributeValueId] = av.[Id]
	WHERE f.[ExistingValue] IS NULL
	OR f.[ExistingValue] <> f.[GiftCountDurationLong]

	-- Added new values.
	INSERT dbo.[AttributeValue] ([EntityId]
        , [AttributeId]
        , [Value]
        , [IsSystem]
        , [Guid]
        , [CreatedDateTime]
        , [ValueAsNumeric]
        , [IsPersistedValueDirty])
	SELECT f.[PersonId]
		, @GiftCountLongAttributeId
		, f.[GiftCountDurationLong]
		, 0
		, newid()
		, @Now
		, f.[GiftCountDurationLong]
		, 1
	FROM #giftCountLongWithoutGroup f
	WHERE f.[AttributeValueId] IS NULL

    -- Remove the temp table.
	DROP TABLE #giftCountLongWithoutGroup
END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*
<doc>
	<summary>
 		This stored procedure attempts to update an indivdiual's first and second visit
		attributes. Below are a few points of interest on the logic.

		+ A child's date will only be calculated looking at their check-in data.
		+ An adult's date will be calculated looking at the check-in data of all the children.

		+ When calculating a first-visit date it will only write the date if the first checkin date
		  is within 14 days of the record being created. This helps eliminate bad first-time visit dates
		  for adults who have attended for quite some time and then have a child later.
		  
	</summary>

	<returns>
	</returns>
	<remarks>
		
	</remarks>
	<code>
		EXEC [dbo].[spCrm_FamilyAnalyticsFirstVisitsAttributeUpdate] 
	</code>
</doc>
*/

CREATE PROCEDURE [dbo].[spCrm_FamilyAnalyticsUpdateVisitDates]
AS

DECLARE @FirstVisitAttributeId int = (SELECT [Id] FROM [Attribute] WHERE [Guid] = '655D6FBA-F8C0-4919-9E31-C1C936653555')
DECLARE @SecondVisitAttributeId int = (SELECT [Id] FROM [Attribute] WHERE [Guid] = 'D7EA578F-0132-473E-8338-4A48DDB8BF66')

DECLARE @AdultRoleId int = (SELECT TOP 1 [Id] FROM [GroupTypeRole] WHERE [Guid] = '2639F9A5-2AAE-4E48-A8C3-4FFE86681E42')
DECLARE @ChildRoleId int = (SELECT TOP 1 [Id] FROM [GroupTypeRole] WHERE [Guid] = 'C8B1814F-6AA7-4055-B2D7-48FE20429CB9')

-- clean up any empty attribute values
DELETE FROM [AttributeValue] WHERE ([Value] = '' OR [Value] IS NULL) AND AttributeId = @FirstVisitAttributeId
DELETE FROM [AttributeValue] WHERE ([Value] = '' OR [Value] IS NULL) AND AttributeId = @SecondVisitAttributeId

--
-- FIRST VISIT DATES
--
-- update children's records with their specific first visit date
IF @FirstVisitAttributeId IS NOT NULL
BEGIN
	INSERT INTO [AttributeValue]
	([IsSystem], [AttributeId], [EntityId], [Value], [Guid], [CreatedDateTime], [ValueAsDateTime], [IsPersistedValueDirty])
	SELECT 1, @FirstVisitAttributeId, p.Id, CONVERT(varchar(50), a.FirstVisit, 126), newid(), getdate(), a.FirstVisit, 1
	FROM [Person] p
	CROSS APPLY ( 
		SELECT 
			MIN([StartDateTime]) [FirstVisit]
		FROM
			[Attendance] a
			INNER JOIN [AttendanceOccurrence] O ON O.[Id] = A.[OccurrenceId]
			INNER JOIN [PersonAlias] pa ON pa.[Id] = a.[PersonAliasId]
		WHERE 
			O.[GroupId] IN (SELECT [Id] FROM [dbo].[ufnCheckin_WeeklyServiceGroups]())
			AND a.[DidAttend] = 1
			AND pa.[PersonId] = p.[Id]
	) a
	WHERE
		p.[Id] NOT IN (SELECT [EntityId] FROM [AttributeValue] WHERE [AttributeId] = @FirstVisitAttributeId )
		AND a.FirstVisit < DATEADD(d, 14, p.CreatedDateTime)
	
	-- next process adults (they look at the first visit of anyone in the family)
	INSERT INTO [AttributeValue]
	([IsSystem], [AttributeId], [EntityId], [Value], [Guid], [CreatedDateTime], [ValueAsDateTime], [IsPersistedValueDirty])
	SELECT 1, @FirstVisitAttributeId, p.Id, MIN(CONVERT(varchar(50), a.FirstVisit, 126)), newid(), getdate(), MIN(a.FirstVisit), 1
	FROM [Person] p
	INNER JOIN [GroupMember] gm ON gm.[PersonId] = p.[Id] AND gm.[GroupRoleId] = @AdultRoleId
	CROSS APPLY ( 
		SELECT 
			MIN([StartDateTime]) [FirstVisit]
		FROM
			[Attendance] a
			INNER JOIN [AttendanceOccurrence] O ON O.[Id] = A.[OccurrenceId]
			INNER JOIN [PersonAlias] pa ON pa.[Id] = a.[PersonAliasId]
			INNER JOIN [GroupMember] agm ON agm.[PersonId] = pa.[PersonId] AND agm.[GroupRoleId] = @ChildRoleId
		WHERE 
			O.[GroupId] IN (SELECT [Id] FROM [dbo].[ufnCheckin_WeeklyServiceGroups]())
			AND a.[DidAttend] = 1
			AND agm.[GroupId] = gm.[GroupId]
	) a
	WHERE
		p.[Id] NOT IN (SELECT [EntityId] FROM [AttributeValue] WHERE [AttributeId] = @FirstVisitAttributeId)
	GROUP BY p.[Id]
END
--
-- SECOND VISIT DATES
--
-- update children's records with their specific first visit date
IF @SecondVisitAttributeId IS NOT NULL
BEGIN
	INSERT INTO [AttributeValue]
	([IsSystem], [AttributeId], [EntityId], [Value], [Guid], [CreatedDateTime], [ValueAsDateTime], [IsPersistedValueDirty] )
	SELECT 1, @SecondVisitAttributeId, p.Id, CONVERT(varchar(50), a.[SecondVisit], 126), newid(), getdate(), [SecondVisit], 1
	FROM [Person] p
	CROSS APPLY ( 
		SELECT 
			MIN([StartDateTime]) [SecondVisit]
		FROM
			[Attendance] a
			INNER JOIN [AttendanceOccurrence] O ON O.[Id] = A.[OccurrenceId]
			INNER JOIN [PersonAlias] pa ON pa.[Id] = a.[PersonAliasId]
		WHERE 
			O.[GroupId] IN (SELECT [Id] FROM [dbo].[ufnCheckin_WeeklyServiceGroups]())
			AND pa.[PersonId] = p.[Id]
			AND a.[DidAttend] = 1
			AND CONVERT(date, a.[StartDateTime]) > (SELECT MAX([ValueAsDateTime]) FROM [AttributeValue] WHERE [AttributeId] = @FirstVisitAttributeId AND [EntityId] = pa.[PersonId] AND [IsSystem] = 1)
	) a
	WHERE
		p.[Id] NOT IN (SELECT [EntityId] FROM [AttributeValue] WHERE [AttributeId] = @SecondVisitAttributeId )
		AND p.[Id] IN (SELECT [EntityId] FROM [AttributeValue] WHERE [AttributeId] = @FirstVisitAttributeId AND [ValueAsDateTime] IS NOT NULL )
		AND a.[SecondVisit] IS NOT NULL

	
	-- next process adults (they look at the first visit of anyone in the family)
	INSERT INTO [AttributeValue]
	([IsSystem], [AttributeId], [EntityId], [Value], [Guid], [CreatedDateTime], [ValueAsDateTime], [IsPersistedValueDirty])
	SELECT 1, @SecondVisitAttributeId, p.[Id], MIN(CONVERT(varchar(50), a.[SecondVisit], 126)), newid(), getdate(), MIN([SecondVisit]), 1
	FROM [Person] p
	INNER JOIN [GroupMember] gm ON gm.[PersonId] = p.[Id] AND gm.[GroupRoleId] = @AdultRoleId
	CROSS APPLY ( 
		SELECT 
			MIN([StartDateTime]) [SecondVisit]
		FROM
			[Attendance] a
			INNER JOIN [AttendanceOccurrence] O ON O.[Id] = A.[OccurrenceId]
			INNER JOIN [PersonAlias] pa ON pa.[Id] = a.[PersonAliasId]
			INNER JOIN [GroupMember] agm ON agm.[PersonId] = pa.[PersonId] AND agm.[GroupRoleId] = @ChildRoleId
		WHERE 
			O.[GroupId] IN (SELECT [Id] FROM [dbo].[ufnCheckin_WeeklyServiceGroups]())
			AND agm.[GroupId] = gm.[GroupId]
			AND a.[DidAttend] = 1
			AND CONVERT(date, a.[StartDateTime]) > (SELECT MAX([ValueAsDateTime]) FROM [AttributeValue] WHERE [AttributeId] = @FirstVisitAttributeId AND [EntityId] = pa.[PersonId] AND [IsSystem] = 1)
	) a
	WHERE
		p.[Id] NOT IN (SELECT [EntityId] FROM [AttributeValue] WHERE [AttributeId] = @SecondVisitAttributeId )
		AND p.[Id] IN (SELECT [EntityId] FROM [AttributeValue] WHERE [AttributeId] = @FirstVisitAttributeId AND [ValueAsDateTime] IS NOT NULL )
		AND a.[SecondVisit] IS NOT NULL
	GROUP BY p.[Id]
END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*
<doc>
 <summary>
   This stored procedure detects potential duplicate person records and stores the results in [PersonDuplicate]
 </summary>
 
 <remarks> 
  Uses the following constants:
   * Group Type - Family: '790E3215-3B10-442B-AF69-616C0DCB998E'
            * Location Type - Home: '8C52E53C-2A66-435A-AE6E-5EE307D9A0DC'
            * Phone Type - Home: 'AA8732FB-2CEA-4C76-8D6D-6AAA2C6A4303'
            * Phone Type - Cell: '407E7E45-7B2E-4FCD-9605-ECB1339F2453'
 </remarks>
 <code>
  EXEC [dbo].[spCrm_PersonDuplicateFinder]
 </code>
</doc>
*/
CREATE PROCEDURE [dbo].[spCrm_PersonDuplicateFinder]
AS
BEGIN
    
 SET NOCOUNT ON
 -- DECLARE @ms DATETIME = GETDATE()
    -- Flags that enable the various compare functions
    DECLARE @compareByEmail BIT = 1
        ,@compareByPartialName BIT = 1
        ,@compareByFullFirstName BIT = 1
        ,@compareByFullLastName BIT = 1
        ,@compareByPhone BIT = 1
        ,@compareByAddress BIT = 1
        ,@compareByBirthDate BIT = 1
        ,@compareByGender BIT = 1
        ,@compareByCampus BIT = 1
        ,@compareByMaritalStatus BIT = 1
        ,@compareBySuffix BIT = 1
    --
    -- Scores
    -- ones marked /**/ only added to score if already a potential match
    DECLARE @cScoreWeightEmail INT = 4
        ,@cScoreWeightPartialName INT = 1
        ,@cScoreWeightFullFirstName INT = 3 /**/
        ,@cScoreWeightFullLastName INT = 3 /**/
        ,@cScoreWeightCellPhoneNumber INT = 4
        ,@cScoreWeightNonCellPhoneNumber INT = 2
        ,@cScoreWeightAddress INT = 2
        ,@cScoreWeightBirthdate INT = 3 /**/
        ,@cScoreWeightGender INT = 1 /**/
        ,@cScoreWeightCampus INT = 1 /**/
        ,@cScoreWeightMaritalStatus INT = 1 /**/
        ,@cScoreWeightSuffix INT = 4
    DECLARE @TotalCapacity INT = @cScoreWeightEmail + @cScoreWeightPartialName + @cScoreWeightFullFirstName + @cScoreWeightFullLastName + @cScoreWeightCellPhoneNumber + @cScoreWeightNonCellPhoneNumber + @cScoreWeightAddress + @cScoreWeightBirthdate + @cScoreWeightGender + @cScoreWeightCampus + @cScoreWeightMaritalStatus + @cScoreWeightSuffix
    --
    -- Guids that this proc uses
    DECLARE @cGROUPTYPE_FAMILY_GUID UNIQUEIDENTIFIER = '790E3215-3B10-442B-AF69-616C0DCB998E'
        ,@cLOCATION_TYPE_HOME_GUID UNIQUEIDENTIFIER = '8C52E53C-2A66-435A-AE6E-5EE307D9A0DC'
        ,@cHOME_PHONENUMBER_DEFINEDVALUE_GUID UNIQUEIDENTIFIER = 'AA8732FB-2CEA-4C76-8D6D-6AAA2C6A4303'
        ,@cCELL_PHONENUMBER_DEFINEDVALUE_GUID UNIQUEIDENTIFIER = '407E7E45-7B2E-4FCD-9605-ECB1339F2453'
    --
    -- Other Declarations
    DECLARE @processDateTime DATETIME = SYSDATETIME()
        ,@cHOME_PHONENUMBER_DEFINEDVALUE_ID INT = (
            SELECT TOP 1 [Id]
            FROM [DefinedValue]
            WHERE [Guid] = @cHOME_PHONENUMBER_DEFINEDVALUE_GUID
            )
        ,@cCELL_PHONENUMBER_DEFINEDVALUE_ID INT = (
            SELECT TOP 1 [Id]
            FROM [DefinedValue]
            WHERE [Guid] = @cCELL_PHONENUMBER_DEFINEDVALUE_GUID
            )
        ,@cGROUPTYPE_FAMILY_ID INT = (
            SELECT TOP 1 [Id]
            FROM GroupType
            WHERE [Guid] = @cGROUPTYPE_FAMILY_GUID
            )
        ,@cLOCATION_TYPE_HOME_ID INT = (
            SELECT TOP 1 [Id]
            FROM DefinedValue
            WHERE [Guid] = @cLOCATION_TYPE_HOME_GUID
            )
 --PRINT'Declare Variables: ' + CAST(DATEDIFF(s, @ms, GETDATE()) as varchar)
 --SET @ms = GETDATE()
    /*
    Populate Temporary Tables for each match criteria (Email, PartialName, PhoneNumber, Address)
    */
    -- Find Duplicates by looking at people with the exact same email address
    CREATE TABLE #PersonDuplicateByEmailTable (
         Email NVARCHAR(75) NOT NULL
        ,PersonAliasId INT NOT NULL
        ,PRIMARY KEY CLUSTERED (Email, PersonAliasId)
        );
    INSERT INTO #PersonDuplicateByEmailTable (
        Email
        ,PersonAliasId
        )
    SELECT [e].[Email] [Email]
        ,[pa].[Id] [PersonAliasId]
    FROM (
        SELECT [a].[Email]
        FROM (
            SELECT [Email]
                ,COUNT(*) [EmailCount]
            FROM [Person] [p]
            WHERE isnull([Email], '') != ''
            GROUP BY [Email]
            ) [a]
        WHERE [a].[EmailCount] > 1
        ) [e]
    JOIN [Person] [p] ON [p].[Email] = [e].[Email]
    JOIN [PersonAlias] [pa] ON [pa].[PersonId] = [p].[Id]
    WHERE [pa].[AliasPersonId] = [pa].[PersonId] -- limit to only the primary alias
        AND @compareByEmail = 1
 --PRINT'Create Email Dups: ' + CAST(DATEDIFF(s, @ms, GETDATE()) as varchar)
 --SET @ms = GETDATE()
    -- Find Duplicates by looking at people with the exact same lastname and same first 2 chars of First/Nick name
    CREATE TABLE #PersonDuplicateByNameTable (
         First2 NVARCHAR(50) NOT NULL -- intentionally 50 vs 2 for performance reasons (sql server spends time on the length constraint if it's shorter than the source column)
        ,LastName NVARCHAR(50) NOT NULL
        ,PersonAliasId INT NOT NULL
        ,PRIMARY KEY CLUSTERED (First2, LastName, PersonAliasId)
        );
    INSERT INTO #PersonDuplicateByNameTable (
         First2
        ,LastName
        ,PersonAliasId
        )
    SELECT [e].[LastName]
        ,[e].[First2]
        ,[pa].[Id] [PersonAliasId]
    FROM (
        SELECT [a].[First2]
            ,[a].[LastName]
        FROM (
            SELECT SUBSTRING([FirstName], 1, 2) [First2]
                ,[LastName]
                ,COUNT(*) [MatchCount]
            FROM [Person] [p]
            WHERE isnull([LastName], '') != ''
                AND [FirstName] IS NOT NULL
                AND LEN([FirstName]) >= 2
            GROUP BY [LastName]
                ,SUBSTRING([FirstName], 1, 2)
            ) [a]
        WHERE [a].[MatchCount] > 1
        ) [e]
    JOIN [Person] [p] ON [p].[LastName] = [e].[LastName]
        AND [p].[FirstName] LIKE (e.First2 + '%')
    JOIN [PersonAlias] [pa] ON [pa].[PersonId] = [p].[Id]
    WHERE [pa].[AliasPersonId] = [pa].[PersonId] -- limit to only the primary alias
        AND @compareByPartialName = 1
 --PRINT'Create Name Dups: ' + CAST(DATEDIFF(s, @ms, GETDATE()) as varchar)
 --SET @ms = GETDATE()
    -- Find Duplicates by looking at people with the exact same phone number
    CREATE TABLE #PersonDuplicateByPhoneTable (
         Number NVARCHAR(20) NOT NULL
        ,Extension NVARCHAR(20) NOT NULL
        ,CountryCode NVARCHAR(3) NOT NULL
        ,NumberTypeValueId INT NOT NULL
  ,GroupId INT NOT NULL
        ,PersonAliasId INT NOT NULL
        ,PRIMARY KEY CLUSTERED (Number, Extension, CountryCode, NumberTypeValueId, GroupId, PersonAliasId)
        );
    INSERT INTO #PersonDuplicateByPhoneTable (
        Number
        ,Extension
        ,CountryCode
        ,NumberTypeValueId
  ,GroupId
        ,PersonAliasId
        )
    SELECT DISTINCT [m].[Number]
        ,isnull([m].[Extension], '')
        ,isnull([m].[CountryCode], '')
        ,[m].[NumberTypeValueId]
  ,[g].[Id]
        ,[pa].[Id] [PersonAliasId]
    FROM (
        SELECT DISTINCT [Number]
            ,[Extension]
            ,[CountryCode]
            ,[NumberTypeValueId]
        FROM (
            SELECT [pn].[Number]
                ,[pn].[Extension]
                ,[pn].[CountryCode]
                ,[pn].[NumberTypeValueId]
                ,COUNT(*) [MatchCount]
            FROM [PhoneNumber] [pn]
            JOIN [Person] [p] ON [p].[Id] = [pn].[PersonId]
            WHERE ISNUMERIC([pn].[Number]) = 1
                AND [pn].[NumberTypeValueId] IN (
                    @cHOME_PHONENUMBER_DEFINEDVALUE_ID
                    ,@cCELL_PHONENUMBER_DEFINEDVALUE_ID
                    )
            GROUP BY [pn].[Number]
                ,[pn].[Extension]
                ,[pn].[CountryCode]
                ,[pn].[NumberTypeValueId]
                ,[p].[Gender]
            ) [a]
        WHERE [a].[MatchCount] > 1
        ) [m]
    JOIN [PhoneNumber] [pn] ON [pn].[Number] = [m].[Number]
        AND ISNULL([pn].[Extension], '') = ISNULL([m].[Extension], '')
        AND ISNULL([pn].[CountryCode], '') = ISNULL([m].[CountryCode], '')
        AND [pn].[NumberTypeValueId] = [m].[NumberTypeValueId]
    JOIN [PersonAlias] [pa] ON [pa].[PersonId] = [pn].[PersonId]
    JOIN [GroupMember] [gm] ON [gm].[PersonId] = [pa].[PersonId]
    JOIN [Group] [g] ON [gm].[GroupId] = [g].[Id]
    WHERE [pa].[AliasPersonId] = [pa].[PersonId] -- limit to only the primary alias
  AND [g].[GroupTypeId] = @cGROUPTYPE_FAMILY_ID
        AND @compareByPhone = 1
 --PRINT'Create Phone Dups: ' + CAST(DATEDIFF(s, @ms, GETDATE()) as varchar)
 --SET @ms = GETDATE()
    -- Find Duplicates by looking at people with the exact same address (Location)
    CREATE TABLE #PersonDuplicateByAddressTable (
         LocationId INT NOT NULL
        ,GroupRoleId INT NOT NULL
  ,GroupId INT NOT NULL
        ,PersonAliasId INT NOT NULL
        ,PRIMARY KEY CLUSTERED (LocationId, GroupRoleId, GroupId, PersonAliasId)
        );
    INSERT INTO #PersonDuplicateByAddressTable (
        LocationId
        ,GroupRoleId
  ,GroupId
        ,PersonAliasId
        )
    -- from the locations that have multiple potential duplicate persons, select the person records (along with gender and family role) that are associated with that location
    -- in case the person has multiple home addresses, get the first one with preference given to MapLocation=true
    SELECT CASE 
            WHEN a.MaxMappedLocationId > 0
                THEN a.MaxMappedLocationId
            ELSE a.MaxNotMappedLocationId
            END [LocationId]
        ,[GroupRoleId]
        ,[GroupId]
        ,[PersonAliasId]
    FROM (
        SELECT max(CASE 
                    WHEN [IsMappedLocation] = 1
                        THEN [LocationId]
                    ELSE 0
                    END) [MaxMappedLocationId]
            ,max(CASE 
                    WHEN [IsMappedLocation] = 0
                        THEN [LocationId]
                    ELSE 0
                    END) [MaxNotMappedLocationId]
            ,[GroupRoleId]
   ,[GroupId]
            ,[PersonAliasId]
        FROM (
            SELECT [m].[LocationId]
                ,[gl].[IsMappedLocation]
                ,[m].[GroupRoleId]
    ,[g].[id] [GroupId]
                ,[pa].[Id] [PersonAliasId]
            FROM (
                SELECT [LocationId]
                    ,[GroupRoleId]
                    ,[MatchCount]
                FROM (
                    -- consider it a potential duplicate person if multiple people have the same address (LocationId), Gender and GroupRole (adult, child)
                    SELECT [gl].[LocationId]
                        ,[gm].[GroupRoleId]
                        ,COUNT(*) [MatchCount]
                    FROM [GroupMember] [gm] 
                    JOIN [Group] [g] ON [gm].[GroupId] = [g].[Id]
                    JOIN [GroupLocation] [gl] ON [gl].[GroupId] = [g].[id]
                    JOIN [Location] [l] ON [l].[Id] = [gl].[LocationId]
					WHERE [g].[GroupTypeId] = @cGROUPTYPE_FAMILY_ID
						AND [gl].[GroupLocationTypeValueId] = @cLOCATION_TYPE_HOME_ID
                    GROUP BY [gl].[LocationID]
                        ,[gm].[GroupRoleId]
                    ) [a]
                WHERE [MatchCount] > 1
                ) [m]
            JOIN [GroupLocation] [gl] ON [gl].[LocationId] = [m].[LocationId]
            JOIN [Group] [g] ON [g].[Id] = [gl].[GroupId]
            JOIN [GroupMember] [gm] ON [gm].[GroupId] = [g].[Id]
            JOIN [PersonAlias] [pa] ON [gm].[PersonId] = [pa].[PersonId]
            JOIN [Person] [p] ON [p].[Id] = [pa].[PersonId]
            WHERE [m].[GroupRoleId] = [gm].[GroupRoleId] -- only consider it a potential duplicate person if the gender,role and location are the same (to reduce false matches due to married couples)
                AND [pa].[AliasPersonId] = [pa].[PersonId] -- limit to only the primary alias
				AND [gl].[GroupLocationTypeValueId] = @cLOCATION_TYPE_HOME_ID
                AND @compareByAddress = 1
            ) [a]
        GROUP BY [PersonAliasId]
            ,[GroupRoleId]
   ,[GroupId]
        ) a
 --PRINT'Create Address Dups: ' + CAST(DATEDIFF(s, @ms, GETDATE()) as varchar)
 --SET @ms = GETDATE()
    -- get the original ConfidenceScore of the IgnoreUntilScoreChanges records so that we can un-ignore the ones that have a changed score
    DECLARE @IgnoreUntilScoreChangesTable TABLE (
        Id INT
        ,ConfidenceScore FLOAT
        );
    INSERT INTO @IgnoreUntilScoreChangesTable
    SELECT [Id]
        ,[ConfidenceScore]
    FROM [PersonDuplicate]
    WHERE [IgnoreUntilScoreChanges] = 1;
 --PRINT'Create Ignore Score Changes: ' + CAST(DATEDIFF(s, @ms, GETDATE()) as varchar)
 --SET @ms = GETDATE()
    /* 
    Reset Scores for everybody. (We want to preserve each record's [IsConfirmedAsNotDuplicate] value)
    */
    UPDATE [PersonDuplicate]
    SET [Score] = 0
        ,[ScoreDetail] = '';
 --PRINT'Reset Scores: ' + CAST(DATEDIFF(s, @ms, GETDATE()) as varchar)
 --SET @ms = GETDATE()
    /*
    Merge Results of Matches into PersonDuplicate Table
    */
    -- Update PersonDuplicate table with results of email match
    MERGE [PersonDuplicate] AS TARGET
    USING (
        SELECT [e1].[PersonAliasId] [PersonAliasId]
            ,[e2].[PersonAliasId] [DuplicatePersonAliasId]
            ,max([e1].[Email]) [Email]
        FROM #PersonDuplicateByEmailTable [e1]
        JOIN #PersonDuplicateByEmailTable [e2] ON [e1].[email] = [e2].[email]
            AND [e1].[PersonAliasId] > [e2].[PersonAliasId] -- we only need the matched pair in there once (don't need both PersonA == PersonB and PersonB == PersonA)
        GROUP BY e1.PersonAliasId
            ,e2.PersonAliasId
        ) AS source(PersonAliasId, DuplicatePersonAliasId, Email)
        ON (target.PersonAliasId = source.PersonAliasId)
            AND (target.DuplicatePersonAliasId = source.DuplicatePersonAliasId)
    WHEN MATCHED
        THEN
            UPDATE
            SET [Score] = [Score] + @cScoreWeightEmail
                ,[ScoreDetail] += '|Email'
                ,[ModifiedDateTime] = @processDateTime
    WHEN NOT MATCHED
        THEN
            INSERT (
                PersonAliasId
                ,DuplicatePersonAliasId
                ,Score
                ,ScoreDetail
                ,IsConfirmedAsNotDuplicate
                ,ModifiedDateTime
                ,CreatedDateTime
                ,[Guid]
                )
            VALUES (
                source.PersonAliasId
                ,source.DuplicatePersonAliasId
                ,@cScoreWeightEmail
                ,'|Email'
                ,0
                ,@processDateTime
                ,@processDateTime
                ,NEWID()
                );
 --PRINT'Merge Email Matches: ' + CAST(DATEDIFF(s, @ms, GETDATE()) as varchar)
 --SET @ms = GETDATE()
    -- Update PersonDuplicate table with results of partial name match
 UPDATE [PD] SET 
   [Score] = [Score] + @cScoreWeightPartialName
        ,[ScoreDetail] += '|PartialName'
        ,[ModifiedDateTime] = @processDateTime
 FROM (
        SELECT [e1].[PersonAliasId] [PersonAliasId]
            ,[e2].[PersonAliasId] [DuplicatePersonAliasId]
            ,max([e1].[First2]) [First2]
            ,max([e1].[LastName]) [LastName]
        FROM #PersonDuplicateByNameTable [e1]
        JOIN #PersonDuplicateByNameTable [e2] ON [e1].[First2] = [e2].[First2]
            AND [e1].[LastName] = [e2].[LastName]
            AND [e1].[PersonAliasId] > [e2].[PersonAliasId] -- we only need the matched pair in there once (don't need both PersonA == PersonB and PersonB == PersonA)
        GROUP BY e1.PersonAliasId
            ,e2.PersonAliasId
        ) [NameDup]
 INNER JOIN [PersonDuplicate] [pd]
     ON ([pd].PersonAliasId = [NameDup].PersonAliasId)
        AND ([pd].DuplicatePersonAliasId = [NameDup].DuplicatePersonAliasId)
    INSERT INTO [PersonDuplicate] (
        PersonAliasId
        ,DuplicatePersonAliasId
        ,Score
        ,ScoreDetail
        ,IsConfirmedAsNotDuplicate
        ,ModifiedDateTime
        ,CreatedDateTime
        ,[Guid]
        )
    SELECT 
        [NameDup].PersonAliasId
        ,[NameDup].DuplicatePersonAliasId
        ,@cScoreWeightPartialName
        ,'|PartialName'
        ,0
        ,@processDateTime
        ,@processDateTime
        ,NEWID()
 FROM (
        SELECT [e1].[PersonAliasId] [PersonAliasId]
            ,[e2].[PersonAliasId] [DuplicatePersonAliasId]
            ,max([e1].[First2]) [First2]
            ,max([e1].[LastName]) [LastName]
        FROM #PersonDuplicateByNameTable [e1]
        JOIN #PersonDuplicateByNameTable [e2] ON [e1].[First2] = [e2].[First2]
            AND [e1].[LastName] = [e2].[LastName]
            AND [e1].[PersonAliasId] > [e2].[PersonAliasId] -- we only need the matched pair in there once (don't need both PersonA == PersonB and PersonB == PersonA)
        GROUP BY e1.PersonAliasId
            ,e2.PersonAliasId
        ) [NameDup]
 LEFT OUTER JOIN [PersonDuplicate] [pd]
     ON ([pd].PersonAliasId = [NameDup].PersonAliasId)
        AND ([pd].DuplicatePersonAliasId = [NameDup].DuplicatePersonAliasId)
 WHERE [pd].[id] IS NULL
 --PRINT'Merge Name Matches: ' + CAST(DATEDIFF(s, @ms, GETDATE()) as varchar)
 --SET @ms = GETDATE()
    --  Update PersonDuplicate table with results of phonenumber match for each number type. 
    --  For example, if both the Cell and Home phone match, that should be a higher score 
    DECLARE @PhoneNumberTypeValueId INT
    DECLARE @PhoneNumberTypeScore INT
    DECLARE @PhoneNumberTypeText VARCHAR(50)
    DECLARE phoneNumberTypeCursor CURSOR FAST_FORWARD
    FOR
    SELECT [Id]
    FROM [DefinedValue]
    WHERE [Id] IN (
            @cHOME_PHONENUMBER_DEFINEDVALUE_ID
            ,@cCELL_PHONENUMBER_DEFINEDVALUE_ID
            )
    ORDER BY [Id]
    OPEN phoneNumberTypeCursor
    FETCH NEXT
    FROM phoneNumberTypeCursor
    INTO @PhoneNumberTypeValueId
    -- loop thru each of the phone number types (home, cell)
    WHILE @@FETCH_STATUS = 0
    BEGIN
        IF (@PhoneNumberTypeValueId = @cCELL_PHONENUMBER_DEFINEDVALUE_ID)
        BEGIN
            SET @PhoneNumberTypeScore = @cScoreWeightCellPhoneNumber
            SET @PhoneNumberTypeText = '|CellPhone'
        END
        ELSE
        BEGIN
            SET @PhoneNumberTypeScore = @cScoreWeightNonCellPhoneNumber
            SET @PhoneNumberTypeText = '|Phone'
        END
        MERGE [PersonDuplicate] AS TARGET
        USING (
            SELECT [e1].[PersonAliasId] [PersonAliasId]
                ,[e2].[PersonAliasId] [DuplicatePersonAliasId]
                ,max([e1].[Number])
                ,max([e1].[Extension])
                ,max([e1].[CountryCode])
                ,max([e1].[NumberTypeValueId])
            FROM #PersonDuplicateByPhoneTable [e1]
            JOIN #PersonDuplicateByPhoneTable [e2] ON [e1].[Number] = [e2].[Number]
                AND [e1].[Extension] = [e2].[Extension]
                AND [e1].[CountryCode] = [e2].[CountryCode]
                AND [e1].[NumberTypeValueId] = [e2].[NumberTypeValueId]
    AND [e1].[GroupId] <> [e2].[GroupId] -- Ignore people with duplicate phone number in same family
                AND [e1].[PersonAliasId] > [e2].[PersonAliasId] -- we only need the matched pair in there once (don't need both PersonA == PersonB and PersonB == PersonA)
            WHERE [e1].[NumberTypeValueId] = @PhoneNumberTypeValueId
            GROUP BY e1.PersonAliasId
                ,e2.PersonAliasId
            ) AS source(PersonAliasId, DuplicatePersonAliasId, Number, Extension, CountryCode, NumberTypeValueId)
            ON (target.PersonAliasId = source.PersonAliasId)
                AND (target.DuplicatePersonAliasId = source.DuplicatePersonAliasId)
        WHEN MATCHED
            THEN
                UPDATE
                SET [Score] = [Score] + @PhoneNumberTypeScore
                    ,[ScoreDetail] += @PhoneNumberTypeText
                    ,[ModifiedDateTime] = @processDateTime
        WHEN NOT MATCHED
            THEN
                INSERT (
                    PersonAliasId
                    ,DuplicatePersonAliasId
                    ,Score
                    ,ScoreDetail
                    ,IsConfirmedAsNotDuplicate
                    ,ModifiedDateTime
                    ,CreatedDateTime
                    ,[Guid]
                    )
                VALUES (
                    source.PersonAliasId
                    ,source.DuplicatePersonAliasId
                    ,@PhoneNumberTypeScore
                    ,@PhoneNumberTypeText
                    ,0
                    ,@processDateTime
                    ,@processDateTime
                    ,NEWID()
                    );
        FETCH NEXT
        FROM phoneNumberTypeCursor
        INTO @PhoneNumberTypeValueId
    END
    CLOSE phoneNumberTypeCursor
    DEALLOCATE phoneNumberTypeCursor
 --PRINT'Merge Phone Matches: ' + CAST(DATEDIFF(s, @ms, GETDATE()) as varchar)
 --SET @ms = GETDATE()
    -- Update PersonDuplicate table with results of address (location) match
    MERGE [PersonDuplicate] AS TARGET
    USING (
        SELECT [e1].[PersonAliasId] [PersonAliasId]
            ,[e2].[PersonAliasId] [DuplicatePersonAliasId]
            ,max([e1].[LocationId])
            ,max([e1].[GroupRoleId])
        FROM #PersonDuplicateByAddressTable [e1]
        JOIN #PersonDuplicateByAddressTable [e2] ON [e1].[LocationId] = [e2].[LocationId]
            AND [e1].[GroupRoleId] = [e2].[GroupRoleId]
            AND [e1].[GroupId] <> [e2].[GroupId] -- Ignore people in same family
            AND [e1].[PersonAliasId] > [e2].[PersonAliasId] -- we only need the matched pair in there once (don't need both PersonA == PersonB and PersonB == PersonA)
        GROUP BY e1.PersonAliasId
            ,e2.PersonAliasId
        ) AS source(PersonAliasId, DuplicatePersonAliasId, LocationId, GroupRoleId)
        ON (target.PersonAliasId = source.PersonAliasId)
            AND (target.DuplicatePersonAliasId = source.DuplicatePersonAliasId)
    WHEN MATCHED
        THEN
            UPDATE
            SET [Score] = [Score] + @cScoreWeightAddress
                ,[ScoreDetail] += '|Address'
                ,[ModifiedDateTime] = @processDateTime
    WHEN NOT MATCHED
        THEN
            INSERT (
                PersonAliasId
                ,DuplicatePersonAliasId
                ,Score
                ,ScoreDetail
                ,IsConfirmedAsNotDuplicate
                ,ModifiedDateTime
                ,CreatedDateTime
                ,[Guid]
                )
            VALUES (
                source.PersonAliasId
                ,source.DuplicatePersonAliasId
                ,@cScoreWeightAddress
                ,'|Address'
                ,0
                ,@processDateTime
                ,@processDateTime
                ,NEWID()
                );
 --PRINT'Merge Address Matches: ' + CAST(DATEDIFF(s, @ms, GETDATE()) as varchar)
 --SET @ms = GETDATE()
    /* Calculate Capacities before we do the additional scores
    */
    -- set base capacity to include MaritalStatus and Gender, since everybody has values for those
    UPDATE [PersonDuplicate]
    SET [Capacity] = CASE 
            WHEN @compareByGender = 1
                THEN @cScoreWeightGender
            ELSE 0
            END + CASE 
            WHEN @compareByMaritalStatus = 1
                THEN @cScoreWeightMaritalStatus
            ELSE 0
            END;
 --PRINT'Update Base Capacity: ' + CAST(DATEDIFF(s, @ms, GETDATE()) as varchar)
 --SET @ms = GETDATE()
    -- increment capacity values for Email, PartialName, Birthdate (do in one Update statement since these are all person fields)
    UPDATE [PersonDuplicate]
    SET [Capacity] += CASE 
            -- add the Email capacity
            WHEN @compareByEmail = 1
                AND isnull(p.Email, '') != ''
                THEN @cScoreWeightEmail
            ELSE 0
            END + CASE 
            -- add partial name capacity
            WHEN @compareByPartialName = 1
                AND (
                    isnull(p.LastName, '') != ''
                    OR isnull(p.FirstName, '') != ''
                    )
                THEN @cScoreWeightPartialName
            ELSE 0
            END + CASE 
            -- full first name capacity
            WHEN @compareByFullFirstName = 1
                AND (
                    isnull(p.FirstName, '') != ''
                    OR isnull(p.NickName, '') != ''
                    )
                THEN @cScoreWeightFullFirstName
            ELSE 0
            END + CASE 
            -- full last name capacity
            WHEN @compareByFullLastName = 1
                AND isnull(p.LastName, '') != ''
                THEN @cScoreWeightFullFirstName
            ELSE 0
            END + CASE 
            -- add the Birthday Capacity
            WHEN @compareByBirthDate = 1
                AND p.BirthDate IS NOT NULL
                THEN @cScoreWeightBirthdate
            ELSE 0
            END + CASE
   -- add the Suffix Capacity
   WHEN @compareBySuffix = 1
    AND p.SuffixValueId IS NOT NULL
    THEN @cScoreWeightSuffix
   ELSE 0
   END
    FROM PersonDuplicate pd
    JOIN PersonAlias pa ON pa.Id = pd.PersonAliasId
    JOIN Person p ON p.Id = pa.PersonId
 --PRINT'Increment Capacity for Email, Name, Birthdate: ' + CAST(DATEDIFF(s, @ms, GETDATE()) as varchar)
 --SET @ms = GETDATE()
    ---- NOTE Phone Capacity is higher if BOTH Home and Cell Phone are available
    -- increment capacity values for Home Phone
    UPDATE [PersonDuplicate]
    SET [Capacity] += @cScoreWeightNonCellPhoneNumber
    FROM PersonDuplicate pd
    JOIN PersonAlias pa ON pa.Id = pd.PersonAliasId
    JOIN Person p ON p.Id = pa.PersonId
    WHERE p.Id IN (
            SELECT PersonId
            FROM PhoneNumber
            WHERE NumberTypeValueId = @cHOME_PHONENUMBER_DEFINEDVALUE_ID
            )
        AND @compareByPhone = 1
 --PRINT'Increment Capacity for Home Phone: ' + CAST(DATEDIFF(s, @ms, GETDATE()) as varchar)
 --SET @ms = GETDATE()
    -- increment capacity values for Cell Phone
    UPDATE [PersonDuplicate]
    SET [Capacity] += @cScoreWeightCellPhoneNumber
    FROM PersonDuplicate pd
    JOIN PersonAlias pa ON pa.Id = pd.PersonAliasId
    JOIN Person p ON p.Id = pa.PersonId
    WHERE p.Id IN (
            SELECT PersonId
            FROM PhoneNumber
            WHERE NumberTypeValueId = @cCELL_PHONENUMBER_DEFINEDVALUE_ID
            )
        AND @compareByPhone = 1
 --PRINT'Increment Capacity for Cell Phone: ' + CAST(DATEDIFF(s, @ms, GETDATE()) as varchar)
 --SET @ms = GETDATE()
    -- increment capacity values for Address
    UPDATE [PersonDuplicate]
    SET [Capacity] += @cScoreWeightAddress
    FROM PersonDuplicate pd
    JOIN PersonAlias pa ON pa.Id = pd.PersonAliasId
    JOIN Person p ON p.Id = pa.PersonId
    WHERE p.Id IN (
            SELECT PersonId
            FROM [GroupMember] [gm]
            JOIN [Group] [g] ON [gm].[GroupId] = [g].[Id]
            JOIN [GroupLocation] [gl] ON [gl].[GroupId] = [g].[id]
            JOIN [Location] [l] ON [l].[Id] = [gl].[LocationId]
                AND [g].[GroupTypeId] = @cGROUPTYPE_FAMILY_ID
            WHERE [gl].[GroupLocationTypeValueId] = @cLOCATION_TYPE_HOME_ID
            )
        AND @compareByAddress = 1
 --PRINT'Increment Capacity for Address: ' + CAST(DATEDIFF(s, @ms, GETDATE()) as varchar)
 --SET @ms = GETDATE()
    -- increment capacity values for Campus
    UPDATE [PersonDuplicate]
    SET [Capacity] += @cScoreWeightCampus
    FROM PersonDuplicate pd
    JOIN PersonAlias pa ON pa.Id = pd.PersonAliasId
    JOIN Person p ON p.Id = pa.PersonId
    WHERE p.Id IN (
            SELECT PersonId
            FROM [GroupMember] [gm]
            JOIN [Group] [g] ON [gm].[GroupId] = [g].[Id]
            WHERE [g].[GroupTypeId] = @cGROUPTYPE_FAMILY_ID
                AND g.CampusId IS NOT NULL
            )
        AND @compareByCampus = 1
 --PRINT'Increment Capacity for Campus: ' + CAST(DATEDIFF(s, @ms, GETDATE()) as varchar)
 --SET @ms = GETDATE()
    /*
    Add additional scores to people that are already potential matches 
    */
    -- Increment the score on potential matches that have the same FirstName (or NickName)
    UPDATE pd
    SET [Score] = [Score] + @cScoreWeightFullFirstName
        ,[ScoreDetail] += '|FirstName'
    FROM PersonDuplicate pd
    JOIN PersonAlias pa1 ON pa1.Id = pd.PersonAliasId
    JOIN PersonAlias pa2 ON pa2.Id = pd.DuplicatePersonAliasId
    JOIN Person p1 ON p1.Id = pa1.PersonId
    JOIN Person p2 ON p2.Id = pa2.PersonId
    WHERE (
            (
                p1.FirstName = p2.FirstName
                AND isnull(p1.FirstName, '') != ''
                )
            OR (
                p1.NickName = p2.NickName
                AND isnull(p1.NickName, '') != ''
                )
            OR (
                p1.FirstName = p2.NickName
                AND isnull(p1.NickName, '') != ''
                AND isnull(p1.FirstName, '') != ''
                )
            OR (
                p1.NickName = p2.FirstName
                AND isnull(p1.NickName, '') != ''
                AND isnull(p1.FirstName, '') != ''
                )
            )
        AND @compareByFullFirstName = 1
 --PRINT'Update score for first name matches: ' + CAST(DATEDIFF(s, @ms, GETDATE()) as varchar)
 --SET @ms = GETDATE()
    -- Increment the score on potential matches that have the same LastName
    UPDATE pd
    SET [Score] = [Score] + @cScoreWeightFullFirstName
        ,[ScoreDetail] += '|LastName'
    FROM PersonDuplicate pd
    JOIN PersonAlias pa1 ON pa1.Id = pd.PersonAliasId
    JOIN PersonAlias pa2 ON pa2.Id = pd.DuplicatePersonAliasId
    JOIN Person p1 ON p1.Id = pa1.PersonId
    JOIN Person p2 ON p2.Id = pa2.PersonId
    WHERE p1.LastName = p2.LastName
        AND isnull(p1.LastName, '') != ''
        AND @compareByFullLastName = 1
 --PRINT'Update score for last name matches: ' + CAST(DATEDIFF(s, @ms, GETDATE()) as varchar)
 --SET @ms = GETDATE()
    -- Increment the score on potential matches that have the same birthday
    UPDATE pd
    SET [Score] = [Score] + @cScoreWeightBirthdate
        ,[ScoreDetail] += '|Birthdate'
    FROM PersonDuplicate pd
    INNER JOIN PersonAlias pa1 ON pa1.Id = pd.PersonAliasId
    INNER JOIN PersonAlias pa2 ON pa2.Id = pd.DuplicatePersonAliasId
    INNER JOIN Person p1 ON p1.Id = pa1.PersonId
    INNER JOIN Person p2 ON p2.Id = pa2.PersonId
    WHERE p1.BirthDate = p2.BirthDate
        AND @compareByBirthDate = 1
 --PRINT'Update score for birthday matches: ' + CAST(DATEDIFF(s, @ms, GETDATE()) as varchar)
 --SET @ms = GETDATE()
    -- Increment the score on potential matches that have the same gender
    UPDATE pd
    SET [Score] = [Score] + @cScoreWeightGender
        ,[ScoreDetail] += '|Gender'
    FROM PersonDuplicate pd
    JOIN PersonAlias pa1 ON pa1.Id = pd.PersonAliasId
    JOIN PersonAlias pa2 ON pa2.Id = pd.DuplicatePersonAliasId
    JOIN Person p1 ON p1.Id = pa1.PersonId
    JOIN Person p2 ON p2.Id = pa2.PersonId
    WHERE p1.Gender = p2.Gender
        AND @compareByGender = 1
 --PRINT'Update score for gender matches: ' + CAST(DATEDIFF(s, @ms, GETDATE()) as varchar)
 --SET @ms = GETDATE()
    -- Increment the score on potential matches that have the same campus
    UPDATE pd
    SET [Score] = [Score] + @cScoreWeightCampus
        ,[ScoreDetail] += '|Campus'
    FROM PersonDuplicate pd
    JOIN PersonAlias pa1 ON pa1.Id = pd.PersonAliasId
    JOIN PersonAlias pa2 ON pa2.Id = pd.DuplicatePersonAliasId
    JOIN Person p1 ON p1.Id = pa1.PersonId
    JOIN Person p2 ON p2.Id = pa2.PersonId
    JOIN [GroupMember] [gm1] ON [gm1].[PersonId] = [p1].[Id]
    JOIN [Group] [g1] ON [gm1].[GroupId] = [g1].[Id]
    JOIN [GroupMember] [gm2] ON [gm2].[PersonId] = [p2].[Id]
    JOIN [Group] [g2] ON [gm2].[GroupId] = [g2].[Id]
    WHERE g1.CampusId = g2.CampusId
        AND g1.CampusId IS NOT NULL
        AND g2.CampusId IS NOT NULL
        AND [g1].[GroupTypeId] = @cGROUPTYPE_FAMILY_ID
        AND [g2].[GroupTypeId] = @cGROUPTYPE_FAMILY_ID
        AND @compareByCampus = 1
 --PRINT'Update score for campus matches: ' + CAST(DATEDIFF(s, @ms, GETDATE()) as varchar)
 --SET @ms = GETDATE()
    -- Increment the score on potential matches that have the same marital status
    UPDATE pd
    SET [Score] = [Score] + @cScoreWeightMaritalStatus
        ,[ScoreDetail] += '|Marital'
    FROM PersonDuplicate pd
    JOIN PersonAlias pa1 ON pa1.Id = pd.PersonAliasId
    JOIN PersonAlias pa2 ON pa2.Id = pd.DuplicatePersonAliasId
    JOIN Person p1 ON p1.Id = pa1.PersonId
    JOIN Person p2 ON p2.Id = pa2.PersonId
    WHERE p1.MaritalStatusValueId = p2.MaritalStatusValueId
        AND @compareByMaritalStatus = 1
 --PRINT'Update score for marital status matches: ' + CAST(DATEDIFF(s, @ms, GETDATE()) as varchar)
 --SET @ms = GETDATE()
    -- Increment the score on potential matches that have the same suffix
    UPDATE pd
    SET [Score] = [Score] + @cScoreWeightSuffix
        ,[ScoreDetail] += '|Suffix'
    FROM PersonDuplicate pd
    INNER JOIN PersonAlias pa1 ON pa1.Id = pd.PersonAliasId
    INNER JOIN PersonAlias pa2 ON pa2.Id = pd.DuplicatePersonAliasId
    INNER JOIN Person p1 ON p1.Id = pa1.PersonId
    INNER JOIN Person p2 ON p2.Id = pa2.PersonId
    WHERE p1.SuffixValueId = p2.SuffixValueId
        AND @compareBySuffix = 1
 --PRINT'Update score for suffix matches: ' + CAST(DATEDIFF(s, @ms, GETDATE()) as varchar)
 --SET @ms = GETDATE()
    /* 
    Clean up records that no longer are duplicates 
    */
    DECLARE @staleCount INT;
    SELECT @staleCount = count(*)
    FROM [PersonDuplicate]
    WHERE [ModifiedDateTime] < @processDateTime
    IF (@staleCount != 0)
    BEGIN
        DELETE
        FROM [PersonDuplicate]
        WHERE [ModifiedDateTime] < @processDateTime
    END
 --PRINT'Remove stale matches: ' + CAST(DATEDIFF(s, @ms, GETDATE()) as varchar)
 --SET @ms = GETDATE()
    UPDATE [PersonDuplicate]
    SET [TotalCapacity] = @TotalCapacity
 --PRINT'Set Total Capacity: ' + CAST(DATEDIFF(s, @ms, GETDATE()) as varchar)
 --SET @ms = GETDATE()
 UPDATE [PersonDuplicate]
 SET [ConfidenceScore] = sqrt (
  ( CASE WHEN [TotalCapacity] > 0 
   THEN [Capacity] / ( [TotalCapacity] * 0.01 ) 
   ELSE 0 END )
  *
  ( CASE WHEN [Capacity] > 0 
   THEN [Score] / ( [Capacity] * 0.01 ) 
   ELSE 0 END )
 )
    UPDATE [PersonDuplicate]
    SET IgnoreUntilScoreChanges = 0
    FROM [PersonDuplicate] [pd]
    JOIN @IgnoreUntilScoreChangesTable [g] ON pd.Id = g.id
    WHERE pd.ConfidenceScore != g.ConfidenceScore;
 --PRINT'Set Ignore changes: ' + CAST(DATEDIFF(s, @ms, GETDATE()) as varchar)
 --SET @ms = GETDATE()
    /*
    Explicitly clean up temp tables before the proc exits (vs. have SQL Server do it for us after the proc is done)
    */
    DROP TABLE #PersonDuplicateByEmailTable;
    DROP TABLE #PersonDuplicateByNameTable;
    DROP TABLE #PersonDuplicateByPhoneTable;
    DROP TABLE #PersonDuplicateByAddressTable;
 --PRINT'Drop temp tables: ' + CAST(DATEDIFF(s, @ms, GETDATE()) as varchar)
 --SET @ms = GETDATE()
END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*
<doc>
	<summary>
 		This procedure merges relationship data for two people being merged.  It is called from the
		from the [dbo].[spCrm_PersonMerge] procedure to merge Known Relationships and Implied
		Relationships.  It is used when merging people in Rock and should never be used outside 
		of that process. 
	</summary>

	<returns></returns>
	<param name="Old Id" datatype="int">The person id of the non-primary Person being merged</param>
	<param name="New Id" datatype="int">The person id of the rimary Person being merged</param>
	<param name="Owner Role Guid" datatype="uniqueidentifier">The role of the owner in the relationship group</param>
	<remarks>	
	</remarks>
	<code>
		EXEC [dbo].[spCrm_PersonMergeRelationships] @OldId, @NewId, '7BC6C12E-0CD1-4DFD-8D5B-1B35AE714C42' -- Known Relationships
		EXEC [dbo].[spCrm_PersonMergeRelationships] @OldId, @NewId, 'CB9A0E14-6FCF-4C07-A49A-D7873F45E196' -- Implied Relationships
	</code>
</doc>
*/

CREATE PROCEDURE [dbo].[spCrm_PersonMergeRelationships]
	@OldId int
	, @NewId int
	, @OwnerRoleGuid uniqueidentifier

AS
BEGIN

	DECLARE @GroupTypeId int
	DECLARE @GroupRoleId int

	DECLARE @NewMemberId int
	DECLARE @NewGroupId int

	DECLARE @OldMemberId int
	DECLARE @OldGroupId int
	
	-- Find the old person's owner group member record
	SELECT TOP 1
		@OldMemberId = GM.[Id],
		@OldGroupId = GM.[GroupId],
		@GroupTypeId = GTR.[GroupTypeId],
		@GroupRoleId = GTR.[Id]
	FROM [GroupMember] GM
		INNER JOIN [GroupTypeRole] GTR ON GTR.[Id] = GM.GroupRoleId AND GTR.[Guid] = @OwnerRoleGuid
	WHERE GM.[PersonId] = @OldId
		
	IF @GroupTypeId IS NOT NULL
	BEGIN

		-- Find the new person's owner group member record
		SELECT TOP 1
			@NewMemberId = GM.[Id],
			@NewGroupId = GM.[GroupId]
		FROM [GroupMember] GM
			INNER JOIN [GroupTypeRole] GTR ON GTR.[Id] = GM.GroupRoleId AND GTR.[Guid] = @OwnerRoleGuid
		WHERE GM.[PersonId] = @NewId
	
		IF @NewGroupId IS NULL 
		BEGIN

			-- If new person doesn't have a relation group member record, update
			-- the old person to use the new person id (and be done)
			UPDATE [GroupMember]
			SET [PersonId] = @NewId
			WHERE [Id] = @OldMemberID

		END
		ELSE
		BEGIN

			-- Move the relationships from old person's relationship group
			-- to new person's group when new person doesn't already have
			-- same relationship
			UPDATE GMO
				SET [GroupId] = @NewGroupId
			FROM [GroupMember] GMO
				LEFT OUTER JOIN [GroupMember] GMN ON GMN.[GroupId] = @NewGroupId 
					AND GMN.[PersonId] = GMO.[PersonId] AND GMN.[GroupRoleId] = GMO.[GroupRoleId]
			WHERE GMO.[GroupId] = @OldGroupId
				AND GMO.[Id] <> @OldMemberId
				AND GMN.[Id] IS NULL

			-- Delete/Archive the old person's relationship group if it still exists
			DELETE [Group] 
			WHERE [Id] = @OldGroupId
			  AND [Id] NOT IN (SELECT GroupId FROM GroupHistorical)
			  AND [Id] NOT IN (SELECT GroupId FROM GroupMemberHistorical)	

			-- Archive the Group if it didn't end up getting deleted because it had GroupHistory
			UPDATE [Group] SET [IsArchived] = 1 WHERE [Id] = @OldGroupID
		END

	END

END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
