CREATE PROCEDURE dbo.spGivingAutomation_UpdateGivingBinsAndPercentiles
    @CurrentRockDateTime DATETIME,
    @TransactionTypeIds dbo.IdList READONLY,        -- List of allowed TransactionTypeValueIds ( Defined in Giving Automation Configuration Block )
    @FinancialAccountIds dbo.IdList READONLY        -- List of allowed FinancialAccounts ( Defined in Giving Automation Configuration Block )
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @EndDate DATETIME = @CurrentRockDateTime;
    DECLARE @StartDate DATETIME = DATEADD(MONTH, -12, @EndDate);

    DECLARE @AttrId_GivingBin        INT = (SELECT TOP 1 Id FROM Attribute WHERE [Guid] = '7FBB63CC-F4FC-4F7E-A8C5-44DC3D0F0720');
    DECLARE @AttrId_GivingPercentile INT = (SELECT TOP 1 Id FROM Attribute WHERE [Guid] = 'D03ACAB8-EB0C-4835-A04C-4C357014D935');

    DECLARE @RecordTypeId_Nameless INT = (SELECT TOP 1 Id FROM DefinedValue WHERE [Guid] = '721300ED-1267-4DA0-B4F2-6C6B5B17B1C5'); -- PERSON_RECORD_TYPE_NAMELESS
    DECLARE @RecordTypeId_RestUser INT = (SELECT TOP 1 Id FROM DefinedValue WHERE [Guid] = 'E2261A84-831D-4234-9BE0-4D628BBE751E'); -- PERSON_RECORD_TYPE_RESTUSER
    DECLARE @GiverAnonymousGuid UNIQUEIDENTIFIER = '802235DC-3CA5-94B0-4326-AACE71180F48'; -- GIVER_ANONYMOUS

    -- =============================================
    -- CALCULATIONS
    -- =============================================

    ;WITH RefundTotals AS (
        SELECT 
            ftr.OriginalTransactionId,
            SUM(ftd.Amount) AS TotalRefundedAmount
        FROM dbo.FinancialTransactionRefund ftr
        JOIN dbo.FinancialTransactionDetail ftd ON ftd.TransactionId = ftr.Id
        GROUP BY ftr.OriginalTransactionId
    ),

    TwelveMonthTransactions AS (
        SELECT
            p.GivingId,
            ft.Id,
            SUM(ftd.Amount) + ISNULL(rt.TotalRefundedAmount, 0.00) AS NetAmount
        FROM dbo.FinancialTransaction ft
        JOIN dbo.PersonAlias pa ON pa.Id = ft.AuthorizedPersonAliasId
        JOIN dbo.Person p ON p.Id = pa.PersonId
        JOIN dbo.FinancialTransactionDetail ftd ON ftd.TransactionId = ft.Id
        LEFT JOIN RefundTotals rt ON rt.OriginalTransactionId = ft.Id
        WHERE 
            ft.TransactionDateTime >= @StartDate
            AND ft.TransactionDateTime <= @CurrentRockDateTime
            
            -- 1. Transaction type filter
            AND ft.TransactionTypeValueId IN (SELECT Id FROM @TransactionTypeIds)

            /*
               2. Account filter -- include the transaction if it has AT LEAST ONE line item
               in one of the allowed financial accounts.

               NOTE:
               - A FinancialTransaction may have multiple FinancialTransactionDetail rows (line items).
               - Some of those line items may belong to accounts NOT in the allowed list.
               - The transaction is still included as long as ONE line item is in an allowed account.
            */
            AND EXISTS (
                SELECT 1
                FROM dbo.FinancialTransactionDetail ftd_account
                WHERE ftd_account.TransactionId = ft.Id
                  AND ftd_account.AccountId IN (SELECT Id FROM @FinancialAccountIds)
            )

            -- 3. Must have at least one positive detail (across ALL details, not just filtered accounts)
            AND EXISTS (
                SELECT 1
                FROM dbo.FinancialTransactionDetail ftd_pos
                WHERE ftd_pos.TransactionId = ft.Id
                  AND ftd_pos.Amount > 0
            )

            -- 4. Refund logic: exclude only FULLY REFUNDED transactions
            AND (
                -- No refunds at all... include
                NOT EXISTS ( SELECT 1 FROM dbo.FinancialTransactionRefund ftr0 WHERE ftr0.OriginalTransactionId = ft.Id )
                OR
                (
                    -- Sum of ALL original txns details + sum of ALL refund details != 0... not fully refunded.
                    (SELECT SUM(ftd_all.Amount)
                     FROM dbo.FinancialTransactionDetail ftd_all
                     WHERE ftd_all.TransactionId = ft.Id)
                    + ISNULL(rt.TotalRefundedAmount, 0.00) <> 0
                )
            )

            -- NOTE: We intentionally do not apply all the person eligibility filters here.
            -- We include all GivingIds in the percentile distribution, and only apply eligibility filters later when updating AttributeValues.
            AND p.GivingId IS NOT NULL 
            AND p.GivingId <> ''
            AND p.[Guid] <> @GiverAnonymousGuid
        GROUP BY
            p.GivingId,
            ft.Id,
            rt.TotalRefundedAmount
    ),

    GiverTotals AS (
        SELECT 
            GivingId,
            SUM(NetAmount) AS Total12MonthGiving
        FROM TwelveMonthTransactions
        GROUP BY GivingId
    ),

    /*
        1/11/2026 - MSE

        Percentile Calculation

        Previous implementation:
        - Built a PercentileLowerRange[0..99] array of percentile cutoffs from the sorted 12-month giving totals.
        - Assigned a giver's percentile by finding which cutoff their total crossed.
        - This is an approximation (bucketed cutoffs), and not a direct percentile rank computed from the full distribution.

        - MAJOR FLAW: Percentile AttributeValues were updated ONLY for GivingIds with new or modified transactions since the last job run.
          Although the job rebuilt the global 12-month percentile cutoffs using everyone's current 12-month data, it did NOT update stored
          AttributeValues for GivingIds without new gifts. This caused some givers to retain high percentile values even after years of no giving,
          because their AttributeValue never changed unless they gave again.

        Current implementation (this procedure):
        - Recalculates Total12MonthGiving for all GivingIds on each run.
        - Uses a cumulative distribution (CUME_DIST) to compute each giver's percentile directly from the full ordered list of totals.
        - https://learn.microsoft.com/en-us/sql/t-sql/functions/cume-dist-transact-sql?view=sql-server-ver17
          
        - This produces a true percentile rank ("what percent of givers have total giving less than or equal to this giver").
        - Removes stale bin/percentile values for people who no longer have qualifying 12-month giving history.

        Why this is better:
        - Percentiles stay current as the overall giving distribution shifts -- changes to any giver should automatically affect everyone.
        - Stored AttributeValues are updated consistently, rather than only when a giver has new transactions.
    */

    GiverPercentiles AS (
        SELECT
            GivingId,
            Total12MonthGiving,
            CUME_DIST() OVER (ORDER BY Total12MonthGiving) AS Percentile
        FROM GiverTotals
    ),

    GiverBins AS (
        SELECT
            GivingId,
            Total12MonthGiving,
            Percentile,
            CASE
                WHEN Percentile >= 0.95 THEN 1  -- >= 95th percentile
                WHEN Percentile >= 0.80 THEN 2  -- >= 80th percentile
                WHEN Percentile >= 0.60 THEN 3  -- >= 60th percentile
                ELSE 4                          --  < 60th percentile
            END AS Bin
        FROM GiverPercentiles
    )

    SELECT
        p.Id AS PersonId,
        gb.Bin,

        /*
            1/11/2026 - MSE

            - CUME_DIST() returns a decimal in (0,1], so ROUND(Percentile * 100) results in 1-100.
            - We store the percentile as 0-99 by using FLOOR(Percentile * 100), and cap the maximum (Percentile = 1) at 99.
        */
        CASE
            WHEN gb.Percentile >= 1 THEN 99
            ELSE CAST(FLOOR(gb.Percentile * 100) AS INT)
        END AS PercentileValue
    INTO #GivingData
    FROM GiverBins gb
    JOIN dbo.Person p ON p.GivingId = gb.GivingId
    WHERE p.GivingId IS NOT NULL
      AND p.GivingId <> ''
      AND p.RecordTypeValueId IS NOT NULL
      AND ( @RecordTypeId_Nameless IS NULL OR p.RecordTypeValueId <> @RecordTypeId_Nameless )
      AND ( @RecordTypeId_RestUser IS NULL OR p.RecordTypeValueId <> @RecordTypeId_RestUser )
      AND p.[Guid] <> @GiverAnonymousGuid;

    CREATE CLUSTERED INDEX IX_PersonId ON #GivingData (PersonId);

    -- =============================================
    -- MERGE INTO ATTRIBUTE VALUE
    -- =============================================

    -- Giving Bin
    ;WITH CurrentBin AS (
        SELECT 
            av.EntityId AS PersonId,
            CAST(av.Value AS INT) AS CurrentBin
        FROM AttributeValue av
        WHERE av.AttributeId = @AttrId_GivingBin
    )
    MERGE AttributeValue AS target
    USING (
        SELECT gd.PersonId, CAST(gd.Bin AS VARCHAR(10)) AS NewValue
        FROM #GivingData gd
        LEFT JOIN CurrentBin cb ON cb.PersonId = gd.PersonId
        WHERE gd.Bin IS NOT NULL
          AND (cb.CurrentBin IS NULL OR cb.CurrentBin != gd.Bin)
    ) AS source ON (target.AttributeId = @AttrId_GivingBin AND target.EntityId = source.PersonId)
    WHEN MATCHED THEN
        UPDATE SET
            Value = source.NewValue,
            ModifiedDateTime = @CurrentRockDateTime
    WHEN NOT MATCHED BY TARGET THEN
        INSERT (IsSystem, AttributeId, EntityId, Value, Guid, CreatedDateTime, ModifiedDateTime)
        VALUES (0, @AttrId_GivingBin, source.PersonId, source.NewValue, NEWID(), @CurrentRockDateTime, @CurrentRockDateTime);

    -- Giving Percentile
    ;WITH CurrentPercentile AS (
        SELECT 
            av.EntityId AS PersonId,
            CAST(av.Value AS INT) AS CurrentPercentile
        FROM AttributeValue av
        WHERE av.AttributeId = @AttrId_GivingPercentile
    )
    MERGE AttributeValue AS target
    USING (
        SELECT gd.PersonId, CAST(gd.PercentileValue AS VARCHAR(10)) AS NewValue
        FROM #GivingData gd
        LEFT JOIN CurrentPercentile cp ON cp.PersonId = gd.PersonId
        WHERE gd.PercentileValue IS NOT NULL
          AND (cp.CurrentPercentile IS NULL OR cp.CurrentPercentile != gd.PercentileValue)
    ) AS source ON (target.AttributeId = @AttrId_GivingPercentile AND target.EntityId = source.PersonId)
    WHEN MATCHED THEN
        UPDATE SET
            Value = source.NewValue,
            ModifiedDateTime = @CurrentRockDateTime
    WHEN NOT MATCHED BY TARGET THEN
        INSERT (IsSystem, AttributeId, EntityId, Value, Guid, CreatedDateTime, ModifiedDateTime)
        VALUES (0, @AttrId_GivingPercentile, source.PersonId, source.NewValue, NEWID(), @CurrentRockDateTime, @CurrentRockDateTime);

    -- =============================================
    -- CLEAR STALE VALUES
    -- =============================================

    -- People who haven't given in the last 12 months should no longer have a bin/percentile.
    DELETE av
    FROM AttributeValue av
    JOIN dbo.Person p ON p.Id = av.EntityId
    WHERE av.AttributeId IN (@AttrId_GivingBin, @AttrId_GivingPercentile)
      AND p.GivingId IS NOT NULL
      AND p.GivingId <> ''
      AND p.RecordTypeValueId IS NOT NULL
      AND ( @RecordTypeId_Nameless IS NULL OR p.RecordTypeValueId <> @RecordTypeId_Nameless )
      AND ( @RecordTypeId_RestUser IS NULL OR p.RecordTypeValueId <> @RecordTypeId_RestUser )
      AND p.[Guid] <> @GiverAnonymousGuid
      AND NOT EXISTS ( SELECT 1 FROM #GivingData gd WHERE gd.PersonId = av.EntityId );

    DROP TABLE #GivingData;

END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE dbo.spGivingAutomation_UpdateGivingJourneyStages
    @CurrentRockDateTime DATETIME,
    @TransactionTypeIds dbo.IdList READONLY,                -- List of allowed TransactionTypeValueIds ( Defined in Giving Automation Configuration Block )
    @FinancialAccountIds dbo.IdList READONLY,               -- List of allowed FinancialAccounts ( Defined in Giving Automation Configuration Block )
    @NewGiverFirstGaveDays INT = 150,                       -- Max days since the first gift for someone to qualify for New Giver
    @NewGiverContributionCountBetweenMinimum INT = 1,       -- Minimum number of gifts for New Giver
    @NewGiverContributionCountBetweenMaximum INT = 5,       -- Maximum number of gifts for New Giver
    @ConsistentGiverLastGaveDays INT = 32,                  -- Maximum days since last gift to still be considered active for Consistent
    @ConsistentGiverMeanFrequency INT = 32,                 -- Max average days between gifts (last 2 years) to qualify for Consistent
    @OccasionalGiverLastGaveDays INT = 150,                 -- Maximum days since last gift to be considered Occasional/active but not consistent
    @OccasionalGiverMeanFrequency INT = 94,                 -- Max average days between gifts (last 2 years) to qualify for Occasional
    @LapsedGiverNoGiftDays INT = 150,                       -- Minimum days without a gift to be considered for Lapsed
    @LapsedGiverMeanFrequency INT = 100                     -- Max average days between gifts (last 2 years) to qualify for Lapsed
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @StartDate DATETIME = DATEADD(MONTH, -24, @CurrentRockDateTime);
    DECLARE @JourneyChangeDateValue VARCHAR(30) = CONVERT(VARCHAR(30), @CurrentRockDateTime, 126);

    DECLARE @AttrId_CurrentJourneyStage INT = (SELECT TOP 1 Id FROM Attribute WHERE [Guid] = '13C55AEA-6D88-4470-B3AE-EE5138F044DF');
    DECLARE @AttrId_PreviousJourneyStage INT = (SELECT TOP 1 Id FROM Attribute WHERE [Guid] = 'B35CE867-6017-484E-9EC7-AEB93CD4B2D8');
    DECLARE @AttrId_JourneyStageChangeDate INT = (SELECT TOP 1 Id FROM Attribute WHERE [Guid] = '8FFE3554-43F2-40D8-8803-446559D2B1F7');

    DECLARE @RecordTypeId_Nameless INT = (SELECT TOP 1 Id FROM DefinedValue WHERE [Guid] = '721300ED-1267-4DA0-B4F2-6C6B5B17B1C5'); -- PERSON_RECORD_TYPE_NAMELESS
    DECLARE @RecordTypeId_RestUser INT = (SELECT TOP 1 Id FROM DefinedValue WHERE [Guid] = 'E2261A84-831D-4234-9BE0-4D628BBE751E'); -- PERSON_RECORD_TYPE_RESTUSER
    DECLARE @GiverAnonymousGuid UNIQUEIDENTIFIER = '802235DC-3CA5-94B0-4326-AACE71180F48'; -- GIVER_ANONYMOUS
    DECLARE @AnonymousVisitorGuid UNIQUEIDENTIFIER = '7EBC167B-512D-4683-9D80-98B6BB02E1B9'; -- ANONYMOUS_VISITOR

    -- =============================================
    -- CALCULATIONS
    -- =============================================
    ;WITH EligiblePersons AS (
        SELECT
            p.Id AS PersonId,
            p.GivingId
        FROM dbo.Person p
        WHERE p.GivingId IS NOT NULL
            AND p.GivingId <> ''
            AND (@RecordTypeId_Nameless IS NULL OR p.RecordTypeValueId <> @RecordTypeId_Nameless)
            AND (@RecordTypeId_RestUser IS NULL OR p.RecordTypeValueId <> @RecordTypeId_RestUser)
            AND p.[Guid] <> @GiverAnonymousGuid
            AND p.[Guid] <> @AnonymousVisitorGuid
    ),

    EligibleGivingIds AS (
        SELECT DISTINCT GivingId
        FROM EligiblePersons
    ),

    RefundTotals AS (
        SELECT
            ftr.OriginalTransactionId,
            SUM(ftd.Amount) AS TotalRefundedAmount
        FROM dbo.FinancialTransactionRefund ftr
        JOIN dbo.FinancialTransactionDetail ftd ON ftd.TransactionId = ftr.Id
        GROUP BY ftr.OriginalTransactionId
    ),

    EligibleTransactions AS (
        SELECT
            p.GivingId,
            ft.TransactionDateTime
        FROM dbo.FinancialTransaction ft
        JOIN dbo.PersonAlias pa ON pa.Id = ft.AuthorizedPersonAliasId
        JOIN dbo.Person p ON p.Id = pa.PersonId
        LEFT JOIN RefundTotals rt ON rt.OriginalTransactionId = ft.Id
        WHERE ft.TransactionDateTime <= @CurrentRockDateTime
            
            -- 1. Transaction type filter
            AND ft.TransactionTypeValueId IN (SELECT Id FROM @TransactionTypeIds)

            /*
               2. Account filter -- include the transaction if it has AT LEAST ONE line item
               in one of the allowed financial accounts.

               NOTE:
               - A FinancialTransaction may have multiple FinancialTransactionDetail rows (line items).
               - Some of those line items may belong to accounts NOT in the allowed list.
               - The transaction is still included as long as ONE line item is in an allowed account.
            */
            AND EXISTS (
                SELECT 1
                FROM dbo.FinancialTransactionDetail ftd_account
                WHERE ftd_account.TransactionId = ft.Id
                  AND ftd_account.AccountId IN (SELECT Id FROM @FinancialAccountIds)
            )

            -- 3. Must have at least one positive detail (across ALL details, not just filtered accounts)
            AND EXISTS (
                SELECT 1
                FROM dbo.FinancialTransactionDetail ftd_pos
                WHERE ftd_pos.TransactionId = ft.Id
                  AND ftd_pos.Amount > 0
            )

            -- 4. Refund logic: exclude only FULLY REFUNDED transactions
            AND (
                -- No refunds at all... include
                NOT EXISTS ( SELECT 1 FROM dbo.FinancialTransactionRefund ftr0 WHERE ftr0.OriginalTransactionId = ft.Id )
                OR
                (
                    -- Sum of ALL original txns details + sum of ALL refund details != 0... not fully refunded.
                    (SELECT SUM(ftd_all.Amount)
                     FROM dbo.FinancialTransactionDetail ftd_all
                     WHERE ftd_all.TransactionId = ft.Id)
                    + ISNULL(rt.TotalRefundedAmount, 0.00) <> 0
                )
            )

            -- 5. Meets person record requirements (at least one eligible person exists for this GivingId)
            AND EXISTS ( SELECT 1 FROM EligibleGivingIds eg WHERE eg.GivingId = p.GivingId )
    ),

    GivingStats AS (
        SELECT
            elg.GivingId,
            MIN(et.TransactionDateTime) AS FirstGiftDate,
            MAX(et.TransactionDateTime) AS LastGiftDate,
            MIN(CASE WHEN et.TransactionDateTime >= @StartDate THEN et.TransactionDateTime END) AS FirstGiftDate24Months,
            SUM(CASE WHEN et.TransactionDateTime >= @StartDate THEN 1 ELSE 0 END) AS GiftCount24Months
        FROM EligibleGivingIds elg
        LEFT JOIN EligibleTransactions et ON et.GivingId = elg.GivingId
        GROUP BY elg.GivingId
    ),

    Calculations AS (
        SELECT
            GivingId,
            FirstGiftDate,
            LastGiftDate,
            ISNULL(GiftCount24Months, 0) AS GiftCount24Months,
            CASE
                WHEN FirstGiftDate IS NOT NULL THEN 1
                ELSE 0
            END AS HasGivenEver,
           
           /*
                1/11/2026 - MSE

                "Ghost Transaction" Logic:

                If the days since the last transaction is greater than the average (mean)
                interval between gifts over the last two years, we assume the giving
                pattern has slowed.

                We simulate a "ghost" transaction at the current date to adjust the mean.

                Calculation Logic:
                    - Current Mean Interval = (LastTxnDate - FirstTxnDate) / (TxnCount - 1)
                    - DaysSinceLastTxn = (@CurrentRockDateTime - LastTxnDate)

                If DaysSinceLastTxn > Current Mean:
                    Adjusted Mean = ((LastTxnDate - FirstTxnDate) + DaysSinceLastTxn) / (TxnCount)

                Simplifies to:
                    (@CurrentRockDateTime - FirstTxnDate) / TxnCount
            */
            CASE
                WHEN ISNULL(GiftCount24Months, 0) < 2 THEN NULL

                WHEN DATEDIFF(DAY, LastGiftDate, @CurrentRockDateTime) >
                     (DATEDIFF(DAY, FirstGiftDate24Months, LastGiftDate) * 1.0 / (ISNULL(GiftCount24Months, 0) - 1))
                THEN DATEDIFF(DAY, FirstGiftDate24Months, @CurrentRockDateTime) * 1.0 / ISNULL(GiftCount24Months, 0)

                /*
                    Standard Calculation:
                        - Time since last transaction is within historical average interval.
                        - Mean = (LastTxnDate - FirstTxnDate) / (TxnCount - 1)
                */
                ELSE DATEDIFF(DAY, FirstGiftDate24Months, LastGiftDate) * 1.0 / (ISNULL(GiftCount24Months, 0) - 1)
            END AS MeanFrequency
        FROM GivingStats
    ),

    JourneyCalculations AS (
        SELECT
            GivingId,

            /*
                1/11/2026 - MSE

                Journey stage classification is computed once per GivingId, and all individuals associated 
                with that GivingId are assigned the same stage. With these updates to stage classification logic, 
                we should no longer encounter "unclassified" cases.

                Previous approach:
                    - Relied on ALL-TIME transaction data and MEDIAN giving frequency.
                    - Calculating the median over many years often masked recent changes in giving behavior.
                    
                    - Example: A donor who gave infrequently for many years but recently began giving monthly 
                      could take considerable time to reach the CONSISTENT category, since their historical giving habits 
                      keep the all-time median elevated, effectively slowing their progression and delaying recognition 
                      of their change in heart and behavior.
                    
                    - Gaps in the previous stage classification logic left a noticeable number of individuals unclassified,
                      not due to having no transactions, but because they didn't fall into any stage.
                    - Reference: https://github.com/SparkDevNetwork/Rock/issues/6419
            */
            CASE
                -- 0. NON-GIVER: No qualifying gifts.
                WHEN HasGivenEver = 0 THEN 0
                
                -- 1. NEW: First qualifying gift is within @NewGiverFirstGaveDays AND gift count is within configured range.
                WHEN FirstGiftDate IS NOT NULL
                     AND DATEDIFF(DAY, FirstGiftDate, @CurrentRockDateTime) <= @NewGiverFirstGaveDays
                     AND GiftCount24Months BETWEEN @NewGiverContributionCountBetweenMinimum AND @NewGiverContributionCountBetweenMaximum
                THEN 1
                
                -- 2. CONSISTENT: Last gift within @ConsistentGiverLastGaveDays AND MeanFrequency <= @ConsistentGiverMeanFrequency.
                WHEN DATEDIFF(DAY, LastGiftDate, @CurrentRockDateTime) <= @ConsistentGiverLastGaveDays
                     AND MeanFrequency <= @ConsistentGiverMeanFrequency
                THEN 2
                
                -- 3. OCCASIONAL: Last gift within @OccasionalGiverLastGaveDays AND MeanFrequency <= @OccasionalGiverMeanFrequency.
                WHEN DATEDIFF(DAY, LastGiftDate, @CurrentRockDateTime) <= @OccasionalGiverLastGaveDays
                     AND MeanFrequency <= @OccasionalGiverMeanFrequency
                THEN 3
                
                -- 4. LAPSED: Last Gift > @LapsedGiverNoGiftDays days AND Mean Frequency < @LapsedGiverMeanFrequency.
                WHEN DATEDIFF(DAY, LastGiftDate, @CurrentRockDateTime) > @LapsedGiverNoGiftDays 
                     AND MeanFrequency < @LapsedGiverMeanFrequency 
                THEN 4
                
                -- 5. FORMER: Catch-all for any remaining givers not classified above.
                ELSE 5
            END AS NewJourneyStage
        FROM Calculations
    )

    -- =============================================
    -- OUTPUT & MERGE INTO ATTRIBUTE VALUE
    -- =============================================

    -- This is only populated with people who's journey stage has changed.
    SELECT
        elg.PersonId,
        jc.NewJourneyStage,
        av.Value AS CurrentStageValue,
        TRY_CAST(av.Value AS INT) AS CurrentStageInt
    INTO #JourneyUpdates
    FROM JourneyCalculations jc
    JOIN EligiblePersons elg ON elg.GivingId = jc.GivingId
    LEFT JOIN dbo.AttributeValue av ON av.EntityId = elg.PersonId AND av.AttributeId = @AttrId_CurrentJourneyStage
    WHERE
        jc.NewJourneyStage != ISNULL(TRY_CAST(av.Value AS INT), -1);

    CREATE CLUSTERED INDEX IX_PersonId ON #JourneyUpdates (PersonId);

    -- Previous Journey Stage
    MERGE dbo.AttributeValue AS target
    USING (
        SELECT PersonId, ISNULL(CurrentStageValue, '') AS CurrentStageValue
        FROM #JourneyUpdates
    ) AS source
    ON target.EntityId = source.PersonId AND target.AttributeId = @AttrId_PreviousJourneyStage
    WHEN MATCHED THEN
        UPDATE SET Value = source.CurrentStageValue, ModifiedDateTime = @CurrentRockDateTime
    WHEN NOT MATCHED BY TARGET AND source.CurrentStageValue <> '' THEN
        INSERT (IsSystem, AttributeId, EntityId, Value, [Guid], CreatedDateTime, ModifiedDateTime)
        VALUES (0, @AttrId_PreviousJourneyStage, source.PersonId, source.CurrentStageValue, NEWID(), @CurrentRockDateTime, @CurrentRockDateTime);
    
    -- Current Journey Stage
    MERGE dbo.AttributeValue AS target
    USING (
        SELECT PersonId, CAST(NewJourneyStage AS VARCHAR(10)) AS NewStageValue
        FROM #JourneyUpdates
    ) AS source
    ON target.EntityId = source.PersonId AND target.AttributeId = @AttrId_CurrentJourneyStage
    WHEN MATCHED THEN
        UPDATE SET Value = source.NewStageValue, ModifiedDateTime = @CurrentRockDateTime
    WHEN NOT MATCHED BY TARGET THEN
        INSERT (IsSystem, AttributeId, EntityId, Value, [Guid], CreatedDateTime, ModifiedDateTime)
        VALUES (0, @AttrId_CurrentJourneyStage, source.PersonId, source.NewStageValue, NEWID(), @CurrentRockDateTime, @CurrentRockDateTime);
    
    -- Journey Stage Change Date
    MERGE dbo.AttributeValue AS target
    USING #JourneyUpdates AS source
    ON target.EntityId = source.PersonId AND target.AttributeId = @AttrId_JourneyStageChangeDate
    WHEN MATCHED THEN
        UPDATE SET Value = @JourneyChangeDateValue, ModifiedDateTime = @CurrentRockDateTime
    WHEN NOT MATCHED BY TARGET THEN
        INSERT (IsSystem, AttributeId, EntityId, Value, [Guid], CreatedDateTime, ModifiedDateTime)
        VALUES (0, @AttrId_JourneyStageChangeDate, source.PersonId, @JourneyChangeDateValue, NEWID(), @CurrentRockDateTime, @CurrentRockDateTime);
    
    -- Output
    SELECT COUNT(*) AS ChangesCount FROM #JourneyUpdates;
    
    DROP TABLE #JourneyUpdates;
END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*
<doc>
    <summary>
        This stored procedure updates the peer network for an individual's following.
    </summary>
    <remarks>
        FOLLOWING PEER NETWORK NOTES
        1.  Any already-existing peer network connections will be updated with a current timestamp.
        2.  Any missing connections will be added.
        3.  A static relationship score of 5 will be enforced for all such connections.
        4.  Any no-longer-matching connections will be deleted (if an individual is no longer following someone they
            used to follow).
    </remarks>
    <code>
        EXEC [dbo].[spPeerNetwork_UpdateFollowing]
    </code>
</doc>
*/

CREATE PROCEDURE [dbo].[spPeerNetwork_UpdateFollowing]
AS
BEGIN

    DECLARE @FollowingScore INT = 5;

    DECLARE @PersonAliasEntityId INT = (SELECT TOP 1 [Id] FROM [EntityType] WHERE [Guid] = '90F5E87B-F0D5-4617-8AE9-EB57E673F36F');
    DECLARE @FollowingConnectionTypeValueId INT = (SELECT TOP 1 [Id] FROM [DefinedValue] WHERE [Guid] = '84E0360E-0828-E5A5-4BCC-F3113BE338A1');

    ;WITH FollowingDataset AS (
        SELECT 
            followerP.[Id] AS [FollowerPersonId]
            , followingP.[Id] AS [FollowingPersonId]
            , MIN(f.[CreatedDateTime]) AS [RelationshipStartDate]
        FROM [dbo].[Following] f
            INNER JOIN [PersonAlias] followingPA ON followingPA.[Id] = f.[EntityId]
            INNER JOIN [Person] followingP ON followingP.[Id] = followingPA.[PersonId]
            INNER JOIN [PersonAlias] followerPA ON followerPA.[Id] = f.[PersonAliasId]
            INNER JOIN [Person] followerP ON followerP.[Id] = followerPA.[PersonId]
        WHERE [EntityTypeId] = @PersonAliasEntityId
            AND (
                [PurposeKey] IS NULL
                OR [PurposeKey] = ''
            )
        GROUP BY followerP.[Id]
            , followingP.[Id]
    )

    MERGE [PeerNetwork] AS t
    USING [FollowingDataset] AS s
    ON t.[TargetPersonId] = s.[FollowingPersonId]
        AND t.[SourcePersonId] = s.[FollowerPersonId]
        AND t.[RelationshipTypeValueId] = @FollowingConnectionTypeValueId
    WHEN MATCHED THEN
        -- Update each matching [PeerNetwork] record with a current time stamp and ensure they have the expected following score.
        UPDATE SET t.[RelationshipStartDate] = s.[RelationshipStartDate]
            , t.[LastUpdateDateTime] = GETDATE()
            , t.[RelationshipScore] = @FollowingScore
            , t.[RelationshipScoreLastUpdateValue] = @FollowingScore
            , t.[RelationshipTrend] = 0
    WHEN NOT MATCHED BY TARGET THEN
        -- Add new [PeerNetwork] records for following relationships not yet reflected in this table.
        INSERT (
            [RelationshipTypeValueId]
            , [RelationshipStartDate]
            , [RelationshipScore]
            , [RelationshipScoreLastUpdateValue]
            , [RelationshipTrend]
            , [LastUpdateDateTime]
            , [SourcePersonId]
            , [TargetPersonId]
        )
        VALUES (
            @FollowingConnectionTypeValueId     -- [RelationshipTypeValueId]
            , s.[RelationshipStartDate]         -- [RelationshipStartDate]
            , @FollowingScore                   -- [RelationshipScore]
            , 0                                 -- [RelationshipScoreLastUpdateValue]
            , 1                                 -- [RelationshipTrend]
            , GETDATE()                         -- [LastUpdateDateTime]
            , s.[FollowerPersonId]              -- [SourcePersonId]
            , s.[FollowingPersonId]             -- [TargetPersonId]
        )
    WHEN NOT MATCHED BY SOURCE AND t.[RelationshipTypeValueId] = @FollowingConnectionTypeValueId THEN
        -- Remove any preexisting [PeerNetwork] records that no longer represent active following relationships.
        DELETE;

END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*
<doc>
    <summary>
        This stored procedure updates the peer network for groups.
    </summary>
    <remarks>
        GROUP PEER NETWORK NOTES
        1.  The group processing will have 3 phases:
            a. Update the peer network connections in the PeerNetwork table.
            b. Recalc the relationship score for each connection with logic for time adjusting. We need to do this as a
               separate step as some of the individuals who previously had peer connections are no longer in those groups.
            c. Clean-up
                - A person could be in a group multiple times (with different roles). In these cases we'll delete the
                  lowest peer network relationship score for that person.
                - Delete all group connections whose scores have gone below 0.
        2.  We only want to connect people who were in the group at the same time. We therefore need to look at the
            archive and inactive dates to ensure they are before the date the source person was added to the group.
        3.  When a person is deleted from a group we don't want to delete their peer network. Instead we want to slowly
            decrease the relationship score until it reaches 0.
        4.  There's logic in here to handle duplicate Group > Person > Roles. This can happen if a person is unarchived.
            The unarchive process could create a new record in the GroupMember table. This is being changed in v17 to
            prevent this, but I think we should keep the logic just in case. To deal with this we set the RelationshipEndDate
            to be 12/31/9999 when the relationship is active (this helps us choose the correct one as null does not work
            with MAX()). In the MERGE we'll convert it back to a null.
    </remarks>
    <code>
        EXEC [dbo].[spPeerNetwork_UpdateGroupConnections]
    </code>
</doc>
*/

CREATE PROCEDURE [dbo].[spPeerNetwork_UpdateGroupConnections]
AS
BEGIN

    DECLARE @GroupMemberConnectionTypeValueId INT = (SELECT TOP 1 [Id] FROM [DefinedValue] WHERE [Guid] = 'CB51DC46-FBDB-43DA-B7F3-60E7C6E70F40')

    /*
        STEP 1: MERGE (ADD/UPDATE/DELETE) PEER NETWORK CONNECTIONS
    */

    -- This creates a dataset of all relevant group members. We'll use this to cross join to get a matrix of relationships.
    ;WITH GroupMemberDataSet AS (
        SELECT
            g.[Id] AS [GroupId]
            , gm.[PersonId] AS [PersonId]
            , gm.[GroupRoleId]
            , gm.[DateTimeAdded] AS [GroupStartDateTime]
            , gm.[ArchivedDateTime]
            , gm.[InactiveDateTime]
            , gt.[Id] AS [GroupTypeId]
            , gtr.[IsLeader]
            , gm.[IsArchived]
            , gm.[GroupMemberStatus]
            , CASE 
                WHEN gm.[IsArchived] = 1 THEN gm.[ArchivedDateTime]
                WHEN gm.[GroupMemberStatus] = 0 THEN gm.[InactiveDateTime]
                ELSE '12/31/9999'
              END AS [GroupMemberInactiveDate]
        FROM [Group] g
            INNER JOIN [GroupMember] gm ON gm.[GroupId] = g.[Id]
            INNER JOIN [GroupType] gt ON gt.[Id] = g.[GroupTypeId]
            INNER JOIN [GroupTypeRole] gtr ON gtr.[Id] = gm.[GroupRoleId]
        WHERE gt.[IsPeerNetworkEnabled] = 1
            AND (
                -- Either the group hasn't overridden the group type's strength and the group type's strength is not "None",
                (g.[RelationshipStrengthOverride] IS NULL AND gt.[RelationshipStrength] != 0)
                -- or the group has overridden with something other than "None".
                OR g.[RelationshipStrengthOverride] != 0
            )
            AND gtr.[IsExcludedFromPeerNetwork] != 1 -- Ignore people in roles that have disabled peer networks.
    ),

    GroupMemberConnectionDataset AS (
        SELECT
            [SourcePersonId]
            , [TargetPersonId]
            , [GroupId]
            , [SourceRoleId]
            , MIN([RelationshipStartDate]) AS [RelationshipStartDate]
            , MAX([RelationshipEndDate]) AS [RelationshipEndDate]
            , MIN([Caption]) AS [Caption]
        FROM (

            SELECT
                s.[PersonId] AS [SourcePersonId]
                , s.[GroupId]
                , s.[GroupRoleId] AS [SourceRoleId]
                , s.[GroupTypeId]
                , s.[IsLeader] AS [SourceIsLeader]
                , t.[TargetPersonId]
                , t.[TargetRoleId]
                , t.[TargetIsLeader]
                , g.[Name] AS [Caption]
                -- The date that the relationship started. This is the newer date that someone was added to the group.
                , CASE
                    WHEN s.[GroupStartDateTime] < t.[GroupStartDateTime] THEN CAST(t.[GroupStartDateTime] AS DATE)
                    ELSE CAST(s.[GroupStartDateTime] AS DATE)
                  END AS [RelationshipStartDate]

                -- The date that the relationship ended.
                , CASE
                    -- If the group is inactive then return the inactivate date of the group.
                    WHEN g.[IsActive] = 0 THEN g.[InactiveDateTime]
                    -- If the group is archived then return the archived date time.
                    WHEN g.[IsArchived] = 1 THEN g.[ArchivedDateTime]
                    -- Both individuals are active so return the max value.
                    WHEN t.[GroupMemberInactiveDate] = '12/31/9999' AND s.[GroupMemberInactiveDate] = '12/31/9999' THEN '12/31/9999'
                    -- If either or both are inactive then we'll take the oldest non-null inactive date since they left first.
                    WHEN t.[GroupMemberInactiveDate] != '12/31/9999' OR s.[GroupMemberInactiveDate] != '12/31/9999' THEN
                        CASE
                            WHEN t.[GroupMemberInactiveDate] = '12/31/9999' THEN s.[GroupMemberInactiveDate]
                            WHEN s.[GroupMemberInactiveDate] = '12/31/9999' THEN t.[GroupMemberInactiveDate]
                            WHEN t.[GroupMemberInactiveDate] < s.[GroupMemberInactiveDate] THEN t.[GroupMemberInactiveDate]
                            ELSE s.[GroupMemberInactiveDate]
                        END
                    ELSE '12/31/9999'
                  END AS [RelationshipEndDate]

            FROM [GroupMemberDataSet] s
                INNER JOIN [Group] g ON g.[Id] = s.[GroupId]
                CROSS APPLY (
                    -- For each group member [s], get all other group members [t].
                    SELECT
                        gdTarget.[PersonId] AS [TargetPersonId]
                        , gdTarget.[GroupStartDateTime] AS [GroupStartDateTime]
                        , gdTarget.[GroupRoleId] AS [TargetRoleId]
                        , gdTarget.[IsLeader] AS [TargetIsLeader]
                        , gdTarget.[GroupMemberInactiveDate]
                    FROM [GroupMemberDataSet] gdTarget
                    WHERE s.[PersonId] <> gdTarget.[PersonId]
                        AND s.[GroupId] = gdTarget.[GroupId]
                ) t

            WHERE
                -- We want to exclude people who were not active in the group at the same time. Active relationships will have a GroupMemberInactiveDate of '12/31/9999'.
                s.[GroupStartDateTime] <= t.[GroupMemberInactiveDate]
                AND t.[GroupStartDateTime] <= s.[GroupMemberInactiveDate]
                AND s.[GroupMemberInactiveDate] >= t.[GroupStartDateTime]
                AND t.[GroupMemberInactiveDate] >= s.[GroupStartDateTime]
        ) x
        -- The group by below is needed as there are duplicate people in the same group with the same role. This should not happen, but it does.
        GROUP BY [SourcePersonId], [TargetPersonId], [GroupId], [SourceRoleId]
    )

    MERGE [PeerNetwork] AS t
    USING [GroupMemberConnectionDataset] AS s
    ON
        t.[TargetPersonId] = s.[TargetPersonId]
        AND t.[SourcePersonId] = s.[SourcePersonId]
        AND t.[RelatedEntityId] = s.[GroupId]
        AND t.[ClassificationEntityId] = s.[SourceRoleId]
        AND t.[RelationshipTypeValueId] = @GroupMemberConnectionTypeValueId
    WHEN MATCHED THEN
        -- Update each matching [PeerNetwork] record to reflect the group members' last-calculated relationship start and end dates.
        UPDATE SET t.[RelationshipEndDate] =
              CASE
                WHEN s.[RelationshipEndDate] = '12/31/9999' THEN NULL
                ELSE s.[RelationshipEndDate]
              END
            , t.[RelationshipStartDate] = s.[RelationshipStartDate]
    WHEN NOT MATCHED BY TARGET THEN
        -- Add new [PeerNetwork] records for group members not yet reflected in this table.
        INSERT (
            [RelationshipTypeValueId]
            , [RelationshipStartDate]
            , [RelationshipEndDate]
            , [RelationshipScore]
            , [RelationshipScoreLastUpdateValue]
            , [RelationshipTrend]
            , [LastUpdateDateTime]
            , [SourcePersonId]
            , [TargetPersonId]
            , [Caption]
            , [RelatedEntityId]
            , [ClassificationEntityId]
        )
        VALUES (
            @GroupMemberConnectionTypeValueId                           -- [RelationshipTypeValueId]
            , s.[RelationshipStartDate]                                 -- [RelationshipStartDate]
            , CASE
                WHEN s.[RelationshipEndDate] = '12/31/9999' THEN NULL   -- [RelationshipEndDate]
                ELSE s.[RelationshipEndDate]
              END
            , 0                                                         -- [RelationshipScore]
            , 0                                                         -- [RelationshipScoreLastUpdateValue]
            , 0                                                         -- [RelationshipTrend]
            , GETDATE()                                                 -- [LastUpdateDateTime]
            , s.[SourcePersonId]                                        -- [SourcePersonId]
            , s.[TargetPersonId]                                        -- [TargetPersonId]
            , s.[Caption]                                               -- [Caption]
            , s.[GroupId]                                               -- [RelatedEntityId]
            , s.[SourceRoleId]                                          -- [ClassificationEntityId]
        )
    WHEN NOT MATCHED BY SOURCE AND t.[RelationshipTypeValueId] = @GroupMemberConnectionTypeValueId AND t.[RelationshipEndDate] IS NULL THEN
        -- Start the relationship score decay process by setting these members' relationship end date to right now.
        UPDATE SET t.[RelationshipEndDate] = GETDATE();

    /*
        STEP 2: UPDATE RELATIONSHIP SCORING
    */

    /*  NOTES
        The calculation for Relationship Score is

            - RelationshipGrowthAdjustmentMultiplier: This field determines the monthly growth rate. If the relationship
              is active, 10% of the base score is added each month. If the relationship is inactive, 20% of the base
              score is subtracted each month.
            - RelationshipGrowthEnabledMultiplier: This determines if the relationship should grow over time. It will be
              a 1 when enabled and 0 if not.
            - RelationshipGrowthDate: This date is used to calculate growth. When the relationship is active, it represents
              the start date. When the relationship is inactive, it is the inactivation date.
    */

    UPDATE [PeerNetwork]
    SET
        [PeerNetwork].[RelationshipScore] =
        CASE
            -- This could happen if the source or target group is deleted.
            WHEN s.[RelationshipScore] IS NULL THEN 0
            ELSE s.[RelationshipScore]
        END
        , [PeerNetwork].[RelationshipScoreLastUpdateValue] = s.[PreviousRelationshipScore]
        , [PeerNetwork].[LastUpdateDateTime] = GETDATE()
        , [PeerNetwork].[RelationshipTrend] =
            CASE
                WHEN [PeerNetwork].[RelationshipScore] > s.[RelationshipScore] THEN -1
                WHEN [PeerNetwork].[RelationshipScore] < s.[RelationshipScore] THEN 1
                ELSE 0
            END
    FROM
    (
        -- [Re-]score each "Group Connection" [PeerNetwork] record based on group/group type configuration & members' roles within the group.
        SELECT
            x.*
            , CASE
                WHEN [IsRelationshipGrowthEnabled] = 1 OR [RelationshipGrowthAdjustmentMultiplier] < 0 THEN
                    -- If relationship growth is enabled OR it's time to start subtracting this member's score, factor in the growth[/decay] adjustment and role-based multipliers.
                    CASE
                        WHEN [SourceIsLeader] = 1 AND [TargetIsLeader] = 1 THEN
                            ([RelationshipStrength] + (DATEDIFF(m, [RelationshipGrowthDate], GETDATE()) * [RelationshipGrowthAdjustmentMultiplier])) * [LeaderToLeaderRelationshipMultiplier]
                        WHEN [SourceIsLeader] = 1 AND [TargetIsLeader] = 0 THEN
                            ([RelationshipStrength] + (DATEDIFF(m, [RelationshipGrowthDate], GETDATE()) * [RelationshipGrowthAdjustmentMultiplier])) * [LeaderToNonLeaderRelationshipMultiplier]
                        WHEN [SourceIsLeader] = 0 AND [TargetIsLeader] = 1 THEN
                            ([RelationshipStrength] + (DATEDIFF(m, [RelationshipGrowthDate], GETDATE()) * [RelationshipGrowthAdjustmentMultiplier])) * [NonLeaderToLeaderRelationshipMultiplier]
                        WHEN [SourceIsLeader] = 0 AND [TargetIsLeader] = 0 THEN
                            ([RelationshipStrength] + (DATEDIFF(m, [RelationshipGrowthDate], GETDATE()) * [RelationshipGrowthAdjustmentMultiplier])) * [NonLeaderToNonLeaderRelationshipMultiplier]
                    END
                ELSE
                    -- If relationship growth is disabled, assign a static score, adjusted only by the role-based multipliers.
                    CASE
                        WHEN [SourceIsLeader] = 1 AND [TargetIsLeader] = 1 THEN [RelationshipStrength] * [LeaderToLeaderRelationshipMultiplier]
                        WHEN [SourceIsLeader] = 1 AND [TargetIsLeader] = 0 THEN [RelationshipStrength] * [LeaderToNonLeaderRelationshipMultiplier]
                        WHEN [SourceIsLeader] = 0 AND [TargetIsLeader] = 1 THEN [RelationshipStrength] * [NonLeaderToLeaderRelationshipMultiplier]
                        WHEN [SourceIsLeader] = 0 AND [TargetIsLeader] = 0 THEN [RelationshipStrength] * [NonLeaderToNonLeaderRelationshipMultiplier]
                    END
              END AS [RelationshipScore]
        FROM (
            -- Get all existing "Group Connection" [PeerNetwork] records, along with their group/group type configuration & members' roles.
            SELECT
                pn.[SourcePersonId]
                , pn.[TargetPersonId]
                , pn.[RelatedEntityId]
                , pn.[ClassificationEntityId]
                , pn.[RelationshipScore] AS [PreviousRelationshipScore]

                , CASE
                    WHEN pn.[RelationshipEndDate] IS NOT NULL THEN pn.[RelationshipEndDate]
                    ELSE pn.[RelationshipStartDate]
                  END AS [RelationshipGrowthDate]

                , CASE WHEN pn.[RelationshipEndDate] IS NULL
                    THEN .1
                    ELSE -.2
                  END AS [RelationshipGrowthAdjustmentMultiplier]

                , CASE
                    WHEN g.[RelationshipGrowthEnabledOverride] IS NOT NULL THEN g.[RelationshipGrowthEnabledOverride]
                    ELSE gt.[RelationshipGrowthEnabled]
                  END AS [IsRelationshipGrowthEnabled]

                , CASE
                    WHEN g.[RelationshipStrengthOverride] IS NOT NULL THEN g.[RelationshipStrengthOverride]
                    ELSE gt.[RelationshipStrength]
                  END AS [RelationshipStrength]

                , CASE
                    WHEN g.[LeaderToLeaderRelationshipMultiplierOverride] IS NOT NULL THEN g.[LeaderToLeaderRelationshipMultiplierOverride]
                    ELSE gt.[LeaderToLeaderRelationshipMultiplier]
                  END AS [LeaderToLeaderRelationshipMultiplier]

                , CASE
                    WHEN g.[LeaderToNonLeaderRelationshipMultiplierOverride] IS NOT NULL THEN g.[LeaderToNonLeaderRelationshipMultiplierOverride]
                    ELSE gt.[LeaderToNonLeaderRelationshipMultiplier]
                  END AS [LeaderToNonLeaderRelationshipMultiplier]

                , CASE
                    WHEN g.[NonLeaderToLeaderRelationshipMultiplierOverride] IS NOT NULL THEN g.[NonLeaderToLeaderRelationshipMultiplierOverride]
                    ELSE gt.[NonLeaderToLeaderRelationshipMultiplier]
                  END AS [NonLeaderToLeaderRelationshipMultiplier]

                , CASE
                    WHEN g.[NonLeaderToNonLeaderRelationshipMultiplierOverride] IS NOT NULL THEN g.[NonLeaderToNonLeaderRelationshipMultiplierOverride]
                    ELSE gt.[NonLeaderToNonLeaderRelationshipMultiplier]
                  END AS [NonLeaderToNonLeaderRelationshipMultiplier]

                , ( SELECT TOP 1 [IsLeader]
                    FROM [GroupTypeRole] tgtr
                        INNER JOIN [GroupMember] tgm
                            ON tgm.[GroupRoleId] = tgtr.[Id]
                            AND tgm.[PersonId] = pn.[TargetPersonId]
                    ORDER BY tgtr.[IsLeader] DESC
                  ) AS [TargetIsLeader]

                , gtr.[IsLeader] AS [SourceIsLeader]
            FROM [PeerNetwork] pn
                LEFT OUTER JOIN [Group] g ON g.[Id] = pn.[RelatedEntityId]
                LEFT OUTER JOIN [GroupTypeRole] gtr ON gtr.[Id] = pn.[ClassificationEntityId]
                LEFT OUTER JOIN [GroupType] gt ON gt.[Id] = g.[GroupTypeId]
            WHERE
                pn.[RelationshipTypeValueId] =  @GroupMemberConnectionTypeValueId
        ) x
    ) s
    WHERE
        s.[SourcePersonId] = [PeerNetwork].[SourcePersonId]
        AND s.[TargetPersonId] = [PeerNetwork].[TargetPersonId]
        AND s.[RelatedEntityId] = [PeerNetwork].[RelatedEntityId]
        AND s.[ClassificationEntityId] = [PeerNetwork].[ClassificationEntityId]
        AND [PeerNetwork].[RelationshipTypeValueId] = @GroupMemberConnectionTypeValueId;

    /*
        STEP 3: CLEAN-UP
    */

    -- Delete relationships that are less than 0.
    DELETE FROM [PeerNetwork]
    WHERE [RelationshipScore] <= 0;

    -- Delete duplicate peer networks (note this is a global delete and should probably be added as a separate procedure when done).
    ;WITH PeerNetworkDuplicates AS (
        SELECT
            [SourcePersonId]
            , [TargetPersonId]
            , [RelationshipStartDate]
            , [RelationshipTypeValueId]
            , [RelatedEntityId]
            , [ClassificationEntityId]
            , ROW_NUMBER() OVER( PARTITION BY [SourcePersonId]
                                     , [TargetPersonId]
                                     , [RelationshipTypeValueId]
                                     , [RelatedEntityId]
                                     , [ClassificationEntityId] 
                                 ORDER BY [RelationshipScore], [RelationshipStartDate] ) AS [DuplicateCount]
        FROM [PeerNetwork] )

    DELETE FROM PeerNetworkDuplicates WHERE [DuplicateCount] > 1;

END
GO
SET ANSI_NULLS ON
GO
